window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-pediatria-ped-2"]={"block":"medcurso:medcurso-pediatria-ped-2","label":"Medcurso · PED 2","count":431,"questions":[{"id":"medcurso-pediatria-ped-2-343780","number":"343780","sourceNumber":"343780","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A partir dos 6 meses de idade da criança, recomenda-se a introdução de alimentos\ncomplementares, uma vez que após esse período o leite materno sozinho não é mais capaz de\nsuprir as necessidades nutricionais do lactente. A respeito da alimentação complementar marque a\nresposta correta.","options":{"A":"A papa principal deve ser oferecida após o 4º mês de vida.","B":"É comum a criança rejeitar alimentos que não lhe são familiares, portanto, são necessárias em\nmédia oito a dez exposições para uma plena aceitação.","C":"Os lipídeos devem assegurar 55% da energia total da alimentação do lactente após 6 meses de\nvida.","D":"Inicialmente os alimentos devem ser ofertados batidos no liquidificador para que não haja risco\nde engasgos."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343786","number":"343786","sourceNumber":"343786","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente de 3 meses de idade, nascido a termo com 3.100g, em aleitamento materno\nexclusivo, previamente hígido deve receber qual das opções abaixo para suplementação de\nvitaminas:","options":{"A":"Vitamina D em dose diária de 600UI para prevenção de raquitismo.","B":"Vitamina C em dose diária de 200mg/dia para prevenção de escorbuto.","C":"Vitamina A em dose de 100.000 UI/mês para prevenção de xerofaltamia.","D":"Vitamina D em dose diária de 400UI para prevenção de raquitismo."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343791","number":"343791","sourceNumber":"343791","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente nascido de parto a termo, pesando 3.500g, medindo 49cm e com perímetro\ncefálico de 34cm, deverá ter quais medidas antropométricas aos 4 meses de idade?","options":{"A":"6.300g; 60cm; 41cm.","B":"5.500g; 53cm; 36cm.","C":"8.000g; 70cm; 45cm.","D":"5.900g; 53cm; 41cm."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343792","number":"343792","sourceNumber":"343792","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente de 6 meses de idade, comparece a Unidade Básica da Saúde para realizar\nconsulta de puericultura. Quais devem ser os marcos do desenvolvimento que surgem nessa\nidade?","options":{"A":"Sorriso social, acompanhar objetos com o olhar e sustentação da cabeça.","B":"Levar as mãos na linha média, sorriso social, sentar com apoio.","C":"Transferir objetos de uma mão para outra, levantar a cabeça em decúbito ventral e acompanhar\nos objetos com o olhar.","D":"Sentar com apoio, levantar a cabeça em decúbito ventral e balbuciar."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-345495","number":"345495","sourceNumber":"345495","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Sobre puberdade precoce, é CORRETO afirmar que:","options":{"A":"Ocorre quando há aparecimento de pelos pubianos antes dos 7 anos no sexo feminino.","B":"Pode ocorrer devido a tumor de células de Leydig ou a gonadoblastoma.","C":"Pode ocorrer se houver ativação do eixo hipotalâmico hipofisário.","D":"É caracterizada no sexo masculino por aumento do volume testicular abaixo de 10 anos de\nidade."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-283290","number":"283290","sourceNumber":"283290","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considerando a orientação da Sociedade Brasileira de Pediatria, com relação à\nalimentação da criança no primeiro ano de vida, assinale a alternativa CORRETA:","options":{"A":"Devemos oferecer suco de fruta natural, sem adição de açucares ou adoçantes.","B":"O aleitamento materno deve ser exclusivo ate o 4º mês de vida, sem necessidade de oferecer\nágua, chás ou qualquer outro alimento.","C":"Na transição alimentar a papa principal pode ser liquidificada ou processada devendo-se evitar o\nsal e utilizando a gordura, sob a forma de óleo vegetal.","D":"Em média, a criança precisa ser exposta a um novo alimento de 8 a 10 vezes para que o aceite\nbem."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-283297","number":"283297","sourceNumber":"283297","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação às características da adolescência normal, marque a alternativa\nCORRETA:","options":{"A":"O crescimento dos membros inferiores e do tronco é responsável pelo aumento da estatura do\nadolescente, sendo esse processo uniforme nessa fase.","B":"A primeira manifestação de puberdade no sexo feminino é a telarca, que pode ser unilateral,\ninicialmente, ocorrendo entre 8 a 13 anos.","C":"O estirão puberal ocorre primeiramente nos meninos, em torno de 9,5 anos de idade e 2 anos\nmais tarde nas meninas.","D":"O ganho de peso no sexo masculino é resultante da deposição de gordura, devido a ação de\ntestosterona, esse hormônio também é responsável pelo aumento da capacidade física nessa fase\nda vida."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-283301","number":"283301","sourceNumber":"283301","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A síndrome de Down é a anomalia cromossômica mais comum em recém-nascidos\nvivos e a forma mais frequente de deficiência\nintelectual causada por alteração cromossômica.\nQuais das alterações dismórficas NÂO são caraterísticas desta síndrome:","options":{"A":"Braquicefalia.","B":"Frouxidão ligamentar.","C":"Mãos largas e curtas e vínculo palmar transverso (prega simiesca).","D":"Luxação de cristalino."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-291790","number":"291790","sourceNumber":"291790","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menina, 8 meses de idade, é levada à Unidade Básica de Saúde, UBS, para consulta\nde rotina. Nasceu de parto natural a termo,\npesando 3.300g; medindo 49cm e com Perímetro\nCefálico medindo 34cm. Atualmente pesa 8.000g e mede 67,5cm (escore z: em ambos, entre -1 e\n\n+1). Está em aleitamento materno exclusivo. Considerando o parâmetro ?escore z?, adotado pela\nOMS, indique a classificação correta para o peso e a estatura dessa lactente.","options":{"A":"Ganho de peso e de estatura adequados.","B":"Ganho de peso e crescimento inadequados.","C":"Ganho de peso adequado e crescimento inadequado.","D":"Ganho de peso inadequado e crescimento adequado."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-291791","number":"291791","sourceNumber":"291791","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menina, 8 meses de idade, é levada à Unidade Básica de Saúde, UBS, para consulta\nde rotina. Nasceu de parto natural a termo,\npesando 3.300g; medindo 49cm e com Perímetro\nCefálico medindo 34cm. Atualmente pesa 8.000g e mede 67,5cm (escore z: em ambos, entre -1 e\n\n+1). Está em aleitamento materno exclusivo. Considerando a velocidade de crescimento esperada\npara o Perímetro Cefálico, especifique\nqual deve ser, aproximadamente, o valor atual, nessa\ncriança.","options":{"A":"40 cm","B":"42 cm","C":"44 cm","D":"46 cm"},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-291792","number":"291792","sourceNumber":"291792","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menina, 8 meses de idade, é levada à Unidade Básica de Saúde, UBS, para consulta\nde rotina. Nasceu de parto natural a termo,\npesando 3.300g; medindo 49cm e com Perímetro\nCefálico medindo 34cm. Atualmente pesa 8.000g e mede 67,5cm (escore z: em ambos, entre -1 e\n\n+1). Está em aleitamento materno exclusivo. Considerando que essa criança apresenta\ndesenvolvimento neuropsicomotor adequado à idade,\nidentifique entre as capacidades listadas a\nque mostra aquela que ela já deve ser capaz de executar atualmente.","options":{"A":"Empilhar cubos.","B":"Levantar-se sozinha com apoio.","C":"Transferir objetos de uma mão para outra.","D":"Pegar objetos em pinça com o polegar e o indicador."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-247189","number":"247189","sourceNumber":"247189","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação ao estadiamento puberal e crescimento em adolescentes, pode-se afirmar\nque","options":{"A":"Meninas e meninos iniciam o estirão em idades cronológicas semelhantes.","B":"A identificação do estágio M2 de mama pelos critérios de Tanner pode ser usado como indicador\nde que o estirão está se iniciando no sexo\nfeminino.","C":"O primeiro sinal de amadurecimento sexual no menino é o aumento do comprimento peniano.","D":"Em estágio M3 de mamas, as meninas encontram-se em fase de desaceleração de crescimento.","E":"A muda vocal é evento que ocorre em fases precoces do desenvolvimento pubertário no sexo\nmasculino, geralmente em estágio G (genital) 2, pelos critérios de Tanner."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-251912","number":"251912","sourceNumber":"251912","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Durante consulta de puericultura da criança, ela é capaz de se sentar sem suporte do\ntronco, consegue apanhar objetos e transferi-los de uma mão para a outra, mas ainda não é capaz\nde fazer o movimento de pinça com os dedos polegar e o indicador. Estes marcos do\ndesenvolvimento são típicos de um bebê de:","options":{"A":"10 meses.","B":"6 meses.","C":"5 meses.","D":"4 meses."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-247197","number":"247197","sourceNumber":"247197","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma adolescente de 15 anos de idade procura o ginecologista para orientação\ncontraceptiva. Refere que seus pais desconhecem\nque tem atividade sexual e que não pretende\ncontar a eles. Durante o exame ginecológico, são encontradas verrugas genitais suspeitas de HPV.\nApós esclarecer as dúvidas da jovem quanto à vida sexual com segurança, o ginecologista deve","options":{"A":"Prescrever contraceptivo, biopsiar e tratar as lesões suspeitas com autorização da paciente.","B":"Solicitar a presença de um familiar responsável para prescrever o contraceptivo e tratar as\nlesões.","C":"Prescrever o contraceptivo, mas solicitar a um responsável que autorize a realização da biópsia.","D":"Orientar o uso de preservativo, cauterizar as lesões verrucosas e esclarecer sobre a\nnecessidade da presença de um adulto responsável para prescrição de medicamentos.","E":"Avisar os responsáveis a respeito da suspeita de HPV por se tratar de doença sexualmente\ntransmissível antes de instituir qualquer tratamento."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-251918","number":"251918","sourceNumber":"251918","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação ao aleitamento materno, marque a alternativa CORRETA:","options":{"A":"A recomendação internacional quanto à duração da amamentação é de 6 meses para a\namamentação exclusiva e de 1 ano ou mais para a amamentação com outros alimentos.","B":"A técnica incorreta de amamentação é a principal causa de pouco ganho ponderal na criança e\nde traumas mamilares.","C":"O bebê que mama exclusivamente ao seio materno deve ter horários regulares para se\nalimentar, sendo recomendado de 3 em 3 horas.","D":"Nos dias mais quentes, podemos oferecer água para as crianças que mamam exclusivamente\nao seio materno, pois a quantidade existente\ndesse elemento é mínima na composição do leite\nmaterno."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-251930","number":"251930","sourceNumber":"251930","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A avaliação do desenvolvimento infantil é extremamente importante na consulta\npediátrica, pois identifica precocemente um\ndéficit neuromotor ou sensorial, alertando para\npatologias. Qual das abaixo NÃO descreve um padrão de desenvolvimento neuropsicomotor no\nprimeiro ano de vida?","options":{"A":"Aos três meses o bebê já sustenta a cabeça e segura o pescoço.","B":"No terceiro trimestre de vida a criança já senta sem apoio.","C":"No primeiro trimestre o bebê ganha, aproximadamente, 700g/mês.","D":"No ultimo trimestre a criança quer explorar, iniciando o processo de autoconsciência."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-251933","number":"251933","sourceNumber":"251933","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação a prevenção da anemia ferropriva, qual é a recomendação atual da\nSociedade Brasileira de Pediatria?","options":{"A":"1mg/kg/dia de sulfato ferroso.","B":"2mg/kg/dia de sulfato ferroso.","C":"1mg/kg/dia de ferro elementar.","D":"3mg/kg/dia de ferro elementar."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-217645","number":"217645","sourceNumber":"217645","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação ao crescimento e desenvolvimento na infância, analise os itens abaixo: I.\nAnda sem apoio; II. Agarra objetos fazendo pinça com o polegar; III. Sustentar a cabeça; IV. Sentar\nem tripé.V. Junta as mãos na linha média. A alternativa CORRETA e SEQUENCIAL no que se\nrefere à aquisição cronológica dos marcos de desenvolvimento é:","options":{"A":"III, V, IV, II e I.","B":"III, V, II, IV, e I.","C":"V, III, II, IV e I.","D":"III, IV, V, II, e I."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-217726","number":"217726","sourceNumber":"217726","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação à adolescência normal, qual das alternativas abaixo está CORRETA?","options":{"A":"A primeira manifestação de puberdade no sexo feminino é o aparecimento dos pelos pubianos.","B":"A menarca ocorre cerca de 1 ano após aparecimento da primeira manifestação de puberdade\nnas meninas.","C":"No gênero masculino, após o início da puberdade, pode ocorrer ginecomastia puberal\nuni/bilateral, que tem caráter transitório e\nregride espontaneamente em cerca de 2 a 3 anos.","D":"A primeira manifestação de puberdade no sexo masculino é o aumento do tamanho peniano."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-217695","number":"217695","sourceNumber":"217695","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Mãe de primeiro filho, chega à consulta queixando-se que seu \"peito\" direito está\nendurecido em uma área do quadrante\nsuperior externo, e que a região está muito dolorida. Ela\nmostra o problema e acha que foi o leite que \"empedrou\". O médico confirma o problema. Assinale\na alternativa que apresenta a recomendação CORRETA que pode ser dada a ela.","options":{"A":"Aplicação de gelo, antes das mamadas.","B":"Ordenha manual da aréola, antes das mamadas.","C":"Compressas mornas ou banho quente, após as mamadas.","D":"Massagens delicadas, com movimentos retilíneos sobre a região afetada."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-217708","number":"217708","sourceNumber":"217708","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Sobre o desenvolvimento da linguagem na infância, assinale V (verdadeiro) ou F (falso)\nnas afirmativas a seguir: ( ) As queixas dos\nfamiliares devem sempre ser valorizadas; ( ) O uso\nexcessivo de televisão, tablet e smartphone nos dois primeiros anos de vida da criança está\nassociado à dificuldade de aprendizagem. ( ) O atraso na aquisição de linguagem oral é\nextremamente raro na infância e, na maioria das vezes, costuma ser grave. ( ) Durante a consulta,\nobservar o comportamento da criança é muito importante, pois dá informações dos aspectos\nemocionais: se fixa o olhar, se corresponde ao sorriso e à brincadeiras. A sequência CORRETA é:","options":{"A":"V-V-F-V.","B":"F-V-V-F.","C":"V-V-F-F.","D":"F-V-F-V."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-182701","number":"182701","sourceNumber":"182701","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considerando o desenvolvimento neuropsicomotor normal da infância, qual dos marcos\nabaixo NÃO é esperado para uma criança de 6 meses?","options":{"A":"Preensão cubital voluntária.","B":"Sustentar a cabeça.","C":"Sentar sozinho (sem apoio).","D":"Lalação."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-182621","number":"182621","sourceNumber":"182621","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Segundo a OMS/MS quando se fala que lactente recebe, além de leite materno, água e\nbebidas à base de água, como suco de frutas ou chás, mas não recebe outro leite, estamos usando\nqual dos conceitos de aleitamento materno abaixo?","options":{"A":"Exclusivo.","B":"Complementado.","C":"Misto ou parcial.","D":"Predominante."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-183135","number":"183135","sourceNumber":"183135","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação à composição do leite humano, é correto afirmar:","options":{"A":"O leite humano apresenta uma quantidade de ferro superior a do leite de vaca, e na forma de\nmaior biodisponibilidade para o ser humano.","B":"A lisozima é uma molécula carreadora do ferro do leite humano, impedindo que bactérias\npatogênicas façam a utilização do ferro para proliferação no meio intestinal.","C":"A relação Ca: P, no leite humano, é de 1:2, o que favorece a absorção do cálcio em detrimento\ndo fósforo na muscosa intestinal.","D":"A taurina é um aminoácido assencial, importante na formação da retina e está presenta em\nmenor quantidade no leite humano, quando comparado ao leite de vaca.","E":"IgA secretória é a principal imunoglobulina do leite humano, tendo sua especificidade\ndeterminada pelos antígenos entéricos e respiratórios da mãe."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-183140","number":"183140","sourceNumber":"183140","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma causa não rara de desmame é a ocorrência da doença na nutriz. Das situações\nabaixo relacionadas na nutriz, qual contraindica a amamentação:","options":{"A":"Tuberculose, puérpera bacilífera no final da gestação.","B":"Hepatite C diagnosticada no terceiro trimestre de gestação.","C":"Dengue na fase aguda com plaquetopenia e hipovolemia.","D":"Varicela manifestada clinicamente três dias antes do parto.","E":"Hepatite B com HbsAg reagente no primeiro trimestre."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-182688","number":"182688","sourceNumber":"182688","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Assinale a alternativa CORRETA sobre as medidas antropométricas:","options":{"A":"A aferição do comprimento em crianças até 2 anos de idade com até 16 kg deve ser realizada\nsegundo o protocolo com antropômetro horizontal.","B":"Algumas deficiências nutricionais específicas podem ocorrer sem comprometimento\nantropométrico imediato, e sua detecção depende da\nrealização de cuidadosa anamnese\nnutricional.","C":"Recomenda-se que as medidas antropométricas sejam realizadas ao nascimento, com 7 a 10\ndias de vida, e, se não forem identificados problemas, nova medida ao final de 12 meses e ao\ncompletar 24 meses de vida.","D":"A aferição de circunferência craniana em crianças até 2 anos de idade deve ser realizada,\nsegundo o protocolo, com fita métrica inextensível (precisão: cm)."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-159049","number":"159049","sourceNumber":"159049","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Puberdade precoce pode ser encontrada em ambos os sexos, mas, o feminino é o mais\nafetado, com uma proporção 23:1. Define-se puberdade precoce quando ocorre em idade inferior a:","options":{"A":"14 anos.","B":"12 anos.","C":"10 anos.","D":"08 anos."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-159073","number":"159073","sourceNumber":"159073","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Após a saída do RN da maternidade, quando o pediatra deve realizar a primeira\nconsulta?","options":{"A":"Nos primeiros cinco dias de vida.","B":"Nos primeiros 15 dias de vida.","C":"Dentro do primeiro mês de vida.","D":"Diariamente."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-159039","number":"159039","sourceNumber":"159039","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Ana Júlia, 10 meses de vida, nascida de parto normal a termo, sem intercorrências, é\nlevada à consulta de puericultura onde a mãe relata que está muito preocupada pois a filha ainda\nnão engatinha. A conduta mais adequada é:","options":{"A":"Encaminhar para o neuropediatra para investigação.","B":"Encaminhar para o fisioterapeuta para estimulação motora.","C":"Tranquilizar a mãe, pois muitas crianças não engatinham sem ter significado patológico.","D":"Solicitar tomografia computadorizada de crânio com urgência."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-159044","number":"159044","sourceNumber":"159044","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação à puberdade podemos afirmar que a:","options":{"A":"Primeira manifestação da puberdade no sexo masculino é o aumento do volume testicular.","B":"Primeira manifestação da puberdade no sexo masculino é a espermatogênese.","C":"Mudança de voz no menino ocorre devido à ação estrogênica.","D":"Aceleração do crescimento ocorre 2 anos após o início do desenvolvimento puberal."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-159058","number":"159058","sourceNumber":"159058","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Criança de 5 anos de idade chega a Unidade Básica de Saúde acompanhada da avó,\ncom queixa principal de cefaleia e vômitos. Qual(is) o(s) sinal/sintoma(s) que sugerem a hipótese\ndiagnóstica de tumor cerebral?","options":{"A":"Febre e dor em membros.","B":"Melhora da cefaleia com analgésico.","C":"Marcha claudicante e estrabismo.","D":"Sonolência."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-159105","number":"159105","sourceNumber":"159105","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Amamentar é muito mais do que nutrir a criança. É um processo que envolve interação\nprofunda entre mãe e filho, com\nrepercussões no estado nutricional da criança, em sua habilidade\nde se defender de infecções, em sua fisiologia e no seu desenvolvimento cognitivo e emocional,\nalém de ter implicações na saúde física e psíquica da mãe. Após a leitura dos itens abaixo sobre\naleitamento materno, marque a resposta correta: I. Durante a amamentação, a produção do leite é\niniciada por meio da sucção do recém-nascido, o que irá estimular a hipófise posterior e secretar\nprolactina, e esta, por sua vez, estimulará a produção de leite pelas células secretoras dos\nalvéolos\nda glândula mamária; II. O reflexo de descida do leite também se inicia com o estímulo da sucção,\nresponsável por ativar a secreção de ocitocina pela hipófise anterior, que atinge os alvéolos,\npromove a contração das células mioepiteliais e leva o leite para dentro dos ductos e então ao\nrecém-nascido; III. Entre os benefícios do aleitamento materno, estão: o melhor desenvolvimento\nda cavidade bucal, promoção do vínculo mãe-filho e o efeito protetor contra o câncer de mama para\nmulher.","options":{"A":"Apenas o item I está correto.","B":"Apenas o item II está correto.","C":"Todos estão incorretos.","D":"Apenas o item III está correto."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-135968","number":"135968","sourceNumber":"135968","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente de 2 meses e meio de idade, em aleitamento materno exclusivo é avaliado em\nunidade de pronto atendimento devido estrófulos em membros inferiores. Mãe nega febre ou outros\nsintomas, mas acha o bebê pálido. Exame físico sem alterações, exceto 2 lesões papulares na\nperna D. O pediatra solicita hemograma com o seguinte resultado: Leucócitos 10 500 - hematócrito\n32% - plaquetas 360.000; Bastões 0% - hemoglobina 9,9; Segmentados 32% - VCM 94; Linfócitos\n64% - HCM 30; Monócitos 4% - CHCM 32. Qual o diagnóstico hematológico e qual a conduta?","options":{"A":"Anemia carencial; tratar com sulfato ferroso;","B":"Anemia fisiológica; esclarecer a mãe;","C":"Anemia carencial; iniciar leite de vaca;","D":"Anemia fisiológica; iniciar leite de vaca;"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-135914","number":"135914","sourceNumber":"135914","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Assinale a alternativa CORRETA em relação a amamentação:","options":{"A":"A hepatite B não é uma doença potencialmente transmissível pelo leite materno;","B":"A toxoplasmose é transmitida via leite humano;","C":"A tuberculose não é transmitida pelo leite humano;","D":"Mães com lesões herpéticas nas mamas devem ser orientadas a suspender a amamentação\ntemporariamente."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-135939","number":"135939","sourceNumber":"135939","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Assinale V (verdadeiro) ou F (falso) e marque a alternativa correta com relação as\nseguintes afirmações: I - A deficiência de tiamina provoca anemia megaloblástica; II - A deficiência\nde vitamina D está relacionada a raquitismo em crianças e osteomalácia em adultos; III - A\ndeficiência de vitamina B12 pode causar Beribéri; IV - A deficiência de vitamina C crônica leva ao\nescorbuto.","options":{"A":"F,F,F,F;","B":"V,V,F,V;","C":"F,V,F,V;","D":"F,V,V,V;"},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-108647","number":"108647","sourceNumber":"108647","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Mãe primípara está com dificuldades na técnica de amamentação e pede ajuda ao\npediatra. O profissional solicita a colocação do bebê ao seio e observa o sinal de possível\ndificuldade. Assinale o sinal que indica a possível dificuldade:","options":{"A":"A cabeça e o tronco do bebê estão alinhados.","B":"O corpo do bebê está muito perto do corpo da mãe.","C":"A mama está apoiada com dedos da mãe na aréola.","D":"O bebê está todo voltado para a mãe."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-108656","number":"108656","sourceNumber":"108656","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente de cinco meses de idade em aleitamento materno exclusivo é levado ao\nambulatório para atendimento de Puericultura. A mãe quer saber se está na época de iniciar outro\nleite. O bebê está com peso adequado e curva de crescimento ascendente. Qual a conduta\nindicada?","options":{"A":"Manter o leite materno e prescrever complementação;","B":"Manter leite materno e prescrever papa de legumes;","C":"Orientar a mãe sobre a importância do aleitamento exclusivo ao seio até o sexto mês;","D":"Recomendar suco de fruta."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-84499","number":"84499","sourceNumber":"84499","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Assinale a alternativa que apresenta a provável sequência cronológica do\ndesenvolvimento motor de Silvana, que hoje tem 1 ano e 6 meses:","options":{"A":"Sentou-se com apoio, sustentou a cabeça, andou com apoio.","B":"Sustentou a cabeça, andou com apoio, sentou-se com apoio.","C":"Sentou-se com apoio, andou com apoio, sustentou a cabeça.","D":"Andou com apoio, sentou-se com apoio, sustentou a cabeça.","E":"Sustentou a cabeça, sentou-se com apoio, andou com apoio."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-84467","number":"84467","sourceNumber":"84467","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Acerca do papel das fibras alimentares na dieta do lactante, assinale a opção\nCORRETA:","options":{"A":"Na redução da absorção de gorduras, utilizam-se fibras solúveis.","B":"Para o tratamento da diarreia aguda, é muito importante o uso de fibras insolúveis.","C":"O leite materno é rico em fibras insolúveis.","D":"Fibras solúveis são importantes na redução do colesterol.","E":"Fibras insolúveis são aquelas ricas em gorduras."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-84483","number":"84483","sourceNumber":"84483","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A mãe de Jonas (4 meses) quer saber quando o pediatra prescreverá sulfato ferroso\nprofilático. O Cartão da Criança de Jonas\nmostra que ele nasceu a termo e com peso adequado\npara a idade gestacional. Considerando que Jonas receberá exclusivamente leite materno até os 6\nmeses, assinale a alternativa que apresenta a provável resposta do pediatra.","options":{"A":"Do primeiro até o segundo ano de vida.","B":"Somente quando a criança apresentar anemia ferropriva.","C":"Quando a criança apresentar anemia perniciosa.","D":"A partir da introdução da alimentação complementar (dos 6 meses aos 2 anos).","E":"Dos 6 meses até 1 ano."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-84503","number":"84503","sourceNumber":"84503","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação a distúrbios do desenvolvimento puberal, é correto afirmar que:","options":{"A":"O brotamento das mamas costuma ser a primeira alteração puberal reconhecida.","B":"A menarca é a segunda alteração puberal que normalmente ocorre no desenvolvimento da\npuberdade.","C":"Durante o estirão de crescimento associado à puberdade, os ossos longos de corpo se alongam,\ne as epífises não se fecham.","D":"A secreção de hormônio do crescimento diminui juntamente com o aumento de gonadotropina\nno início da puberdade.","E":"O surgimento dos pelos pubianos ocorre após a menarca."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-66956","number":"66956","sourceNumber":"66956","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considere as assertivas abaixo: I - Malformação congênita é todo defeito na\nconstituição de algum órgão ou conjunto de órgãos que determine uma anomalia morfológica\nestrutural presente ao nascimento; II - Toda malformação congênita é de origem genética; III -\nDoença genética é todo e qualquer distúrbio que afete o material genético; IV - Toda doença\ngenética é hereditária. Marque a alternativa em que as assertivas estão CORRETAS.","options":{"A":"I e II.","B":"II e III.","C":"I e III.","D":"II e IV."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-66962","number":"66962","sourceNumber":"66962","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menina, 14 anos procurou atendimento por não apresentar desenvolvimento puberal.\nMas nega atraso no desenvolvimento\nneuropiscicomotor ou dificuldade de leitura na escola. Ao\nexame: corada, hidratada, afebril, peso adequado, baixa estatura (abaixo do percentil 3), pescoço\ncurto e alado, hipertelorismo mamário, cúbito valgo. Qual o diagnóstico sindrômico mais provável?","options":{"A":"Síndrome de Turner;","B":"Síndrome de Down;","C":"Síndrome de Klinefelter;","D":"Síndrome de Laron."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343181","number":"343181","sourceNumber":"343181","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com quais idades considera-se puberdade precoce em meninos e meninas?","options":{"A":"Entre 8 e 13 anos nas meninas e entre 9 e 14 anos nos meninos.","B":"Entre 6 e 8 anos nas meninas e entre 7 e 9 anos nos meninos.","C":"Antes dos 8 anos em meninas e 9 anos em meninos.","D":"Antes de 9 anos em meninas e 11 anos em meninos."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343182","number":"343182","sourceNumber":"343182","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação à puberdade em meninos e meninas assinale a alternativa correta.","options":{"A":"Em meninas, o início da puberdade é marcado pela menarca.","B":"A puberdade inicia-se entre 8 e 13 anos nas meninas e entre 9 e 14 anos nos meninos.","C":"Em meninos, o início da puberdade é marcado por pelos corporais generalizados.","D":"A puberdade precoce sempre vai ser central."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343183","number":"343183","sourceNumber":"343183","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um adolescente de 13 anos de idade, sexo masculino, relata o aumento da mama\ndireita há 6 meses. Ao exame físico apresenta\ntecido mamário subareolar palpável bilateralmente,\ntestículos com 10ml e pelos axilares, com pelos pubianos e genitália no estágio 3 de Tanner. Qual\na conduta mais indicada nesse momento?","options":{"A":"Acompanhamento clínico.","B":"Cirurgia para remoção das mamas.","C":"Tratamento com inibidores de aromatase.","D":"Tratamento com antagonistas de estrogênio."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343184","number":"343184","sourceNumber":"343184","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um dado do exame físico que levanta a suspeita de puberdade precoce periférica em\num menino de 4 anos com virilização é a\npresença de:","options":{"A":"Pubarca","B":"Ginecomastia","C":"Quadro neurológico","D":"Testículos de volume infantil"},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343185","number":"343185","sourceNumber":"343185","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um menino apresenta aumento de pênis em seu comprimento, testículos com 10cc,\npelos escuros, grossos e crespos no saco escrotal e na linha média acima de pênis, bem como\npelos finos acima do lábio superior, acne, mudança da voz e início do estirão puberal. Qual é a\nclassificação de Tanner para seu estágio puberal?","options":{"A":"G3P3","B":"G2P2","C":"G4P3","D":"G3P2"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-341071","number":"341071","sourceNumber":"341071","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menino, 13 meses, em aleitamento materno exclusivo, pesa 11,0Kg e a curva de\ncrescimento acompanha o mesmo percentil desde o\nnascimento. Sua mãe o leva à Unidade Básica\nde Saúde para orientação pois precisará complementar a alimentação para trabalhar fora de casa.\nA família é vegetariana e pretende manter essa prática na dieta da criança. Indique a partir de qual\nperíodo de vida a introdução de novos alimentos deve ser incentivada:","options":{"A":"5 meses.","B":"6 meses.","C":"12 meses.","D":"24 meses."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-341073","number":"341073","sourceNumber":"341073","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menino, 13 meses, em aleitamento materno exclusivo, pesa 11,0Kg e a curva de\ncrescimento acompanha o mesmo percentil desde o\nnascimento. Sua mãe o leva à Unidade Básica\nde Saúde para orientação pois precisará complementar a alimentação para trabalhar fora de casa.\nA família é vegetariana e pretende manter essa prática na dieta da criança. Quanto à presença de\naminoácidos essenciais na alimentação vegetariana, é correto afirmar:","options":{"A":"Histidina, Leucina e Isoleucina não são encontrados na alimentação vegetariana.","B":"Metionina, Cisteína e Histidina não são encontrados na alimentação vegetariana.","C":"Triptófano, Valina e Metionina não são encontrados na alimentação vegetariana.","D":"Todos os aminoácidos essenciais necessários à dieta são encontrados na alimentação\nvegetariana."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-341075","number":"341075","sourceNumber":"341075","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menina, 14 anos de idade, é levada ao Ambulatório de Pediatria com relato de ausência\nde menarca. Sua mãe apresentou a menarca aos 13\nanos. Posiciona-se adequadamente nos\ngráficos ponderal e estatural. Verifica-se que apresenta caracteres sexuais secundários\ncompatíveis com os critérios de Tanner M5P4 e não há alterações ao exame segmentar. Indique o\ndiagnóstico provável para esse caso:","options":{"A":"Menarca tardia.","B":"Puberdade fisiológica.","C":"Atraso puberal a esclarecer.","D":"Atraso puberal constitucional."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-341076","number":"341076","sourceNumber":"341076","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menina, 14 anos de idade, é levada ao Ambulatório de Pediatria com relato de ausência\nde menarca. Sua mãe apresentou a menarca aos 13\nanos. Posiciona-se adequadamente nos\ngráficos ponderal e estatural. Verifica-se que apresenta caracteres sexuais secundários\ncompatíveis com os critérios de Tanner M5P4 e não há alterações ao exame segmentar. Indique a\nconduta adequada a ser adotada no caso:","options":{"A":"Orientar aos pais e expectar.","B":"Prescrever medroxiprogesterona.","C":"Solicitar dosagem de TSH e FSH.","D":"Solicitar ultrassonografia de útero e de ovários."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-315174","number":"315174","sourceNumber":"315174","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um bebê primogênito de 1 mês de vida, amamentação exclusivamente ao peito, não\nganhou peso adequadamente. A mãe se queixa de\nque a criança ?mama a toda hora?. Fez\n\npré-natal completo, sem intercorrências e seu parto foi normal. O bebê nasceu a termo, pesando\n\n3.400 g. Apresenta-se normal ao exame físico. Este quadro requer a seguinte conduta:","options":{"A":"Avaliar técnica correta de amamentação.","B":"Introduzir complemento de fórmula láctea.","C":"Explicar à mãe a importância do leite materno.","D":"Pesar o lactente antes e depois da mamada ao seio.","E":"Nenhuma das afirmativas acima."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-315175","number":"315175","sourceNumber":"315175","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Quanto ao leite materno, pode-se afirmar que:","options":{"A":"A proteção anti-infecciosa conferida à criança se refere apenas à doença diarreica viral.","B":"A manutenção do aleitamento materno exclusivo até quatro meses é desejável pois a partir\ndessa idade as crianças necessitam alimentação rica em ferro.","C":"A proteção anti-infecciosa decorrente do aleitamento materno é decorrente da presença de IgA\nsecretora e vários fatores inespecíficos, como lisozima, fatores de maturação para o epitélio\nintestinal e lactoferrina.","D":"Crianças com baixo peso devem receber leite de vaca como complemento até atingir o peso\nideal para a idade.","E":"O aleitamento materno não deve ser exclusivo até seis meses, pois a criança necessita de frutas\npara suplementar sua necessidade de vitaminas."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-315176","number":"315176","sourceNumber":"315176","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Qual das opções abaixo é a mais eficaz para garantir um adequado volume de leite na\nnutriz?","options":{"A":"Sucção frequente.","B":"Nível plasmático de ocitocina.","C":"Uso de spray de ocitocina","D":"Uso regular de metoclopramida","E":"Uso de bomba que garanta o esvaziamento do seio materno."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-314206","number":"314206","sourceNumber":"314206","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Todas as crianças necessitam fazer acompanhamento de crescimento e\ndesenvolvimento, principalmente, nos primeiros anos de\nvida. São competências do pediatra na\npuericultura todas as abaixo, exceto:","options":{"A":"Obrigar viagem anual da criança com a família.","B":"Orientar atividade física.","C":"Orientar imunizações.","D":"Avaliação do quadril coluna e marcha."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-313444","number":"313444","sourceNumber":"313444","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Para oferecer um cuidado de qualidade e alcançar resultados positivos no controle de\nsintomas alguns pontos são muito relevantes. Dentre os abaixo, assinale a incorreta.","options":{"A":"Avaliação das queixas utilizando instrumentos validados para a faixa etária pediátrica e o\nidioma.","B":"Controle dos sintomas utilizando apenas a terapêutica farmacológica, excluindo-se as práticas\nnão farmacológicas.","C":"Comunicação dos achados de estudos e pesquisas, de hipóteses diagnósticas e do plano\nterapêutico de forma honesta e realista.","D":"Reavaliação e monitoramento, a fim de ter certeza de que o tratamento está adequado e, caso\ncontrário, proceder com nova avaliação e ajuste da terapêutica."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-313445","number":"313445","sourceNumber":"313445","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Durante o plantão no Pronto Socorro Infantil você atende um paciente de 5 anos. Os\npais referem que a criança apresenta febre,\ndor abdominal e vômitos. Ao exame apresenta-se\ndescorado, hidratado, acianótico, ictérico, taquipnéico, febril, taquicárdico e edemaciado; o abdome\né doloroso à palpação difusamente, com RHA diminuídos, restante do exame sem alterações\nimportantes. Das alternativas abaixo são sinais apresentados pelo paciente todas as descritas,\nexceto:","options":{"A":"Icterícia.","B":"Edema.","C":"Taquipneia.","D":"Dor abdominal."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-307062","number":"307062","sourceNumber":"307062","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Jovem, primípara, acaba de evoluir com parto normal e recebe notícia, durante\ninternação, que está com sorologia positiva\npara HIV, motivo pelo qual não poderá amamentar. A\npaciente ainda não começou a produzir colostro. Identifique o mecanismo de ação da cabergolina:","options":{"A":"Agonista da dopamina.","B":"Antagonista da dopamina.","C":"Antagonista de GnRH.","D":"Inibidor da produção de ocitocina."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-280410","number":"280410","sourceNumber":"280410","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Assinale a alternativa que apresenta uma síndrome genética que não tem correlação\nclínica com ginecomastia.","options":{"A":"Síndrome de Down.","B":"Síndrome de Klinefelter.","C":"Síndrome de Kallmann.","D":"Síndrome de Peutz-Jeghers."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-278094","number":"278094","sourceNumber":"278094","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Sobre a Avaliação do Desenvolvimento Neuropsicomotor (DNPM) e\nmusculoesquelético, assinale a alternativa correta.","options":{"A":"As crianças com alterações do DNPM, do tônus muscular e da função neuromusculoesquelética\napresentam maior risco de desenvolver atelectasias\npulmonares.","B":"Diferentemente da escala de Bayley, a Alberta identifica se a idade cronológica e o DNPM\nesperado da criança são correspondentes.","C":"Existem diversos instrumentos determinados para avaliar o DNPM de acoro com a faixa etária\nda criança, em pediatria é recomendada,\nexclusivamente, a escala de Alberta.","D":"O sistema neuromusculoesquelético não sofre alterações indiretas durante a internação\nhospitalar, principalmente e UTI."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-275994","number":"275994","sourceNumber":"275994","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Marcelo, 1 ano, termo, hígido, nasceu pesando 3400 g, medindo 50 cm de estatura e\n35 cm de perímetro cefálico. Ao ser avaliado\nna UBS, quais seriam as medições esperadas para\nMarcelo?","options":{"A":"Peso: 10 kg; estatura: 75 cm; perímetro cefálico: 47 cm.","B":"Peso: 12 kg; estatura: 65 cm; perímetro cefálico: 41 cm.","C":"Peso: 9,2 kg; estatura: 50 cm; perímetro cefálico: 39 cm.","D":"Peso: 7,2 kg; estatura: 60 cm; perímetro cefálico: 44 cm.","E":"Peso: 8,3 kg; estatura: 75 cm; perímetro cefálico: 37 cm."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-275995","number":"275995","sourceNumber":"275995","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Júlia, 11 anos, hígida, vai à consulta com pediatra acompanhada de sua mãe Gabriela\ne de seu pai João. A mãe questiona o médico\na respeito do início da puberdade de sua filha,\nquerendo saber se há algum atraso, uma vez que aos 11 anos afirma já ter menstruado. O pediatra\nrelata que Júlia ainda está dentro da faixa etária de início de desenvolvimento puberal e que a\nconduta, por hora, é acompanhar. João, atento, pergunta ao médico quais seriam os sinais, em\nsequência, que Júlia apresentaria e quando a menstruação de Júlia provavelmente irá acontecer.\n\nEm relação ao caso anteriormente descrito, quais seria a resposta do médico à pergunta de João,\nsabendo que o primeiro sinal puberal de Júlia irá aparecer ainda aos 11 anos?","options":{"A":"Menarca, pubarca e telarca. A menstruação de Júlia irá acontecer, provavelmente, aos 13 anos.","B":"Telarca, menarca e pubarca. A menstruação de Júlia irá acontecer, provavelmente, aos 11 anos.","C":"Telarca, pubarca e menarca. A menstruação de Júlia irá acontecer, provavelmente, aos 13 anos.","D":"Apenas telarca e menarca. A menstruação de Júlia irá acontecer, provavelmente, aos 12 anos.","E":"Apenas telarca e pubarca. A menstruação de Júlia irá acontecer, provavelmente, aos 11 anos."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-283746","number":"283746","sourceNumber":"283746","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menina, 8 meses de idade, é levada à Unidade Básica de Saúde, UBS, para consulta\nde rotina. Nasceu de parto natural a termo,\npesando 3.300g; medindo 49cm e com Perímetro\nCefálico medindo 34cm. Atualmente pesa 8.000g e mede 67,5cm (escore z: em ambos, entre -1 e\n\n+1). Está em aleitamento materno exclusivo. Considerando a velocidade de crescimento esperada\npara o perímetro cefálico, especifique qual\ndeve ser, aproximadamente, o valor atual nesta criança:","options":{"A":"40 cm.","B":"42 cm.","C":"44 cm.","D":"46 cm."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-283747","number":"283747","sourceNumber":"283747","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menina, 8 meses de idade, é levada à Unidade Básica de Saúde, UBS, para consulta\nde rotina. Nasceu de parto natural a termo,\npesando 3.300g; medindo 49cm e com Perímetro\nCefálico medindo 34cm. Atualmente pesa 8.000g e mede 67,5cm (escore z: em ambos, entre -1 e\n\n+1). Está em aleitamento materno exclusivo. Considerando que essa criança apresenta\ndesenvolvimento neuropsicomotor adequado à idade,\nidentifique entre as capacidades listadas a\nque mostra aquela que ela já deve ser capaz de executar atualmente.","options":{"A":"Empilhar cubos.","B":"Levantar-se sozinha com apoio.","C":"Transferir objetos de uma mão para outra.","D":"Pegar objetos em pinça com o polegar e o indicador."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-249905","number":"249905","sourceNumber":"249905","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Sobre nutrição materna e infantil assinale a alternativa correta:","options":{"A":"A nutrição materna deficiente afeta principalmente o sistema motor da criança.","B":"A inadequada nutrição materna e infantil pode limitar o desenvolvimento de aspectos\nimportantes da arquitetura do cérebro.","C":"A anemia materna no primeiro trimestre gestacional é um dos fatores impeditivos para o\ncrescimento infantil.","D":"O estado nutricional adequado da gestante é importante, mas não é fator de risco para maiores\nproblemas comportamentais na idade escolar, mesmo na ausência de déficits neurológicos\nevidentes."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-249303","number":"249303","sourceNumber":"249303","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A ginecomastia é a proliferação benigna mais comum do tecido glandular da mama\nmasculina, causada pela alteração do equilíbrio entre as concentrações de estrógeno e\nandrogênios. Pela Classificação de Simon, a mama que apresenta aumento mamário moderado\ncom redundância de pele definida, similar a mama feminina corresponde ao grau:","options":{"A":"I","B":"II","C":"III","D":"IV"},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-249404","number":"249404","sourceNumber":"249404","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Assinale a alternativa incorreta em relação à palpação do abdome em pediatria:","options":{"A":"Devemos aprofundar a palpação no tempo expiratório.","B":"Sempre deixar as regiões dolorosas para serem palpadas por último.","C":"Utilizar sempre a ponta dos dedos para pressionar os órgãos durante a palpação.","D":"A princípio palpar toda a extensão do abdome, depois os órgãos específicos."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-231388","number":"231388","sourceNumber":"231388","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A anemia ocorre principalmente pela deficiência de ferro é a carência nutricional de\nmaior magnitude no mundo. Atinge,\nprincipalmente, crianças menores de dois anos e gestantes e,\nno pré-natal, relaciona-se com o baixo peso ao nascer e à mortalidade materna. Em relação às\nestratégias criadas no Brasil para o controle e redução da anemia por deficiência de ferro, assinale\na alternativa correta.","options":{"A":"Suplementação preventiva diária de 60 mg de sulfato ferroso e 5mg de ácido fólico para crianças\nde 6 a 18 meses de idade e suplementação\nsemanal de 25 mg de sulfato ferroso para gestantes a\npartir da 20ª semana.","B":"Suplementação preventiva semanal de 25 mg de sulfato ferroso para crianças de 6 a 18 meses\nde idade e suplementação diária de 60 mg de\nsulfato ferroso e 5mg de ácido fólico para gestantes a\npartir da 20ª semana.","C":"Suplementação medicamentosa diária de 60 mg de sulfato ferroso e 5mg de ácido fólico\nsomente para gestantes com diagnóstico de anemia falciforme.","D":"Fortificação das farinhas de trigo e milho com ferro e vitamina A: cada 100g de farinha de trigo\ne\nde milho deverá conter 10,0 mg de ferro e\n200.000 UI de vitamina A.","E":"fortificação das farinhas de mandioca e arroz com ferro e tiamina: cada 100g de farinha de\nmandioca e arroz deverão conter 10,0 mg de ferro e 150 mg de vitamina B1."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-201763","number":"201763","sourceNumber":"201763","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Qual das opções abaixo é a mais eficaz para garantir um adequado volume de leite na\nnutriz?","options":{"A":"Sucção frequente.","B":"Nível plasmático de ocitocina.","C":"Uso de spray de ocitocina.","D":"Uso regular de metoclopramida.","E":"Uso de bomba que garanta o esvaziamento do seio materno."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-201764","number":"201764","sourceNumber":"201764","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O retardo na purberdade é definido como a ausência de características sexuais\nsecundárias na idade de:","options":{"A":"10 anos.","B":"12 anos.","C":"14 anos.","D":"16 anos.","E":"18 anos."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-215513","number":"215513","sourceNumber":"215513","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Você está atendendo em uma UBS e a mãe traz seu filho de 1 ano e 3 meses para\nconsulta de rotina; refere que a criança começou a andar faz 1 mês e está falando algumas\npalavras, usa fralda durante o dia e à noite. Come bem, mas mama apenas leite materno. Ao\nexame apresenta PC no percentil 50, peso no percentil 25 e estatura no percentil 25 do gráfico de\ncrescimento. Qual é a orientação para a mãe?","options":{"A":"Solicitar TC de crânio, pois a criança está com PC desproporcional ao tamanho e peso.","B":"Orientar suspender o leite materno e iniciar leite de vaca engrossado, pois a criança está\ndesnutrida.","C":"Orientar apenas retorno na consulta de rotina.","D":"Solicitar hemograma, urina 1, glicemia, ureia e creatinina para investigar a causa da\ndesnutrição."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-219915","number":"219915","sourceNumber":"219915","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Adolescente feminino, 17 anos, apesar de ter feito acompanhamento nutricional com\nsucesso, optara por realizar cirurgia de\nredução de estômago em serviço privado. Evoluiu com\ncomplicações pós-cirúrgicas e foi transferida para Unidade de Terapia Intensiva onde veio a falecer\ncinco dias após a admissão. Um jornal local quer fazer reportagem sobre os riscos de\nprocedimentos cirúrgicos na adolescência e procura você. Frente aos dados deste caso e\nbaseando-se no capítulo XI - Sigilo Profissional - do Código de Ética Médica brasileiro (2010),\nassinale a opção CORRETA:","options":{"A":"Você pode revelar fato de que tenha conhecimento em vista do exercício de sua profissão,\nquando este já é de conhecimento público.","B":"Você poderá prestar informações a empresas seguradoras sobre as circunstâncias da morte do\npaciente sob seus cuidados, além das contidas na declaração de óbito.","C":"Você poderá utilizar retratos de sua paciente em anúncios profissionais ou na divulgação de\nassuntos médicos, com a autorização do paciente/familiares.","D":"Você tem o dever de preservar o sigilo profissional em paciente com menos de 18 anos de\nidade, mesmo após o óbito da adolescente."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-219896","number":"219896","sourceNumber":"219896","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Na unidade básica de saúde, você está acompanhando um lactente de seis meses de\nidade que está em aleitamento materno exclusivo e a mãe está com dúvidas quanto a introdução\nde alimentos. Segundo orientações para alimentação saudável do Ministério de Saúde, você\ndeverá orientar a mãe que:","options":{"A":"Aos oito meses, a criança poderá receber a alimentação básica da família desde que não seja\nmuito temperada.","B":"Há crianças que se adaptam facilmente às novas etapas e aceitam bem os novos alimentos\npermitindo a retirada do leite materno.","C":"Outros alimentos podem ser introduzidos de forma lenta e gradual até a retirada do leite materno\nao final do primeiro ano de vida.","D":"Se a criança rejeitar as primeiras ofertas pode indicar intolerância ao alimento devendo-se\noferecer outros em substituição."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-212202","number":"212202","sourceNumber":"212202","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"As evidências científicas acerca da prevenção de doenças crônicas e degenerativas do\nadulto através da alimentação saudável na primeira infância têm levado o governo brasileiro a\ninvestir em treinamentos para intervenções nutricionais em aleitamento materno. Aplicando a\nBioética às boas práticas de aconselhamento, podemos dizer:","options":{"A":"a escuta é mais importante que qualquer outro instrumento de intervenção em aleitamento\nmaterno.","B":"nos casos de contraindicações do leite materno, o preparo de fórmula não deve ser orientado na\nmaternidade, pelo risco de outras mães se desestimularem a amamentar.","C":"deve-se observar e intervir nas mães inseguras quanto às vantagens do aleitamento materno, e\na liberação para alta depende da alimentação do\nbebê com leite materno exclusivo.","D":"deve ser realizado aconselhamento sempre que se observar relutância em não amamentar, com\ntécnicas verbais e todas as informações possíveis, empatia e julgando o aleitamento materno a\nmelhor escolha para o binômio mãe-bebê.","E":"o aconselhamento em saúde não significa necessariamente que o profissional de saúde fale das\nvantagens e alerte sobre os riscos da não amamentação, mas tenha argumentação para que a mãe\nopte pela decisão de amamentar com autonomia."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-212177","number":"212177","sourceNumber":"212177","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Na avaliação da puberdade, costuma-se avaliar as mamas e os pelos púbicos nas\nmeninas e as características dos genitais\ne os pelos púbicos nos meninos. Nesse contexto, dadas\nas afirmativas, considerando-se sua evolução natural, I. Nas mamas, no estágio 4, a aréola e a\npapila formam um contorno secundário, destacando-se do resto da mama. II. Nos genitais, no\nestágio 2, o escroto apresenta-se levemente aumentado, com pele mais escura e mudança de\ntextura, enquanto no estágio 1, permanece de tamanho e formas infantis. III. No estágio 3, tanto em\nmeninos quanto em meninas, os pelos são finos, longos, lisos ou curvos, com localização exclusiva\nem base do pênis ou a longo dos lábios. verifica-se que está(ão) correta(s)","options":{"A":"II, apenas.","B":"III, apenas.","C":"I e II, apenas.","D":"I e III, apenas.","E":"I, II e III."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-180119","number":"180119","sourceNumber":"180119","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um bebê primogênito de 1 mês de vida, amamentação exclusivamente ao peito, não\nganhou peso adequadamente. A mãe se queixa de\nque a criança ?mama a toda hora?. Fez\n\npré-natal completo, sem intercorrências e seu parto foi normal. O bebê nasceu a termo, pesando\n\n3.400 g. Apresenta-se normal ao exame físico. Este quadro requer a seguinte conduta:","options":{"A":"Avaliar técnica correta de amamentação","B":"Introduzir complemento de fórmula láctea","C":"Explicar à mãe a importância do leite materno","D":"Pesar o lactente antes e depois da mamada ao seio","E":"Nenhuma das afirmativas acima"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-180129","number":"180129","sourceNumber":"180129","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Quanto ao leite materno, pode-se afirmar que:","options":{"A":"A proteção anti-infecciosa conferida à criança se refere apenas à doença diarreica viral","B":"A manutenção do aleitamento materno exclusivo até quatro meses é desejável pois a partir\ndessa idade as crianças necessitam alimentação rica em ferro.","C":"A proteção anti-infecciosa decorrente do aleitamento materno é decorrente da presença de IgA\nsecretora e vários fatores inespecíficos, como lisozima, fatores de maturação para o epitélio\nintestinal e lactoferrina","D":"Crianças com baixo peso devem receber leite de vaca como complemento até atingir o peso\nideal para a idade","E":"O aleitamento materno não deve ser exclusivo até seis meses, pois a criança necessita de frutas\npara suplementar sua necessidade de vitaminas"},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-180132","number":"180132","sourceNumber":"180132","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Qual das opções abaixo é a mais eficaz para garantir um adequado volume de leite na\nnutriz?","options":{"A":"Sucção frequente","B":"Nível plasmático de ocitocina","C":"Uso de spray de ocitocina","D":"Uso regular de metoclopramida","E":"Uso de bomba que garanta o esvaziamento do seio materno."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-187762","number":"187762","sourceNumber":"187762","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Qual alternativa é CORRETA em relação às peculiaridades próprias da relação\nmédico-paciente em Pediatria?","options":{"A":"Aquele que se chama paciente muitas vezes não é a criança, mas sim a mãe ou o pai","B":"Dirigir-se às mães, chamando-as de \"mãe\" e não pelo seu nome reforça o caráter pessoal da\nrelação","C":"Na clientela particular de consultório, o pagamento direto pelos serviços médicos diminiu a\naquisição de direitos sobre o pediatra","D":"Nas últimas décadas, com o avanço tecnológico, a satisfação com os pediatras vem crescendo"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-187811","number":"187811","sourceNumber":"187811","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Qual alternativa está CORRETA em relação aos alimentos e à medicação na prevenção\nde anemia por deficiência de ferro?","options":{"A":"Lactente nascido a termo, com peso adequado e recebendo pelo menos 500ml/dia de fórmula\nalimentar não necessita de reposição de ferro","B":"O espinafre contém alto teor de ferro, porém tem baixa disponibilidade","C":"O feijão tem alto teor de ferro e alta disponibilidade","D":"Prematuros acima de 2kg ao nascimento não necessitam receber reposição de ferro"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-182759","number":"182759","sourceNumber":"182759","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Cognição é uma rede complexa de funções mentais comandadas pelo cérebro que\ninclui todas as alternativas abaixo, EXCETO:","options":{"A":"Atenção","B":"Memória","C":"Aprendizado","D":"Audição"},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-182764","number":"182764","sourceNumber":"182764","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"São fatores que podem influenciar o desenvolvimento cognitivo da criança, EXCETO:","options":{"A":"Prematuridade.","B":"Recém-nascidos com Crescimento Intra-Útero Acelerado (GIG).","C":"Nível socioeconômico.","D":"Estimulação no primeiro ano de vida."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-182776","number":"182776","sourceNumber":"182776","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação ao Desenvolvimento Cognitivo, assinale a alternativa CORRETA:","options":{"A":"Durante os períodos fetal e neonatal precoce, o cérebro está em uma fase de desenvolvimento e\namadurecimento rápidos, sendo um período que o torna vulnerável a desequilíbrios nutricionais.","B":"O desenvolvimento cognitivo depende apenas do desenvolvimento e do amadurecimento\nestrutural das várias regiões do cérebro, e não sofre\ninfluências externas.","C":"Após um período de deficiência nutricional, depois da reposição do nutriente em quantidades\nadequadas, o cérebro tem capacidade de recuperar-se totalmente, sem sofrer interferências.","D":"Algumas áreas específicas do cérebro, associadas à linguagem, leitura e memória não sofrem\ninfluências de agravos nutricionais durante a infância."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-182785","number":"182785","sourceNumber":"182785","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Assinale a alternativa INCORRETA:","options":{"A":"A desnutrição nos primeiros dois anos de vida pode estar associada a alterações do\ndesenvolvimento da linguagem e do aprendizado.","B":"Existe uma relação entre deficiência de ferro e pior desenvolvimento cognitivo durante a\ninfância.","C":"A dieta materna influencia as variações no conteúdo de gordura do leite materno.","D":"O número de partos anteriores é um importante fator de influência na variação do conteúdo de\ngordura do leite materno, quanto maior o número de gestações, maiores as concentrações de\ngordura no leite materno."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-181413","number":"181413","sourceNumber":"181413","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A puberdade feminina caracteriza-se pelo surgimento dos caracteres sexuais\nsecundários (mamas, pelos pubianos e menstruação)\nparalelamente à aceleração ou estirão do\ncrescimento, dentre outros eventos biológicos e psicossociais. Sobre a puberdade precoce\nfeminina, é correto afirmar:","options":{"A":"um dos principais exames complementares é a radiografia de mãos e punhos, avaliada\ncomumente pelo método de Tanner, para determinação da idade óssea.","B":"no exame físico ginecológico, é importante realizar avaliação\n\ncuidadosa e se utilizar dos critérios de Greulich-Pyle para determinar o desenvolvimento mamário e\ndos pelos pubianos.","C":"a puberdade precoce central é causada por maturação precoce\n\ndo eixo hipotálamo-hipófise-ovariano, sendo na maioria dos casos por ativação idiopática dos\npulsos de GnRH.","D":"a puberdade precoce periférica pode ser causada por\n\nexcesso de hormônios esteroides sexuais de fonte exógena, secretados pelas gônadas ou nas\nglândulas suprarrenais, com ativação do eixo hipotálamo-hipófise-ovariano.","E":"cistos foliculares de ovário são a causa mais rara de\n\npuberdade precoce periférica, sendo as neoplasias ovarianas, como as das células da granulosa,\ntumores de\n\ncélulas de Leydig e gonadoblastomas, as mais frequentes."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-181401","number":"181401","sourceNumber":"181401","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Constitui contraindicação absoluta ao aleitamento materno:","options":{"A":"galactosemia.","B":"mastite lactacional.","C":"fissura labiopalatal.","D":"ingurgitamento mamário.","E":"doença da urina de xarope de bordo."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-152625","number":"152625","sourceNumber":"152625","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O aleitamento materno está contraindicado quando a mãe apresenta:","options":{"A":"HTLV-1.","B":"Sífilis.","C":"Citomegalovírus.","D":"Toxoplasmose.","E":"Rubéola."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-161276","number":"161276","sourceNumber":"161276","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Para o adequado tratamento de pacientes com betatalassemia maior, inclui terapêutica\ntransfusional crônica, agentes quelantes de ferro, esplenectomia, transplante alogênico de\n\ncélulas-tronco hematopoéticas e medidas de suporte. Entretanto, a terapia transfusional regular\nleva a complicações relacionadas à\nsobrecarga de ferro, incluindo manifestações listadas a seguir,\ncom EXCEÇÃO de:","options":{"A":"Retardo no crescimento.","B":"Aceleração da maturação sexual.","C":"Miocardiopatia dilatada.","D":"Fibrose hepática e cirrose."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-158801","number":"158801","sourceNumber":"158801","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Qual o sinal de alarme que surge na criança aos nove meses de vida, devendo-se\nrealizar como conduta, a investigação do\ncomprometimento do desenvolvimento neuropsicomotor?","options":{"A":"Não fala quatro palavras.","B":"Não segue ordens simples.","C":"Não tem preensão em pinça.","D":"Ausência de sinergia pés-mãos.","E":"Não se arrasta para subir em objetos."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-158809","number":"158809","sourceNumber":"158809","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Dadas as afirmativas sobre os marcos do desenvolvimento neuropsicomotor infantil, I.\nAos dois anos de vida, a criança é capaz de: correr com desenvoltura, abrir portas, subir em\ncadeiras, ajudar no vestir, manusear bem colheres e começar a formar frases.; II. Aos três anos de\nvida, a criança é capaz de: pular, ficar de um pé só, participar de jogos e brincadeiras, controlar\nevacuação e micção diurna, dizer sua idade e sexo, contar até três objetos.; III. Aos dezoito meses\nde vida, a criança é capaz de: ao correr, movimentar o corpo em bloco, sentar-se a partir da\nposição ereta, procurar ajuda em situações de perigo, beijar familiares, falar dez palavras e\nreconhecer partes do corpo.; Verifica-se que está(ão): correta(s)","options":{"A":"I, II e III.","B":"I e II, apenas.","C":"III, apenas.","D":"II, apenas.","E":"I, apenas."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-158825","number":"158825","sourceNumber":"158825","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Dadas as afirmativas sobre a absorção de ferro, I. O efeito negativo dos fitatos não\nsofre interferência da dose.; II. A absorção do\nferro heme ocorre da mesma forma do ferro\ninorgânico.; III. O ácido ascórbico e o ácido cítrico melhoram a biodisponibilidade do ferro,\nreduzindo de ferroso para férrico.; IV. São fatores inibidores de sua absorção: os polifenóis,\nfitatos,\ncálcio, caseína e proteínas de legumes.; V. Em refeições ricas em fitatos, recomenda-se a ingestão\nconcomitante de ácido ascórbico, que compensaria o efeito negativo dos fitatos, na proporção 2:1\n(ácido ascórbico: ferro).; Verifica-se que estão corretas apenas:","options":{"A":"I e IV.","B":"III e IV.","C":"IV e V.","D":"I, II e III.","E":"I, II e V."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-131399","number":"131399","sourceNumber":"131399","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em que período da vida o crescimento é acelerado?","options":{"A":"Com 3 anos e com 10 anos.","B":"No primeiro ano de vida e na adolescência.","C":"Entre 5 e 7 anos de idade.","D":"Antes e após a menstruação.","E":"Período pré-escolar e escolar."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-131403","number":"131403","sourceNumber":"131403","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Qual o tecido ou sistema que primeiro para de crescer?","options":{"A":"Tecido conjuntivo.","B":"Sistema imune.","C":"Tecido nervoso.","D":"Sistema vascular.","E":"Musculoesquelético."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-131409","number":"131409","sourceNumber":"131409","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Você é o (a) médico (a) de um posto de saúde e atende em consulta agendada um\nbebê de 02 meses de vida, trazido pela\nprimeira vez ao serviço, cuja mãe tem 15 anos de idade.\nQual a forma mais adequada de realizar este atendimento de modo a otimizar o máximo possível\nesta consulta?","options":{"A":"Deixaria que a mãe falasse espontaneamente e responderia a cada dúvida que ela tivesse.","B":"Seguiria o padrão de consulta, começando pela queixa principal, história da doença atual,\nantecedentes pessoais, antecedentes familiares, antecedentes patológicos e sociais. Faria a\nrevisão dos sistemas e procederia ao exame físico. No final, faria as orientações necessárias\nidentificadas pela esta anamnese e prescreveria a receita.","C":"Iniciaria o atendimento pela identificação, tentando desde o início interagir com a jovem mãe,\npara\n\nadquirir a confiança da mesma. Seguiria um padrão de anamnese e exame físico priorizando a\nhistória alimentar e vacinal. Procederia ao exame físico discutindo cada detalhe e esclarecendo\ndúvidas. Faria a prescrição conforme os diagnósticos levantados e agendaria o retorno para o\npróximo mês.","D":"Em um posto de saúde a demanda é grande e quanto mais ágil for o atendimento melhor para a\npopulação.","E":"Deixaria que a enfermeira atendesse, pois se trata apenas de um atendimento de rotina para\norientar vacina e dieta."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-131421","number":"131421","sourceNumber":"131421","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Mãe traz seu filho com uma semana de vida para consulta, em aleitamento materno\nexclusivo. A queixa é a de que ?toda vez que mama, evacua?. Sua conduta é:","options":{"A":"Suspender o aleitamento, dar soro oral e agendar retorno em 24 horas.","B":"Suspender o aleitamento materno e prescrever uma fórmula isenta de lactose.","C":"Trocar o aleitamento materno para o leite de vaca diluído acrescido de creme de arroz.","D":"Manter o aleitamento materno e prescrever soro oral no intervalo das mamadas.","E":"Manter o aleitamento materno e tranquilizar a mãe."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134879","number":"134879","sourceNumber":"134879","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Está cada vez mais comum, entre crianças e jovens, o consumo dos chamados <i> fast\nfoods </i>. Esse tipo de dieta deve ser desestimulado por ter valor nutricional pobre e por ser:","options":{"A":"Hiperproteica.","B":"Hipocalórica.","C":"Rica em ferro.","D":"Rica em sódio."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134792","number":"134792","sourceNumber":"134792","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação às anemias carenciais, podemos afirmar que","options":{"A":"o diagnóstico laboratorial da anemia ferropriva inclui ferro sérico e ferritina sérica baixos,\ncapacidade total de ligação de ferro\n\nbaixa e saturação de transferrina alta.","B":"a deficiência de B12 e as talassemias são exemplos clássicos de anemias macrocíticas.","C":"nas crianças com anemia hemolítica esferocítica, está contraindicado o uso de sulfa e\nquinolonas.","D":"baixo peso ao nascimento, desmame precoce e baixa disponibilidade de ferro na dieta\npredipõem às anemias ferroprivas."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134795","number":"134795","sourceNumber":"134795","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Você recebe em seu consultório um lactente de 3 meses, nascido de termo, sem\nintercorrências na gestação e período neonatal. Ao exame físico, apresenta as mãos sempre\nfechadas, não sorri e não sustenta a cabeça. Diante desse caso, qual é a conduta MAIS\nadequada?","options":{"A":"Solicitar teste do olhinho e da orelhinha, com retorno em 30 dias para reavaliação.","B":"Orientar a família a fazer estimulação motora e sensorial, além de encaminhar para o\nfisioterapeuta.","C":"Aguardar o teste do pezinho para avaliar doenças metabólicas congênitas.","D":"Encaminhar ao neurologista para avaliação e investigação."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134272","number":"134272","sourceNumber":"134272","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Os suplementos vitamínicos e minerálicos na adolescência devem ser oferecidos\nsomente:","options":{"A":"Na fase de aceleração do crescimento.","B":"Na fase de desaceleração do crescimento.","C":"Antes da menarca.","D":"Em situações especiais como distúrbios alimentares."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134801","number":"134801","sourceNumber":"134801","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em uma consulta de rotina do Posto de Saúde, você atende uma criança que apresenta\nas seguintes habilidades: anda com apoio,\naproxima-se quando é chamada, bate palmas, solta um\nobjeto sob comando, emite 1 ou 2 palavras com significado. Considerando as diretrizes com\nreferência à faixa superior da normalidade, você diria que essa criança tem quanto tempo?","options":{"A":"6 meses","B":"9 meses","C":"12 meses","D":"18 meses"},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134803","number":"134803","sourceNumber":"134803","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação ao desenvolvimento infantil, podemos afirmar que","options":{"A":"o desenvolvimento adequado da criança não depende de um ambiente social propício.","B":"o lactente se senta sem apoio por volta dos 6 meses.","C":"o uso de bebidas alcoólicas durante a gestação não é fator de distúrbios do desenvolvimento.","D":"por volta de 1 e 2 meses, a criança é capaz de combinar 2 palavras."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134061","number":"134061","sourceNumber":"134061","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Pré-escolar, 36 meses, apresenta, ao exame físico, tecido celular subcutâneo\ndiminuído, sem outras alterações clínicas. A\navaliação do gráfico da curva de crescimento mostra\npeso/idade no percentil 2. Segundo as normas do Ministério daSaúde, pode-se afirmar que o\n\npré-escolar","options":{"A":"é portador de baixo peso.","B":"é portador de desnutrição grave.","C":"se encontra em alerta nutricional.","D":"é portador da forma clínica denominada marasmo."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134834","number":"134834","sourceNumber":"134834","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Criança de 7 anos é levada pela mãe ao Pediatra para consulta de rotina. Ao exame\nfísico, foi constatado que a criança estava\nno estágio M2P2 de Tanner. Diante de tal caso clínico, a\nhipótese diagnóstica MAIS provável é:","options":{"A":"Puberdade precoce.","B":"Telarca idiopática precoce.","C":"Pseudopuberdade precoce.","D":"Puberdade normal."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134055","number":"134055","sourceNumber":"134055","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A forma prática de monitorizar a nutrição pós-natal do recém-nascido pré-termo,\ndurante a internação na UTI neonatal, é\navaliada por","options":{"A":"dosagem da pré albumina.","B":"dosagem da albumina sérica.","C":"utilização das curvas de crescimento.","D":"dosagem de creatinina sérica."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134267","number":"134267","sourceNumber":"134267","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A causa mais comum de anemia por deficiência de ferro na infância é","options":{"A":"Gemelaridade.","B":"Infecções crônicas.","C":"Desordens gastrointestinais.","D":"Ingestão inadequada de ferro."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-110542","number":"110542","sourceNumber":"110542","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A deficiência de ferro em lactentes e crianças maiores acompanha-se clinicamente de\ntodos os sinais e sintomas, EXCETO:","options":{"A":"Irritabilidade.","B":"Geofagia.","C":"Hipertrofia das papilas gustativas.","D":"Anorexia.","E":"Palidez."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-110604","number":"110604","sourceNumber":"110604","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"São características descritas na Síndrome de Down, EXCETO:","options":{"A":"hipermobilidade articular;","B":"hipotonia muscular;","C":"macroglossia;","D":"malformações cardíacas;","E":"deficiência mental."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-110571","number":"110571","sourceNumber":"110571","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"<p>Escolar do sexo masculino de sete anos e seis meses de idade, previamente\nsaudável, trazido ao seu consultório com queixa\nde baixa estatura. A família tem boa renda e as\ncondições alimentares são adequadas. A altura da mãe é de 1.55 m (p25) e a do pai de 1.75 m\n(p50-75). Traz exames complementares realizados previamente com resultados dentro do padrão\nnormal. Atualmente a criança mede 1.16 m e pesa 20 kg, tem desenvolvimento neuropsicomotor e\nexame físico normais. A melhor conduta é: </p>","options":{"A":"Tranquilizar a família e reavaliar o crescimento em 6 a 12 meses.","B":"Solicitar novos exames complementares e\nraios X de sela túrcica.","C":"Encaminhar ao endocrinologista para avaliação.","D":"Solicitar dosagem de hormônio do crescimento.","E":"Solicitar T4 livre, TSH e cintilografia de tireoide."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-110574","number":"110574","sourceNumber":"110574","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"No desenvolvimento neuropsicomotor de um lactente observa-se, aproximadamente\naos seis meses de idade, a aquisição da\ncapacidade de:","options":{"A":"sustentar a cabeça;","B":"sorrir socialmente;","C":"ficar sentado, inclinando-se para frente;","D":"abrir a boca para ser alimentado;","E":"ficar em pé segurando no berço."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-109773","number":"109773","sourceNumber":"109773","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Criança de 1 ano e 3 meses vem em consulta de rotina e apresenta PC no percentil 50,\npeso no percentil 25 e estatura no percentil 25 do gráfico de crescimento. Mãe refere que a criança\ncomeçou a andar há 1 mês e está falando algumas palavras. Come bem, mas toma apenas leite\nmaterno. Usa fralda durante o dia e à noite. Qual é a orientação para a mãe?","options":{"A":"Encaminhar ao neurologista para investigar atraso DNPM, pois a criança começou a andar muito\ntarde, fala apenas algumas palavras e ainda usa fralda durante o dia.","B":"Solicitar hemograma, urina 1, glicemia, ureia e creatinina para investigar a causa da\ndesnutrição.","C":"Solicitar TPC de crânio, pois a criança apresenta PC desproporcional ao tamanho e peso.","D":"Orientar apenas retorno à consulta de rotina."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-109994","number":"109994","sourceNumber":"109994","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um lactente de seis semanas de vida, com diagnóstico de cardiomiopatia congestiva,\nestá pesando 4 kg. Alimenta-se de 360 ml de fórmula\ndiariamente. Das alternativas abaixo, a\nconsequência MAIS provável da ingestão diminuída nessa criança é:","options":{"A":"Hipocalcemia.","B":"Hipoglicemia.","C":"Ganho de peso inadequado.","D":"Hipopotassemia."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-109808","number":"109808","sourceNumber":"109808","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Mãe procura você no consultório para acompanhamento do bebê. Lactente\nencontra-se com 6 meses de idade, em aleitamento\nmaterno exclusivo, sem alterações ao\nexame físico. Desenvolvimento neuropsicomotor adequado, crescimento peso no percentil 20% e\nestatura no percentil 25%. Nesse caso, o que você orienta para a mãe?","options":{"A":"Manter aleitamento materno exclusivo e retornar em 1 mês para pesar.","B":"Manter aleitamento materno e iniciar papas.","C":"Suspender aleitamento materno, iniciar fórmula infantil e retornar em 1 mês para pesar.","D":"Manter aleitamento materno e associar leite integral com frutas."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-86611","number":"86611","sourceNumber":"86611","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O processo de crescimento é multifatorial, englobando a composição genética do\nindivíduo, fatores neuroendócrinos, ambientais, nutricionais e psicossociais. De acordo com o\nexposto, assinale a afirmativa CORRETA:","options":{"A":"No primeiro ano de vida ocorre a maior velocidade de crescimento, cerca de 40 cm/ano e ganha\ncerca de 8 kg.","B":"No primeiro ano de vida ocorre a maior velocidade de crescimento, cerca de 24 cm/ano e ganha\ncerca de 6 kg.","C":"No segundo ano de vida cresce aproximadamente 24 cm/ano.","D":"A velocidade de crescimento na fase escolar está em torno de 12 cm/ano.","E":"O estirão puberal é mais tardio e mais amplo nas meninas do que nos meninos."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-86616","number":"86616","sourceNumber":"86616","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Quais os itens abaixo são marcos do desenvolvimento de uma criança com 6 meses de\nidade?","options":{"A":"Sorri, eleva a cabeça e a mantém a 45º.","B":"Transfere objeto de uma mão para a outra, pinça polegar-dedo.","C":"Bate palmas, acena, vocaliza.","D":"Tenta alcançar um brinquedo, chama atenção por meio de um sorriso, vocalização.","E":"Senta sem apoio, balbucia."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-86612","number":"86612","sourceNumber":"86612","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Marcela, de seis anos de idade, é levada para consulta por apresentar palidez há seis\nmeses e falta de apetite. Exame físico: palidez cutâneo-mucosa e restante normal. Para\nconfirmação de anemia ferropriva, quais as alterações encontradas nos exames?","options":{"A":"Hb < 11 g/dl, contagem de reticulócitos aumentada, hipercromia e macrocitose.","B":"Hb < 11 g/dl, contagem de reticulócitos normal ou diminuída, hipocromia e microcitose.","C":"Hb < 11,5 g/dl, contagem de reticulócitos aumentada, hipercromia e macrocitose.","D":"Hb < 11,5 g/dl, contagem de reticulócitos normal ou diminuída, hipocromia e microcitose.","E":"Hb < 12 g/dl, contagem de reticulócitos aumentada, hipercromia e macrocitose."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-86617","number":"86617","sourceNumber":"86617","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Marcela de seis anos de idade é levada para consulta por apresentar palidez há seis\nmeses e falta de apetite. Exame físico: palidez cutâneo-mucosa e restante normal. Após iniciar o\ntratamento para Anemia Ferropriva de Marcela, qual o exame mais adequado para avaliar\nprecocemente a sua resposta terapêutica?","options":{"A":"Dosagem de hemoglobina.","B":"Contagem de reticulócitos.","C":"Saturação de transferrina.","D":"Dosagem de ferro sérico.","E":"Ferritina sérica."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-86641","number":"86641","sourceNumber":"86641","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Marque V (Verdadeiro) ou F (Falso) e assinale a alternativa CORRETA: ( ) Em casos de\ndoença cardiovascular materna, a amiodarona\npoderá ser utilizada. ( ) A vincristina é contraindicada\nna amamentação, bem como a maioria dos quimioterápicos. ( ) Quando há a necessidade do uso\ndo lítio durante a amamentação, deve-se monitorar níveis plasmáticos de lítio na mãe e no bebê,\nassim como a função tireóidea. ( ) Carbamazepina e ácido valproico são considerados substâncias\nseguras para uso durante a lactação. As respostas são, respectivamente:","options":{"A":"V, V, F, F.","B":"V, F, F, V.","C":"F, F, V, F.","D":"V, F, V, F.","E":"F, V, V, V."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-86873","number":"86873","sourceNumber":"86873","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente feminino, 20 meses de idade, é levado para consulta de puericultura sem\nqueixas. Usou leite materno até o quarto mês\nde vida, quando começou a usar a alimentação\ncomplementar adequada e também leite de vaca 6 vezes ao dia. Não usa ou usou medicamento\nalgum. Trouxe um hemograma que mostra Hb = 9,2 g/dl, VCM = 61 micro3, RDW = 18%. Assinale\na alternativa que apresenta o diagnóstico MAIS PROVÁVEL para o quadro acima.","options":{"A":"Anemia falciforme.","B":"Talassemia minor.","C":"Esferocitose hereditária.","D":"Anemia ferropriva.","E":"Anemia hemolítica autoimune."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-86870","number":"86870","sourceNumber":"86870","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O início da puberdade é acompanhado de diferentes mudanças corporais e\npsicológicas. Qual dos eventos abaixo é\nconsiderado o melhor parâmetro do início da puberdade\nem meninos?","options":{"A":"Aumento dos testículos e da bolsa escrotal;","B":"Mudança do timbre de voz;","C":"Crescimento de pelos em face;","D":"Velocidade rápida do crescimento;","E":"Mudanças psicológicas."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-158438","number":"158438","sourceNumber":"158438","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação ao aleitamento materno, é CORRETO afirmar que:","options":{"A":"Para retirar o recém-nascido da mama, a nutriz deve esperar que ele adormeça.","B":"Deve-se iniciar precocemente, a partir da 2ª hora de vida.","C":"Deve ser evitado nas mães que apresentam sangramento maior que 2 litros na parturição.","D":"A pega deve ser com o recém-nascido apreendendo toda a aréola mamária e com os lábios\nevertidos.","E":"No ingurgitamento mamário, devem ser indicadas compressas mornas nas mamas."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-158402","number":"158402","sourceNumber":"158402","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Segundo os 10 passos para alimentação saudável do lactente, está INCORRETA a\nafirmativa:","options":{"A":"Recomenda-se introdução de alimentos sólidos a partir do 6° mês de vida.","B":"O suco de fruta não é indicado na dieta de um lactente.","C":"Recomenda-se que o aleitamento materno seja oferecido no mínimo até os 12 meses e, depois\ndisso, pelo tempo que desejado mutuamente.","D":"Os lactentes que não são alimentados ao seio podem receber leite de vaca integral após o 6°\nmês de vida.","E":"Aos 6 meses, deve-se acrescentar fonte protéica animal, carbohidratos, frutas e verduras."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-158388","number":"158388","sourceNumber":"158388","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Segundo critérios de Tanner, a primeira manifestação da puberdade no sexo feminino\né:","options":{"A":"Menarca.","B":"Adrenarca.","C":"Pubarca.","D":"Telarca.","E":"Ciclos anovulatórios."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-158399","number":"158399","sourceNumber":"158399","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Qual das situações abaixo representa uma contraindicação absoluta para o aleitamento\nmaterno?","options":{"A":"Prótese de silicone materna.","B":"Infecção materna pelo HTLV-1.","C":"Recém ? nascido com citomegalovirose congênita.","D":"Mãe com tuberculose pulmonar.","E":"Mãe com herpes labial."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-158433","number":"158433","sourceNumber":"158433","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A amamentação possui inúmeras vantagens para a mãe e para o filho. Assim, cabe ao\nmédico auxiliar na promoção do aleitamento materno através de:","options":{"A":"Estímulo à amamentação na 1ª hora após o parto.","B":"Orientação quanto a horários e intervalos de mamadas a cada 3 horas.","C":"Recomendação de fricção mamilar com bucha vegetal durante o pré-natal.","D":"Prescrição de cremes à base de lanolina para prevenção de fissuras mamilares.","E":"Estímulo à amamentação após todo o cuidado e banho do recém-nascido."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-108597","number":"108597","sourceNumber":"108597","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Os eventos habituais no desenvolvimento puberal normal, em ordem de surgimento,\nsão:","options":{"A":"Velocidade máxima de crescimento, surgimento de pelos pubianos, brotamento mamário,\nmenarca.","B":"Surgimento de pelos pubianos, velocidade máxima de crescimento, brotamento mamário,\nmenarca.","C":"Brotamento mamário, menarca, surgimento dos pelos pubianos, velocidade máxima de\ncrescimento.","D":"Brotamento mamário, surgimento de pelos pubianos, velocidade máxima de crescimento,\nmenarca.","E":"Surgimento de pelos pubianos, brotamento mamário, menarca, velocidade máxima de\ncrescimento."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-108610","number":"108610","sourceNumber":"108610","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Criança de 1 ano e 4 meses vai à UBS onde você realiza o internato de medicina\npreventiva, por conta de quadro gripal.\nAlimentação da criança variada. Vacinas realizadas até 1\nano de idade. Ao exame, menor eupneica, hidratada, anictérica, acianótica, afebril, boa interação\ncom o meio, desenvolvimento neuropsicomotor adequado para idade, AP: MV presente\nbilateralmente com roncos de transmissão, AC: BCNF RCR 2T S/Sopro, abdome flácido sem\nmegas ou massas, extremidades sem alterações. Quais das situações abaixo esperamos que essa\ncriança ainda não realize?","options":{"A":"Andar sem apoio.","B":"Falar até 5 palavras comuns.","C":"Andar para trás.","D":"Trocar objetos de mãos.","E":"Colocar objeto dentro de uma vasilha."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-108612","number":"108612","sourceNumber":"108612","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação ao desenvolvimento de uma criança de 2 meses devemos observar:","options":{"A":"Fixa o olhar no rosto do examinador ou da mãe.","B":"Segue objeto na linha média.","C":"Reage ao som.","D":"Eleva a cabeça.","E":"TODAS ACIMA."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-108616","number":"108616","sourceNumber":"108616","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação à recomendação para suplementação de ferro, é CORRETO:","options":{"A":"Lactentes nascidos a termo, de peso adequado para idade gestacional, em aleitamento materno\nexclusivo até 6 meses de idade, não é indicado a\n\nsuplementação.","B":"Lactentes nascidos a termo, de peso adequado para idade gestacional, em uso de fórmula\ninfantil até 6 meses de idade e a partir do\n6° mês se houver ingestão mínima de 500 ml de fórmula\npor dia, não é indicado a suplementação.","C":"Lactentes nascidos a termo, de peso adequado para idade gestacional, a partir da introdução de\nalimentos complementares, é indicado a suplementação de ferro.","D":"Prematuros maiores de 1.500 g e recém-nascidos de baixo peso, a partir do 30° dia de vida, é\nindicada a suplementação.","E":"Todas corretas."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-327281","number":"327281","sourceNumber":"327281","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em uma consulta de ambulatório, ao receber mãe, avó e LILS, de 1 semana de vida.\nVocê é questionado pela avó, que seu neto,\nnasceu a termo com 3.400 kg e elas observaram perda\nde peso do bebê nos últimos dias. Na triagem, o peso do bebê hoje é de 3.000kg. Na anamnese,\nmãe relata aleitamento materno exclusivo e a avó sugere, a necessidade de complemento\n(mamadeira), já que seu neto perdeu peso e na sua família as mães não têm leite. Na oportunidade\nao observar a mamada, você detectou que o seio da lactante apresenta fissuras, o que seria\nevitado se a pega estivesse adequada. O que é necessário para uma boa pega: I. Mais aréola\nvisível, acima da boca do bebê. II. Boca bem aberta. III. Bochechas do bebê encovadas a cada\nsucção. IV. Ruídos da língua. V. Lábio inferior virado para fora. VI. Queixo tocando a mama.\n\nAssinale a alternativa CORRETA.","options":{"A":"Somente as afirmativas I, II, IV e V estão corretas.","B":"Somente as afirmativas I, II, V e VI estão corretas.","C":"Somente as afirmativas I, III, IV e VI estão corretas.","D":"Somente as afirmativas II, III, V e VI estão corretas."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-327288","number":"327288","sourceNumber":"327288","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Mãe, leva o filho Luís, de 12 meses de idade, a consulta de puericultura, ansiosa,\nefetuando alguns questionamentos, pois a\ncriança ainda não anda, apesar de ficar de pé com\napoio, falar a palavra \"mamãe\", reconhecer o som do seu nome, dar tchau, bate palminhas, há 2\nmeses ele passou a estranhar pessoas desconhecidas, tem acordado a noite chorando e querendo\npermanecer com os pais, algo que não acontecia desde os 4 meses de vida, quando passou a ter\num sono mais tranquilo. Ela viu no Instagram que talvez fosse o caso de contratar uma Consultora\ndo Sono. Qual seria a sua orientação:","options":{"A":"Lactente com provável diagnóstico de terror noturno, com necessidade de avaliação com\nNeuropediatra e Consultora de Sono.","B":"Lactente com sinais precoces de Autismo, com indicação de encaminhamento ao Neuropediatra\ne início de Melatonina para auxiliar o sono.","C":"Lactente com desenvolvimento esperado para a idade, sendo necessário acolher as angústias\nda mãe e orientá-la que essas alterações são\nnormais.","D":"Lactente com sinal de alerta para o desenvolvimento motor, com indicação para estímulo com\nfisioterapia motora e retorno em 4 semanas para reavaliação."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-298249","number":"298249","sourceNumber":"298249","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Os estágios G2, G3 e G4 de Tanner para meninos são marcados, respectivamente,\npor:","options":{"A":"Crescimento do pênis em comprimento; aumento do pênis em diâmetro e aumento do volume\ntesticular.","B":"Aumento do volume testicular; crescimento do pênis em comprimento e aumento do pênis em\ndiâmetro.","C":"Crescimento do pênis em comprimento; aumento do volume testicular e aumento do pênis em\ndiâmetro.","D":"Aumento do volume testicular; aumento do pênis em diâmetro e crescimento do pênis em\ncomprimento."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-298256","number":"298256","sourceNumber":"298256","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Você é médico da Estratégia de Saúde da Família na zona rural de sua cidade. Recebe\npara consulta um lactente de 10 meses com\nantecedentes neonatais sem intercorrências e com\nboa evolução até o momento. Já iniciou introdução alimentar e mantém aleitamento materno. Ao\naplicar o instrumento para avaliação do desenvolvimento você verifica que: não duplica sílabas, não\ntransfere objetos de uma mão para outra, brinca de esconde achou, senta-se sem apoio, imita\ngestos, faz pinça, produz jargão e não anda com apoio. Qual a classificação e qual seria sua\nconduta nessa consulta?","options":{"A":"DNPM normal","B":"DNPM normal com fator de risco","C":"Alerta para desenvolvimento","D":"Provável atraso no desenvolvimento"},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-298257","number":"298257","sourceNumber":"298257","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"\"Entre as ações para prevenção da deficiência de ferro e anemia ferropriva está o\nincentivo ao aleitamento materno exclusivo\naté seis meses de vida e prolongado até dois anos de\nidade, associado ao acesso universal à alimentação adequada pela mãe durante a lactação e pelo\nlactente, de forma a aumentar o consumo de alimentos fontes de ferro, bem como de alimentos que\naumentam a biodisponibilidade e a absorção do ferro na introdução de alimentos complementares.\"\nQual das opções a seguir descreve fatores de risco para anemia em crianças?","options":{"A":"Gestações múltiplas com pouco intervalo entre elas, prematuridade e baixo peso ao nascer (<\n2.500g), clampeamento do cordão umbilical antes de um minuto de vida.","B":"Suplementação de ferro na gravidez e lactação, meninas com grandes perdas menstruais,\naleitamento materno exclusivo prolongado 2 (superior a seis meses).","C":"Dieta materna deficiente em ferro, alimentação complementar com alimentos ricos em ferro e de\nalta biodisponibilidade, malária.","D":"Discrasias sanguíneas, hemorragia gastrintestinal (ex: doença inflamatória intestinal, polipose\ncolônica, drogas anti-inflamatórias não esteroides), suplementação profilática com ferro\nmedicamentoso, quando recomendada."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-286759","number":"286759","sourceNumber":"286759","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Márcia, 23 anos, acabou de dar à luz ao seu primeiro filho, que nasceu a termo, sem\nintercorrências e com 3kg. Com relação à amamentação é CORRETO orientar que:","options":{"A":"As mamadas devem ser em livre demanda e que devemos começar uma nova mamada pelo\núltimo seio que foi oferecido na mamada anterior.","B":"Os horários das mamadas devem ser a cada 3h e que antes disso não há motivo para ser fome.","C":"A duração das mamadas devem ser de 10 minutos e que ela deverá trocar de mama após esse\nintervalo.","D":"As fórmulas infantis podem ser oferecidas durante a madrugada para deixar a mãe descansar."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-286760","number":"286760","sourceNumber":"286760","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Pedro e Eduarda são pais de Mateus, um lactente que acabou de completar 6 meses.\nMateus é um bebê hígido, sem\nintercorrências desde o nascimento, com bom desenvolvimento\nneuropsicomotor e está atualmente em seio materno livre demanda. Você é o médico da UBS e vai\norientá-los sobre a introdução da alimentação complementar. Na Caderneta de Saúde da Criança\ndo Ministério da Saúde existem os 10 passos para alimentação saudável que orientam:","options":{"A":"No início da introdução de alimentos, deve-se deixar a consistência líquida para que as crianças\nnão engasguem.","B":"Primeiro deve-se oferecer frutas 2x ao dia até que a criança se adapte e se acostume. Só então,\npassar para alimentos salgados.","C":"As carnes devem ser oferecidas após o nono mês, pois nesse momento já existem os dentes\nque auxiliarão na mastigação.","D":"A alimentação complementar deve ser oferecida de acordo com os horários de refeição da\nfamília, em intervalos regulares e de forma a respeitar o apetite da criança."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-286769","number":"286769","sourceNumber":"286769","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Os pacientes com Síndrome de Down apresentam mais frequentemente:","options":{"A":"Hipotireoidismo","B":"Microcefalia","C":"Hipertireoidismo","D":"Diabetes insipidus"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-286772","number":"286772","sourceNumber":"286772","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Estaremos diante de um alerta para atraso do desenvolvimento neuropsicomotor se aos\n9 meses o lactente:","options":{"A":"Não anda.","B":"Não fala uma palavra.","C":"Não engatinha.","D":"Não se senta sem apoio."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-252220","number":"252220","sourceNumber":"252220","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A anemia ferropriva permanece como uma das deficiências nutricionais mais frequentes\ne importantes no mundo. O tratamento com ferro\ndeve ser iniciado preferencialmente por via oral e\na investigação apropriada de sua causa é obrigatória. Sobre o tratamento da anemia ferropriva,\nassinale a alternativa INCORRETA:","options":{"A":"A dose terapêutica de ferro elementar recomendada para o tratamento da anemia ferropriva é de\n10 mg a 20 mg/kg/dia, não ultrapassando 100\nmg/dia nos adultos.","B":"O ferro é mais bem absorvido no duodeno e no jejuno proximal, onde as proteínas carreadoras\ndo ferro expressam-se mais fortemente.","C":"Os sais de ferro não devem ser administrados com as refeições, porque os farelos, fitatos\n(fórmulas infantis, ervilha, feijão) e taninos\n(vinho, chocolate, nozes, canela) da dieta se ligam ao\nferro e dificultam a sua absorção.","D":"O ferro é também mais bem absorvido como sal ferroso (Fe++) num ambiente levemente ácido;\ndaí a indicação de tomá-lo com meio copo\nde suco de laranja."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-252282","number":"252282","sourceNumber":"252282","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O aleitamento materno exclusivo até o 6º mês de vida é considerado o alimento mais\nimportante para o lactente. Qual das infecções maternas é formalmente contraindicação ao\naleitamento?","options":{"A":"Infecção pelo HTLV 1-2","B":"Rubéola","C":"Hepatite A","D":"Infecção por citomegalovírus"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-208306","number":"208306","sourceNumber":"208306","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A sequência e a velocidade de maturação puberal variam entre os indivíduos, porém os\neventos sentinelas da puberdade, em geral, seguem um padrão previsível. Assinale o CORRETO:","options":{"A":"Gonadarca - pubarca - adrenarca - telarca - menarca","B":"Pubarca - telarca - adrenarca - gonadara - menarca","C":"Gonadarca - adrenarca - pubarca - telarca - menarca","D":"Adrenarca - pubarca - gonadarca - telarca - menarca"},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-208354","number":"208354","sourceNumber":"208354","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Recém-nascido de termo, sexo feminino, pesou 3.250 gramas ao nascimento. O exame\nfísico na sala de parto evidenciou face achatada, fenda palpebral oblíqua, epicanto, pele abundante\nno pescoço, sulco entre o hálux e o segundo artelho, hipotonia muscular generalizada e reflexo de\nMoro débil. Entre os exames complementares rotineiramente indicados para o melhor\nacompanhamento desse paciente estão:","options":{"A":"Ecocardiograma e dosagem sérica de cortisol.","B":"Tomografia computadorizada de crânio e cariótipo.","C":"Audiometria de tronco cerebral e dosagem sérica de TSH, T4 e T3.","D":"Eletroneuromiografia e fundo de olho."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-208377","number":"208377","sourceNumber":"208377","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Suelen está de licença maternidade, porém terá que voltar ao trabalho no próximo mês.\nMantém aleitamento materno exclusivo e está preocupada como poderá fazer após o fim da\nlicença. Ela leu na internet que poderá ordenhar e guardar seu leite ordenhado cru (não\npasteurizado) em um congelador (freezer), podendo oferecê-lo com segurança a seu filho em\nperíodo após a coleta de até, no máximo:","options":{"A":"15 dias","B":"30 dias","C":"2 meses","D":"24 horas"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-176117","number":"176117","sourceNumber":"176117","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Quanto à avaliação de puberdade no gênero masculino, assinale assertiva CORRETA:","options":{"A":"A primeira manifestação da puberdade é o aumento do diâmetro do pênis.","B":"Deve-se considerar retardo puberal a ausência de qualquer característica sexual secundária a\npartir dos 14 anos de idade.","C":"O aumento dos testículos ocorre após, aproximadamente, um ano do aumento do diâmetro do\npênis.","D":"O início da puberdade antes dos 11 anos é considerado puberdade precoce."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-176028","number":"176028","sourceNumber":"176028","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente, 1 ano e 6 meses de idade, sexo feminino, é trazido pela tia materna em\nconsulta ambulatorial para avaliação. Ao\nquestionar pelos pais, tia informa que ambos são usuários\nde drogas e relata abandono da menor. Neste atendimento, a única queixa é que criança está\nmuito emagrecida. O médico não dispõe de histórico pregresso, bem como da caderneta da\ncriança. Em relação aos dados antropométricos desta paciente, peso 7 kg (escore-Z = -3),\ncomprimento 72 cm (escore-Z = -3) e perímetro cefálico 44 cm (escore-Z = -2 e ? +2), classifica-se\npaciente como PESO MUITO BAIXO para idade. Assinale a conduta CORRETA neste caso:","options":{"A":"Encaminhar imediatamente para nutricionista e iniciar dieta especial.","B":"Orientar dieta especial e solicitar retorno em 30 dias para avaliação de ganho ponderal no\nperíodo.","C":"Prescrever megadose de vitamina A, se a criança não tiver tomado nos últimos 30 dias.","D":"Referir urgentemente ao hospital, para início de dieta enteral via sonda nasogástrica."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-176100","number":"176100","sourceNumber":"176100","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O aleitamento materno exclusivo até o 6º mês é considerado o alimento mais\nimportante para o lactente. Dentre as infecções\nmaternas, é contraindicado para o aleitamento:","options":{"A":"Citomegalovírus.","B":"Infecção pelo HTLV-1.","C":"Hepatite C.","D":"Rubéola."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-151869","number":"151869","sourceNumber":"151869","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A.M.O., 11 anos foi levada por sua mãe à primeira consulta ginecológica. Ao exame\nfísico, o médico concluiu que a paciente estava no estágio II de Tanner. Isso significa:","options":{"A":"Elevação da mama e da papila com separação discreta da aréola. Pêlos velares com a área da\nlinha média coberta.","B":"Maior elevação da mama e da papila sem separação dos contornos da aréola e da mama. Pêlos\npubianos qualitativamente adultos, mas a área coberta concentra-se na linha média.","C":"Separação dos contornos da aréola e da mama. Pêlos pubianos adultos em quantidade e\nqualidade. No monte de vênus a distribuição obedece à configuração em triângulo invertido.","D":"Mamas: elevação discreta da mama e da papila, com aumento do diâmetro areolar (broto\nmamário) pêlos pubianos terminais grossos,\npigmentados, discretamente curvilíneos nos grandes\nlábios e no monte de vênus."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-151870","number":"151870","sourceNumber":"151870","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"As diretrizes da suplementação de vitamina D recomendam a ingestão diária para todos\nos lactentes de:","options":{"A":"400 Ul\\dia.","B":"800 Ul\\dia.","C":"1.000 Ul\\dia.","D":"1.200 Ul\\dia."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-151959","number":"151959","sourceNumber":"151959","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Sobre as dificuldades e manejo com aleitamento materno, marque a alternativa\nINCORRETA:","options":{"A":"Quando existe a queixa de \"pouco leite\" ou 'leite fraco\", o profissional deve apenas orientar a\nmãe \"que não existe leite fraco\".","B":"Quando a anquiloglossia está causando problemas na amamentação, está indicada a\nfrenotomia.","C":"Um recurso que se utiliza para fazer o bebê mamar na mama \"recusada\", muitas vezes com\nsucesso, é o uso da posição de \"jogador de futebol americano\" (football player).","D":"As mulheres submetidas à cirurgia de redução de mamas devem ser informadas de que a\nmamoplastia redutora pode postargar a descida do leite, assim como o estabelecimento pleno da\nlactação."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-129812","number":"129812","sourceNumber":"129812","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Segundo as Orientações do Ministério da Saúde, 2013, em relação ao\nacompanhamento do adolescente, sexo MASCULINO, é INCORRETO afirmar:","options":{"A":"A primeira manisfestação da puberdade no sexo masculino é o aumento do volume testicular,\nem média aos 10 anos e 9 meses.","B":"O crescimento peniano acontece associado ao crescimento dos testículos.","C":"A idade da primeira ejaculação, conhecida como semenarca ou espermarca, ocorre em média\naos 12 anos e 8 meses.","D":"A ginecomastia puberal regride espontaneamente em 85% dos casos."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-129815","number":"129815","sourceNumber":"129815","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Segundo as Orientações do Ministério da Saúde, 2013, em relação ao\nacompanhamento da adolescente, sexo FEMININO, é INCORRETO afirmar;","options":{"A":"O mamário é o primeiro sinal puberal na menina, é chamado de telarca e pode apresentar-se\nunilateralmente sem significado patológico.","B":"Caso a puberdade se inicie com o aparecimento de pelos pubianos e não com o broto mamário,\na puberdade é de origem periférica.","C":"Nas meninas a ausência de qualquer característica sexual secundária a partir dos 15 anos de\nidade, considerar retardo puberal.","D":"É frequente ocorrer um corrimento vaginal claro nos 6 aos 12 meses que antecedem a primeira\nmenstruação ou menarca."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-129723","number":"129723","sourceNumber":"129723","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Qual alternativa abaixo NÃO corresponde aos 10 passos para Alimentação\nComplementar Saudável, segundo ENPACS- Ministério da Saúde:","options":{"A":"A alimentação complementar deve ser liquidificada no início para evitar risco de erro alimentar.","B":"Dar somente leite materno até os 6 meses, sem oferecer água, chás ou qualquer outro alimento.","C":"Ao completar 6 meses, dar alimentos complementares (cereais, tubérculos, carnes,\nleguminosas, frutas e legumes) três vezes ao dia,\nse a criança estiver em aleitamento materno.","D":"Estimular a criança doente e convalescente a se alimentar, oferecendo sua alimentação habitual\ne seus alimentos preferidos, respeitando a sua\naceitação."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-129738","number":"129738","sourceNumber":"129738","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A anemia por deficiência de ferro é uma carência nutricional muito frequente nos países\nem desenvolvimento. Quanto ao uso de suplementação\nde ferro profilático, segundo a\nrecomendação da Sociedade Brasileira de Pediatria, 2012, assinale a alternativa INADEQUADA.","options":{"A":"3 mg/kg peso/dia durante um ano e, posteriormente, 1 mg/kg/dia por mais um ano para\nrecém-nascidos pré-termo com peso entre 1.500 e 1.000 g.","B":"2 mg/kg peso/dia durante um ano. Após este período, 1 mg/kg/dia por mais um ano para\nrecém-nascidos pré-termo e/ou de baixo peso até 1.500 g a partir do 30º dia de vida.","C":"Não recomendado para recém-nascidos a termo, de peso adequado para a idade gestacional,\nem uso de 500 ml de fórmula infantil.","D":"3 mg de ferro elementar/kg peso/dia a partir do 6º mês (ou da introdução de outros alimentos)\naté o 24º mês de vida, para recém-nascidos a\ntermo, de peso adequado para a idade gestacional,\nem aleitamento materno."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-129761","number":"129761","sourceNumber":"129761","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A carência nutricional de ferro afeta o desenvolvimento mental de 40 a 60% das\ncrianças. Assinale a alternativa com as\nprincipais alterações bioquímicas encontradas na depleção\nde ferro SEM anemia:","options":{"A":"Hgb, VCM, RDW normais; ferro sérico e ferritina baixos.","B":"Hbg, ferro sérico e ferritina baixos; RDW e VCM normais.","C":"Hgb, ferro sérico, ferritina e VCM baixos; RDW normal.","D":"Hbg, VCM normais; RDW elevado; ferro sérico e ferritina baixos."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-129788","number":"129788","sourceNumber":"129788","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Durante a avaliação de rotina do atendimento de uma criança de 1 ano e 6 meses, os\npais informam que a criança é bem alegre e sorridente, senta sozinha e pega todos os objetos ao\nseu redor. Índices de peso/idade escore-Z entre +2 < -2; IMC entre +1 < -1. De acordo com a\nclassificação do Desenvolvimento Neuropsicomotor (DNPM), pelo método AIDPI/OMS, assinale a\nalternativa mais ADEQUADA para este caso.","options":{"A":"Possível atraso no DNPM; parabenizar a família/mãe e aumentar o estímulo.","B":"Provável atraso no DNPM; encaminhar ao neurologista/pediatra.","C":"Possível atraso no DNPM; encaminhar ao neurologista/pediatra.","D":"Provável atraso no DNPM; parabenizar a família/mãe e aumentar o estímulo."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-129797","number":"129797","sourceNumber":"129797","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Adolescente do sexo masculino vai a consulta de rotina no Programa de Atendimento\ndo Adolescente na Unidade de Saúde do seu Bairro.\nDurante o atendimento médico, descreve peso\nadequado para idade, IMC eutrofia, no desenvolvimento puberal aumento do volume testicular,\nbolsa escrotal, e comprimento do pênis e pelos em toda região pubiana um pouco encaracolados,\nescuros e espessos; orientações gerais, e alimentar, prevenção de agravos e promoção de estilo\nde vida saudável. Assinale a alternativa que corresponde ao estágio puberal de Tanner, do\npaciente no caso acima.","options":{"A":"P2G3.","B":"P2G2.","C":"P3M2.","D":"P3G3."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-107718","number":"107718","sourceNumber":"107718","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A mãe do menor J.K.L. foi ao pediatra pedir orientação alimentar, pois o mesmo está\ncompletando 6 meses em aleitamento materno exclusivo e segundo a vizinha ela deve parar de dar\no leite materno. O médico orienta que ela deve iniciar ALIMENTOS COMPLEMENTARES, o que\nsignifica:","options":{"A":"Conjunto de outros alimentos, além de manter o leite materno oferecido durante o período de\naleitamento.","B":"Fórmulas artificiais.","C":"Conjunto de outros alimentos, substituir o leite materno por leite artificial oferecidos durante\no\nperíodo do primeiro ano de vida.","D":"Conjunto de guloseimas, além do leite materno oferecidos durante o período de aleitamento."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-107732","number":"107732","sourceNumber":"107732","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Duas mães aguardando o atendimento obstétrico conversam sobre a importância da\nalimentação saudável para a Criança, a fim de prevenir obesidade e suas complicações. Diante do\nconceito programação metabólica (Programming) devemos começar o estimulo à alimentação\nsaudável desde a:","options":{"A":"Segunda infância.","B":"Gestação.","C":"Primeira infância.","D":"Lactente."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-107741","number":"107741","sourceNumber":"107741","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Segundo a Organização Mundial de Saúde - OMS e Ministério da Saúde devemos\nestimular o Aleitamento materno exclusivo até e Total até:","options":{"A":"3 meses e 1 ano.","B":"8 meses e 3 anos.","C":"6 meses e 1 ano.","D":"6 meses e 2 anos."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-107823","number":"107823","sourceNumber":"107823","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Paciente de 11 anos de idade, vem à consulta de Pediatria médica sem queixas, o\nPediatra descreve o estágio de Tanner, como M3P3. Qual descrição abaixo corresponde ao\nEstágio de Maturação Sexual descrito pelo Pediatra:","options":{"A":"Projeção da aréola e da papila, formando uma segunda saliência acima do nível da mama. Pêlos\ntipo adulto, ainda em pouca quantidade.","B":"Volume testicular aumentado sem aumento do pênis. Pêlos longos escuros, encaracolados em\ntoda a base do pênis.","C":"Aréola e papila sem separação do contorno da mama, Pêlos mais escuros, pouco\nencaracolados, em toda região pubiana.","D":"Broto mamário, pêlos um pouco escuros na linha central da região pubiana."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-107884","number":"107884","sourceNumber":"107884","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Os pais levam o lactente de 4 meses à consulta de Puericultura referindo que o menor\napresenta 5 episódios de vômitos ao dia, sem outras queixas. Atualmente está em dieta mista:\naleitamento materno e fórmula láctea de partida. Quanto à presença de Doença do Refluxo Gastro\nEsofágico, assinale a assertiva abaixo que NÃO é esperada nesta patologia.","options":{"A":"Pais relatarem sono intranquilo do lactente.","B":"Lactente com irritabilidade.","C":"Presença de esofagite.","D":"Aos 5 meses apresentar o dobro do peso de nascimento."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-107689","number":"107689","sourceNumber":"107689","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A alimentação saudável é fundamental para o bom crescimento e desenvolvimento ao\nlongo da vida, além de previnir doenças e evitar deficiências nutricionais. A infância representa um\nmomento delicado para o desenvolvimento de hábitos alimentares saudáveis, portanto, os\ncuidadores de crianças menores de dois anos devem ser orientados quanto à prevenção de riscos,\na fim de evitar obesidade. Marque V ou F nas seguintes opções: ( ) Incentivar o aleitamento\nmaterno e evitar a superalimentação de bebês alimentados com mamadeira, pois o consumo\nexcessivo de leite de vaca está associado à obesidade entre crianças menores de dois anos. O\nconsumo deve ser limitado a 1000 ml por dia dos seis meses aos dois anos de vida. ( ) Evitar a\nintrodução precoce de sólidos. O tempo adequado para a introdução de sólidos é entre 4 e 6 meses\nde idade. ( ) Dar estimulantes do apetite a crianças que não tem apetite. ( ) Orientar os cuidadores\nsobre importância de refeições específicas por idade, consistência de refeições, tipos de lanches,\nporções adequadas, leitura de rótulos de alimentos e atividades físicas diárias. Avaliando as\npremissas marque a alternativa correta:","options":{"A":"F; V; F; V.","B":"F; F; F; F.","C":"V; V; F; V.","D":"V; F; F; V."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-103796","number":"103796","sourceNumber":"103796","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Qual das doenças hematológicas é a mais comum na infância, acometendo 30% da\npopulação global, sendo que a maioria dos indivíduos afetados vive em países em\ndesenvolvimento?","options":{"A":"Anemia ferropriva.","B":"Anemia megaloblástica.","C":"Anemia falciforme.","D":"Leucemias."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-103829","number":"103829","sourceNumber":"103829","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Quanto ao crescimento da criança, podemos afirmar que:","options":{"A":"No final do segundo ano, o crescimento somático e cerebral desacelera com a correspondente\nredução das exigências nutricionais e do apetite,\ne, por este motivo, cresce, em geral, a queixa de\n\"falta de apetite\" no consultório.","B":"No primeiro ano de vida, a criança cresce, em geral, 15 cm e, no segundo ano, 10 cm ao ano.","C":"A criança deve triplicar o peso de nascimento aos sete meses de idade.","D":"Entre dois e cinco anos, a criança normal ganha aproximadamente 5 a 8 kg e cresce em torno\nde 10 cm ao ano."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-87434","number":"87434","sourceNumber":"87434","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Maria liga para o médico e fala: \"eu sou mãe não faz nem um mês, meu peito esta\nferido e não sei como tratar. Meu bebê\nSofia, chora e toma leite toda hora e toda vez que ela bebe\nleite ela morde e chupa com força e dói e o peito esta ficando cada vez mais ferido\". Pergunta-se\nqual o provável diagnóstico e sua conduta:","options":{"A":"Criança estressada/ Orientar a mãe a acalmar a Criança estressada.","B":"Incoordenação oro-facial / Encaminhar para a Fonoaudióloga.","C":"Depressão maternal/ Encaminhar ao psiquiatra.","D":"É normal /orientar para complementar com fórmula infantil na mamadeira.","E":"Pega incorreta / Procurar com Urgência um profissional em Aleitamento Materno para orientar a\npega correta."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-87448","number":"87448","sourceNumber":"87448","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação à velocidade de crescimento média e à idade das crianças e adolescentes,\né CORRETO afirmar:","options":{"A":"Velocidade de crescimento de 12,5 cm/ano, no primeiro ano de vida.","B":"Velocidade de crescimento de 7 cm/ano, dos 2 aos 4 anos incompletos.","C":"Velocidade de crescimento de 10 cm/ano, dos 6 anos de idade até a puberdade.","D":"Velocidade de crescimento de 25 cm/ano, de 1 a 2 anos incompletos.","E":"A velocidade de crescimento não varia com a idade até a adolescência no estirão puberal."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-87440","number":"87440","sourceNumber":"87440","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O crescimento de uma criança depende de vários fatores intrínsecos e extrínsecos.\nQuanto às variações normais do crescimento,\nassinale a assertiva CORRETA.","options":{"A":"A idade cronológica está compatível com a idade óssea no Atraso Constitucional do\nCrescimento.","B":"Na Baixa Estatura Familiar há história familiar de retardo puberal.","C":"O exame físico é normal para idade cronológica no Atraso Constitucional do Crescimento.","D":"No Atraso Constitucional do Crescimento a idade óssea é compatível com a estatura.","E":"Os exames laboratoriais estão normais para a idade óssea na Baixa Estatura Familiar."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-87458","number":"87458","sourceNumber":"87458","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O desenvolvimento infantil é um processo que abrange vários aspectos. Assinale a\nalternativa abaixo onde o marco do desenvolvimento encontrado corresponde ao esperado para a\nidade:","options":{"A":"9 meses de vida, começa a sustentar a cabeça.","B":"18 meses de vida, corre, anda para trás, fala mais de três palavras.","C":"12 meses de vida, senta-se sem apoio, engatinha.","D":"6 meses de vida, eleva a cabeça quando em decúbito ventral, reage ao som, fixa e acompanha\na face da mãe.","E":"2 meses de vida, senta com apoio, balbucia."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-80992","number":"80992","sourceNumber":"80992","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Entende-se por ALIMENTOS COMPLEMENTARES:","options":{"A":"Conjunto de outros alimentos, além do leite materno oferececidos durante o período de\naleitamento.","B":"Fórmulas artificiais.","C":"Conjunto de outros alimentos, além do leite artificial oferecidos durante o período do primeiro\nano de vida.","D":"Conjunto de guloseimas, além do leite materno oferecidos durante o período de aleitamento.","E":"Aditivos do leite humano."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-81922","number":"81922","sourceNumber":"81922","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Qual o papel do pediatra não especialista no cuidado de crianças com distúrbios raros e\ncomuns?","options":{"A":"Reconhecer os sinais e sintomas, fazer os encaminhamentos, dar suporte à família, planejar\ncuidados a longo prazo. Utilizar testes genéticos para guiar tratamento.","B":"Cuidar de problemas específicos da especialidade.","C":"Desenvolver e interpretar testes, tratar de casos complexos, realizar a consulta familiar; fazer\nterapias baseadas na genética.","D":"Fazer diagnóstico, dar as consultas e cuidados a longo prazo e terapias genéticas.","E":"Auxiliar na interpretação dos resultados de testes; fazer terapias baseadas na genética."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-81063","number":"81063","sourceNumber":"81063","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Duas mães aguardando o atendimento obstétrico conversam sobre a importância da\nalimentação saudável para a criança, a fim de prevenir obesidade e suas complicações. Diante do\nconceito programação metabólica (programming) devemos começar o estímulo à alimentação\nsaudável desde a:","options":{"A":"Pós-menopausa.","B":"Gestação.","C":"Primeira Infância.","D":"Segunda infância.","E":"Lactente."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-81080","number":"81080","sourceNumber":"81080","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Segundo a Organização Mundial de Saúde - OMS e Ministério da Saúde devemos\nestimular:","options":{"A":"Aleitamente materno exclusivo até 3 meses e total de 1 ano","B":"Aleitamente materno exclusivo até 8 meses e total 3 ano","C":"Aleitamento materno exclusivo até 6 meses e total de 1 ano","D":"Aleitamento materno exclusivo até 9 meses e total de 1 ano","E":"Aleitamento materno exclusivo até 6 meses e total de 2 anos"},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-81136","number":"81136","sourceNumber":"81136","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"MST, masculino,14 anos, apresenta palidez, anorexia, astenia e sonolência excessiva.\nEstá crescendo muito rápido, segundo informa mãe.\nQual diagnóstico mais provável?","options":{"A":"Giardíase","B":"Mononucleose","C":"Anemia ferropriva","D":"anemia megaloblástica","E":"depressão"},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-80967","number":"80967","sourceNumber":"80967","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A.N.T., 8 meses, foi levado por sua mãe ao posto e durante exame o pediatra observou\nque o perímetro cefálico estava < - 3\nescore-Z e apresentava atraso de dois marcos de\ndesenvolvimento. Qual impressão diagnóstica e conduta?","options":{"A":"Adequado desenvolvimento. Acalmar a mãe.","B":"Atraso no desenvolvimento. Referir para avaliação neuropsicomotora.","C":"Adequado desenvolvimento. Não registrar na caderneta da criança.","D":"Atraso no desenvolvimento. Brigar com a mãe pela negligência.","E":"Atraso no desenvolvimento. Chamar o conselho tutelar."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-80981","number":"80981","sourceNumber":"80981","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Paciente 12 anos de idade, vem a consulta de Pediatria sem queixas, ao exame físico\napresenta bom estado geral, acianótico, anictério, hidratado, hipocorado, nuca livre, sem alterações\nà ausculta pulmonar e cardíaca, abdome normal sem visceromegalias, genitália presença de pelos\nfinos, lisos, longos escuros na base do pênis, bolsa escrotal afinada e hipervascularizada, aumento\ndo volume testicular sem aumento do tamanho do pênis. Em relação ao Estágio de Maturação\nSexual de Tanner, responda:","options":{"A":"Paciente está em Tanner G3P3","B":"Paciente está em Tanner G2P3","C":"Paciente está em Tanner M1P2","D":"Paciente está em Tanner G2P2","E":"Paciente está em Tanner G3P2"},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-80974","number":"80974","sourceNumber":"80974","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A deficiência de ferro é uma das carências nutricionais mais prevalentes no mundo.\nQuanto à suplementação profilática do ferro\nelementar, qual das alternativas abaixo corresponde às\nrecomendações da Sociedade Brasileira de Pediatria:","options":{"A":"Prematuros maiores que 1500g e recém nascidos de baixo peso a partir do 30º dia de vida,\nrecomenda-se 2mg de ferro elementar/kg/dia durante todo o primeiro ano de vida e após este\nperíodo 1mg/kg/dia até 2 anos de idade.","B":"Prematuros com peso menor que 1000g, a partir do 30º dia de vida, recomenda-se 1mg de ferro\nelementar/kg/dia durante todo o primeiro ano de vida e após este período 2mg/kg/dia até 2 anos de\nidade.","C":"Lactentes nascidos a termo, peso adequado para idade gestacional, em aleitamento materno\nexclusivo, recomenda-se 4mg de ferro\nelementar/kg/dia, a partir do 30º dia de vida e durante todo o\nprimeiro ano de vida. Após este periodo 1mg/kg/dia até 2 anos de idade.","D":"Prematuros com peso entre 1000g e 1500g, recomenda-se 1mg/kg/dia de ferro elementar até os\n2 anos de idade.","E":"No lactente o ferro elementar só deve ser suplementado em caso de documentado de anemia\nferropriva."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-80959","number":"80959","sourceNumber":"80959","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A queixa de \"pouco leite\" ou \"leite fraco\" deve sempre ser valorizada pois, se não\nvalorizada, pode levar ao desmame precoce. Marque a opção CORRETA. 1. Melhorar o\nposicionamento e a pega do bebê, quando não adequados. 2. Oferecer as 2 mamas em cada\nmamada. 3. Diminuir a frequência das mamadas. 4. Trocar de mama várias vezes em uma\nmamada se a criança estiver sonolenta ou se não sugar vigorosamente. 5. Não ordenhar o leite\nresidual.","options":{"A":"V, F, V, F, V.","B":"V, V, F, V, V.","C":"V, V, V, V, F.","D":"V, F, V, F, V.","E":"V, V, F, V, F."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-61481","number":"61481","sourceNumber":"61481","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Segundo as orientações para o atendimento à saúde do adolescente, Ministério da\nSaúde, 2011, quanto ao desenvolvimento puberal normal da menina é correto afirmar, EXCETO:","options":{"A":"O broto mamário é o primeiro sinal puberal na menina.","B":"Os primeiros ciclos menstruais são geralmente anovulatórios e irregulares.","C":"É frequente ocorrer um corrimento vaginal claro nos 36 meses que antecedem a menarca.","D":"As adolescentes podem ainda crescer em média 4 a 6 cm nos 2 ou 3 anos após a menarca.","E":"Deve-se considerar retardo puberal a ausência de qualquer característica sexual secundária a\npartir dos 13 anos de idade."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-61567","number":"61567","sourceNumber":"61567","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considerando que muitos dos profissionais de saúde pouco conhecem sobre o\ndesenvolvimento puberal normal nos meninos, segundo as informações do ministério da saúde\nquanto ao desenvolvimento puberal normal do menino, é correto afirmar, EXCETO:","options":{"A":"O crescimento peniano começa, em geral, um ano após o crescimento dos testículos.","B":"Deve-se considerar retardo puberal a ausência de qualquer característica sexual secundária a\npartir dos 17 anos de idade.","C":"A ginecomastia puberal em 85% dos casos regride espontaneamente até 3 anos do seu\naparecimento durante a fase puberal.","D":"A primeira manifestação da puberdade é o aumento do volume testicular, medido cerca de 3 cc,\nem média aos 10 anos e 9 meses de idade.","E":"O pênis primeiro cresce em tamanho e depois em diâmetro e no final do crescimento puberal\nmede aproximadamente de 12 a 15 cm quando ereto podendo variar de ± 2 a 3 cm."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-61574","number":"61574","sourceNumber":"61574","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Rapaz de 13 anos vem à consulta com queixa de ginecomastia e pênis pequeno. A\nginecomastia surgiu há 6 meses. O exame físico foi normal, exceto por obesidade moderada,\nginecomastia bilateral e \"pênis embutido\". O estadiamento puberal de Tanner é: pêlos pubianos II,\ngenitália III. A conduta adequada neste momento é:","options":{"A":"Referir à psicóloga para acompanhamento.","B":"Encaminhar à genética para fazer cromatina sexual.","C":"Indicar cirurgia para a correção da ginecomastia.","D":"Observar a evolução da ginecomastia por mais um ano.","E":"Solicitar exames laboratoriais para detectar problemas endócrinos."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-61581","number":"61581","sourceNumber":"61581","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação à presença de anemias na infância qual afirmativa NÃO está correta?","options":{"A":"As anemias podem ser decorrentes de alterações na produção; hemólise; perdas sanguíneas.","B":"Correspondem a desordens de produção; desordens imunológicas; falência absoluta da\neritropoiese.","C":"O VCM (Volume Corpuscular Médio) está aumentado na deficiência da vitamina B12 e na\ndeficiência de ácido fólico.","D":"São consideradas desordens por destruição do eritrócito; defeitos estruturais das hemáceas\n(congênitos); desordens imunológicas; destruição não mediada por anticorpos.","E":"A doença falciforme, as talassemias e as deficiências enzimáticas cursam com anemia devido a\ndesordens por destruição dos eritrócitos (hemólise)."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-60883","number":"60883","sourceNumber":"60883","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Qual seria a ação política efetiva para resolver o problema da anemia ferropriva em\nlactentes e pré-escolares em nosso país?","options":{"A":"Aplicar doses preventivas de ferro nos dias nacionais de vacinação.","B":"Contraindicar a alimentação com leite de vaca para todas as crianças.","C":"Treinar pediatras para prevenção do ferro profilático.","D":"Conscientizar as mães para o problema.","E":"Garantir a fortificação exclusiva vit. \"D\"."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-60890","number":"60890","sourceNumber":"60890","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Adolescente de 14 anos procura AAL com queixa de ginecomastia há seis meses e\npênis pequeno. Ao exame: ginecomastia, obesidade moderada, pênis embutido, sem outra\nanormalidade. Estadiamento de Tanner P2 G3. Qual a conduta?","options":{"A":"Solicitar TAC de crânio.","B":"Encaminhar para endocrinologia.","C":"Pedir exame de cromatina sexual.","D":"Observar a evolução da ginecomastia por mais um ano.","E":"Indicar cirurgia para correção da ginecomastia."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-61513","number":"61513","sourceNumber":"61513","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação à velocidade do crescimento esperado para idade, qual das afirmativas\nNÃO representa a média ao ano esperada para idade?","options":{"A":"Lactentes de 0 a 12 meses incompletos, 15 cm/ano.","B":"Lactente de 1 a 2 anos incompletos, 12 cm/ano.","C":"Crianças de 2 a 4 anos incompletos, 7 cm/ano.","D":"Crianças de 4 a 6 anos incompletos, 6 cm/ano.","E":"Crianças de 6 anos até a puberdade, 5 cm/ano."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-46637","number":"46637","sourceNumber":"46637","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Nutriz portadora de citomegalovirose confirmada no pré-natal. Qual a orientação a ser\ndada relacionada ao aleitamento materno, já que seu recém-nascido é de termo?","options":{"A":"Formula láctea.","B":"Diretamente ao seio.","C":"Leite da próxima mãe, após pasteurização.","D":"Leite da próxima mãe, após pasteurização e congelamento a 20°C.","E":"Leite da própria mãe, após congelamento a 20°C."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-46689","number":"46689","sourceNumber":"46689","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"São contraindicações absolutas de aleitamento materno EXCETO:","options":{"A":"HTLV.","B":"HIV.","C":"Hepatite B.","D":"Galactosemia.","E":"Nenhuma das alternativas anteriores."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-324692","number":"324692","sourceNumber":"324692","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Adolescente, sexo feminino, 15 anos de idade, é levada a consulta de rotina por sua\nmãe. Reluta para permitir o exame fisico. Ao\nconversar, sem a presença materna, relata que tem se\ncortado com gilete nos antebraços, mas seus pais não tem conhecimento do fato pois tem usado\nmangas compridas para cobrir os ferimentos. Refere término de namoro com um rapaz de 16 anos\nde idade, com quem teve iniciação sexual, de forma voluntária. Relata fazer uso de contraceptivos\ne deseja saber se deve continuar. Tem obtido notas medianas na escola. Define-se viciada em\ninternet e jogos eletrônicos, passando mais de 6 horas por dia em uso de telas. Informa que tem\npoucos amigos. Ao exame físico: em bom estado geral, lúcida, orientada; comunica-se pouco na\npresença da mãe; demonstra tristeza; fala sobre namoro terminado, hipervalorizando a situação\ncom conteúdo negativo. Demonstra sofrimento, autocrítica e baixa autoestima. Apresenta várias\nlesões cicatriciais em Atebraços. Sem outros achados anormais. Indique a conduta médica\nadequada, definida pelas normativas éticas nessa situação, com relação à mãe e à\nconfidencialidade da consulta, no que diz respeito aos indícios de autoagressão:","options":{"A":"A mãe deve ser informada no momento da consulta, sem a presença da paciente, pois há risco\nde vida por autoagressão.","B":"Caso a paciente escolha uma pessoa adulta para interlocução essa deve ser, necessariamente,\nseu responsável legal.","C":"Pode ser pactuado que a própria adolescente converse com a mãe, pois esta deve ser\ninformada, já que há risco com a autoagressão.","D":"A mãe não deve ser informada, pois afetaria a autonomia da paciente, sendo o sigilo um direito\ndo paciente adolescente."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-324693","number":"324693","sourceNumber":"324693","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Adolescente, sexo feminino, 15 anos de idade, é levada a consulta de rotina por sua\nmãe. Reluta para permitir o exame fisico. Ao\nconversar, sem a presença materna, relata que tem se\ncortado com gilete nos antebraços, mas seus pais não tem conhecimento do fato pois tem usado\nmangas compridas para cobrir os ferimentos. Refere término de namoro com um rapaz de 16 anos\nde idade, com quem teve iniciação sexual, de forma voluntária. Relata fazer uso de contraceptivos\ne deseja saber se deve continuar. Tem obtido notas medianas na escola. Define-se viciada em\ninternet e jogos eletrônicos, passando mais de 6 horas por dia em uso de telas. Informa que tem\npoucos amigos. Ao exame físico: em bom estado geral, lúcida, orientada; comunica-se pouco na\npresença da mãe; demonstra tristeza; fala sobre namoro terminado, hipervalorizando a situação\ncom conteúdo negativo. Demonstra sofrimento, autocrítica e baixa autoestima. Apresenta várias\nlesões cicatriciais em Atebraços. Sem outros achados anormais. Considerando as especificidades\ndas consultas médicas para o público adolescente, pode-se dizer que","options":{"A":"A presença de atendente durante o exame físico não é recomendável.","B":"A consulta deve ter momentos com e sem a presença dos pais ou responsáveis.","C":"Os pais não devem participar do momento da entrevista com o/a adolescente.","D":"A presença de atendente na sala, durante o exame físico, precisa ter concordância do/da\nadolescente."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-324694","number":"324694","sourceNumber":"324694","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Adolescente, sexo feminino, 15 anos de idade, é levada a consulta de rotina por sua\nmãe. Reluta para permitir o exame fisico. Ao\nconversar, sem a presença materna, relata que tem se\ncortado com gilete nos antebraços, mas seus pais não tem conhecimento do fato pois tem usado\nmangas compridas para cobrir os ferimentos. Refere término de namoro com um rapaz de 16 anos\nde idade, com quem teve iniciação sexual, de forma voluntária. Relata fazer uso de contraceptivos\ne deseja saber se deve continuar. Tem obtido notas medianas na escola. Define-se viciada em\ninternet e jogos eletrônicos, passando mais de 6 horas por dia em uso de telas. Informa que tem\npoucos amigos. Ao exame físico: em bom estado geral, lúcida, orientada; comunica-se pouco na\npresença da mãe; demonstra tristeza; fala sobre namoro terminado, hipervalorizando a situação\ncom conteúdo negativo. Demonstra sofrimento, autocrítica e baixa autoestima. Apresenta várias\nlesões cicatriciais em Atebraços. Sem outros achados anormais. Com relação à demanda quanto\nao uso de contraceptivos, considerando as indicações éticas da Sociedade Brasileira de Pediatria.","options":{"A":"está contraindicado pela imaturidade hormonal da paciente e deve ser comunicado à mãe.","B":"está contraindicado pela imaturidade hormonal da paciente e não deve ser comunicado à mãe.","C":"está indicado e é direito da adolescente usar sem informação parental e deve ser prescrito de\nforma adequada","D":"é indicado e o sigilo deve ser quebrado, pois é dever dos parentes participar das decisões\nquanto à saúde reprodutiva da adolescente."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-294487","number":"294487","sourceNumber":"294487","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Adolescente, 16 anos de idade, é levada à UPA pela mãe, por ter sido agredida\nfisicamente há, aproximadamente, 3 horas. O\nrelato é de que o padrasto a espancou ao chegar,\nalcoolizado, em casa. O médico observa que a menor está tensa e retraída, limitando-se a\nresponder com a cabeça às suas perguntas, enquanto a genitora relata o quadro que encontrou em\ncasa. Identifique a atitude mais adequada do médico ao proceder à anamnese.","options":{"A":"Solicitar a presença do padrasto durante a anamnese e acareá-lo para obter a verdade.","B":"Solicitar que a menor faça o relato detalhado examiná-la na presença da genitora.","C":"Solicitar a presença de uma testemunha durante anamnese e o exame físico.","D":"Solicitar à mãe que lhe permita uma conversa só com a menor, antes do exame físico."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-62879","number":"62879","sourceNumber":"62879","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A respeito das comorbidades em crianças com HIV/AIDS, é correto afirmar, EXCETO:","options":{"A":"A pneumonia por Pneumocystis jirovecii (antes denominada Pneumocystis carinii) é a mais\nfrequente infecção oportunista em crianças\ninfectadas pelo HIV. A faixa de maior risco é a do\nprimeiro ano de vida, quando o diagnóstico definitivo da infecção pelo HIV, na maioria das crianças\nexpostas, ainda não pode ser feito.","B":"Recomenda-se que todas as crianças expostas recebam profilaxia com\n\nSulfametoxazol-Trimetoprima (SMX-TMP) a partir de seis semanas de vida até completar um ano,\nexceto se a hipótese de infecção pelo HIV puder ser afastada durante o período. Essa profilaxia é\nmantida depois do primeiro ano de vida somente para as crianças infectadas quando a indicação\nserá orientada pela contagem de células TCD4+.","C":"Em crianças, a transmissão vertical do HTLV-1 ocorre exclusivamente pelo leite materno de\nmulheres infectadas, não ocorrendo naquelas que recebem leite artificial.","D":"A infecção precoce do HTLV-1 na criança é uma importante preocupação para a saúde pública,\npois está associada com subsequente risco de\ndesenvolver linfoma não Hodgkin, leucemia/linfoma\nde células T do adulto, dermatite e paraparesia espástica tropical.","E":"A transmissão perinatal do vírus da hepatite B acontece predominantemente como resultado da\nexposição da criança a sangue e secreções genitais da mãe durante o parto e trabalho de parto\n(cerca de 90 a 95% dos casos). A transmissão intraútero é incomum (5 a 10%) e pelo colostro é\nrara."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343349","number":"343349","sourceNumber":"343349","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com quais idades considera-se puberdade precoce em meninos e meninas?","options":{"A":"Entre 8 e 13 anos nas meninas e entre 9 e 14 anos nos meninos.","B":"Entre 6 e 8 anos nas meninas e entre 7 e 9 anos nos meninos.","C":"Antes dos 8 anos em meninas e 9 anos em meninos.","D":"Antes de 9 anos em meninas e 11 anos em meninos."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343350","number":"343350","sourceNumber":"343350","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação à puberdade em meninos e meninas assinale a alternativa correta.","options":{"A":"Em meninas, o início da puberdade é marcado pela menarca.","B":"A puberdade inicia-se entre 8 e 13 anos nas meninas e entre 9 e 14 anos nos meninos.","C":"Em meninos, o início da puberdade é marcado por pelos corporais generalizados.","D":"A puberdade precoce sempre vai ser central."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343351","number":"343351","sourceNumber":"343351","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um adolescente de 13 anos de idade, sexo masculino, relata o aumento da mama\ndireita há 6 meses. Ao exame físico apresenta\ntecido mamário subareolar palpável bilateralmente,\ntestículos com 10ml e pelos axilares, com pelos pubianos e genitália no estágio 3 de Tanner. Qual\na conduta mais indicada nesse momento?","options":{"A":"Acompanhamento clínico.","B":"Cirurgia para remoção das mamas.","C":"Tratamento com inibidores de aromatase.","D":"Tratamento com antagonistas de estrogênio."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343353","number":"343353","sourceNumber":"343353","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um menino apresenta aumento de pênis em seu comprimento, testículos com 10cc,\npelos escuros, grossos e crespos no saco escrotal e na linha média acima de pênis, bem como\npelos finos acima do lábio superior, acne, mudança da voz e início do estirão puberal. Qual é a\nclassificação de Tanner para seu estágio puberal?","options":{"A":"G3P3","B":"G2P2","C":"G4P3","D":"G3P2"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-281863","number":"281863","sourceNumber":"281863","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Assinale a alternativa correta em relação à media de sono diária recomendada para\numa criança de 6 a 13 anos.","options":{"A":"7 a 8 horas.","B":"8 a 9 horas.","C":"9 a 10 horas.","D":"9 a 13 horas."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-283858","number":"283858","sourceNumber":"283858","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"As práticas alimentares no primeiro ano de vida exercem um importante papel na\nformação dos hábitos da criança. Sobre as\npráticas alimentares recomendadas no primeiro ano de\nvida, é correto afirmar que","options":{"A":"o suco de fruta pode e deve ser introduzido aos seis meses de vida em substituição às frutas.","B":"se preconiza amamentação exclusiva até o quarto mês de vida, e, a partir dessa idade, a criança\ndeve receber alimentos complementares.","C":"proteínas como carne moída e peixe devem ser inseridos ao se introduzir os alimentos\ncomplementares no sexto mês de vida. A demora\nna introdução desses alimentos pode aumentar o\nrisco de anemia ferropriva.","D":"se recomenda que, a partir de três meses, a criança receba duas papas de frutas nos lanches e\numa papa principal, que poderá ser oferecida no almoço, com alimentos bem cozidos para que\npossam ser amassados.","E":"papas industrializadas, além de não serem adequadas do ponto de vista nutricional, não são\nseguras em termos de segurança alimentar, portanto não devem ser oferecidas às crianças\nmenores de dois anos, mesmo em situações em que não seja possível oferecer papa caseira."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-250010","number":"250010","sourceNumber":"250010","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Puérpera na segunda semana, apresentando mamas flácidas e com pouco leite. O\ndiagnóstico e tratamento adequado são:","options":{"A":"Hipogalactia / Ocitocina spray nasal.","B":"Ectasia ductal / Sulpirida.","C":"Hipogalactia / Sulpirida.","D":"Ectasia ductal / Ocitocina spray nasal."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-218136","number":"218136","sourceNumber":"218136","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considerando o crescimento e desenvolvimento da criança, analise as assertivas e\nidentifique com V as verdadeiras e com F as falsas. ( ) A prematuridade, a hipóxia neonatal, as\ninfecções congênitas e a herança genética são consideradas fatores de risco para problemas\nfuturos de desenvolvimento. ( ) Caso os testículos sejam impalpáveis na bolsa escrotal na consulta\ndo primeiro mês de vida, deve-se solicitar ecografia (ultrassom) e encaminhar o lactente para\navaliação cirúrgica. ( ) Diagnosticada hérnia inguinal, é indicada observação até o sexto mês de\nvida, quando a criança deve ser encaminhada para cirurgia caso não haja resolução espontânea do\nquadro. ( ) O primeiro sinal de puberdade esperado em meninas é o surgimento de broto mamário\n(telarca), uni ou bilateral, e é considerada puberdade precoce nas meninas o desenvolvimento das\ncaracterísticas sexuais secundárias antes da idade de oito anos. A alternativa que contém a\nsequência CORRETA, de cima para baixo, é:","options":{"A":"V, V, F, F.","B":"V, F, F, V.","C":"V, F, V, F.","D":"F, V, V, F.","E":"F, F, V, V."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-218148","number":"218148","sourceNumber":"218148","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Segundo as Diretrizes Nacionais da Saúde sobre a necessidade e a suplementação de\nferro para as crianças até dois anos de vida, é CORRETO afirmar que:","options":{"A":"O período de maior risco para a carência de ferro é o primeiro semestre de vida.","B":"Crianças em aleitamento materno não necessitam da suplementação de ferro no 1° ano de vida.","C":"Crianças em uso de fórmulas com leite de vaca devem receber suplementação de ferro após\nseis meses de vida.","D":"A Equipe de Saúde da Família deve realizar exame laboratorial de rotina para anemia e, em\nfunção dos resultados, prescrever a suplementação de ferro.","E":"Crianças com mais de 6 meses de vida até os 24 meses devem receber a suplementação de\nferro independente da realização de exames\ncomplementares, sendo período mais crítico o de 6 a\n12 meses."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-218184","number":"218184","sourceNumber":"218184","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Maria Aparecida, negra, 36 anos, bem-humorada, compareceu à Unidade Básica de\nSaúde onde tem como equipe: a agente de\nsaúde Filomena, a técnica de enfermagem Carla, o\nenfermeiro Mário e a médica Daiane. Maria Aparecida tem uma história de realização de\nCitopatológico (CP) de colo de útero com uma certa regularidade. Seu último exame foi há 3 anos,\nquando era casada com Paulo, uma relação que durou 7 anos. O resultado fora normal. Na mesma\nocasião, em uma campanha de educação em saúde promovida pelo Ministério da Saúde e\nSecretarias de Saúde do Estado e do Município, Maria fez a mamografia também com resultados\nnormais. Maria Aparecida teve menarca aos 13 anos, sexarca aos 16 anos. Teve uma filha, Lelê, e\num filho, Carlinhos, com Paulo. Duas gestações com dois partos vaginais. Maria Aparecida\nmenstrua regularmente. Sem casos conhecidos de câncer de mama na família. Divorciou-se de\nPaulo há 2 anos: me libertei doutora - sempre dizia à Daiane. Recentemente, conheceu um homem\nde 30 anos, Valdomiro, com quem está namorando e já está pensando em se \"juntar\". Maria é\nhipertensa em uso de enalapril 10 mg de 12/12 horas. Na consulta, observou-se PA 140/90 mmHg,\npesa 78 kg, mede 1,60 m de altura (IMC 30,5). Maria Aparecida e Valdomiro chegam felizes da vida\ncom a pequena Mara no colo. Depois de ser paparicada por todos profissionais da Unidade de\nSaúde, \"Má\", como os pais a chamam, chega finalmente para a consulta com Daiane. Embora\ntenham participado do pré-natal, Maria Aparecida e Valdomiro trazem muitas dúvidas sobre a\namamentação, e Ele, ansioso e com caderninho e caneta nas mãos, já quer montar um calendário\ncom a descrição da alimentação complementar após o período de amamentação exclusiva. Daiane\norienta calma, e esclarece todas as questões, aguardando o tempo de Valdomiro anotar ante o\nsorriso de Maria, que mistura satisfação com divertimento ante a postura sistemática de seu\ncompanheiro. Sobre a amamentação e a alimentação da criança nos primeiros anos de vida,\nsegundo as orientações do Ministério da Saúde, analise as assertivas e identifique com V as\nverdadeiras e com F as falsas. ( ) As frutas devem ser oferecidas amassadas logo no início da\nalimentação complementar e, também, sobre a forma de suco. A papa salgada deve ser iniciada no\n7° mês com legumes e verduras, inicialmente, colocadas no liquidificador e peneiradas, e, somente\n\ndepois, amassadas, e com ovos e carnes introduzidos na mesma, preferencialmente, após o 8°\nmês de vida. ( ) Uma queixa muito comum\nnas primeiras consultas de puericultura é a de \"pouco\nleite\" ou \"leite fraco\". Para estas situações, as diretrizes nacionais sugerem à mãe uma dieta\nhiperproteica; aumentar a frequência das mamadas, se possível de três em três horas no máximo,\nestimulando a criança; ordenar o leite residual; e usar protetores intermediários de mamilos para o\ncaso de dor ou fissuras. ( ) Recomenda-se a amamentação exclusiva até os seis meses. Dentre as\ndiversas razões, do ponto de vista do desenvolvimento da criança é importante observar que, até o\n4° mês, a criança ainda não atingiu o desenvolvimento fisiológico necessário para que possa\nreceber alimentos sólidos (reflexo de protrusão ainda regredindo, não senta sem apoio e não tem\ncontrole neuromuscular da cabeça e pescoço para mostrar desinteresse ou saciedade). Dos 4 aos\n6 meses, a aceitação e tolerância da alimentação pastosa melhoram sensivelmente devido às\nfunções gastrointestinal e renal, mas é por volta dos 6 meses que a tolerância gastrointestinal e a\ncapacidade de absorção de nutrientes atingem um nível satisfatório. As crianças com aleitamento\nexclusivo desenvolvem mais cedo o autocontrole da ingestão aprendendo a distinguir as sensações\nde fome, durante o jejum, e de saciedade, após a alimentação. A alternativa que contém a\nsequência CORRETA, de cima para baixo, é:","options":{"A":"V, F, F.","B":"V, V, F.","C":"F, F, V.","D":"F, V, F.","E":"F, V, V."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-139745","number":"139745","sourceNumber":"139745","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação à anticoncepção na adolescência, aponte a alternativa CORRETA:","options":{"A":"Condom e geleia espermaticida aplicados conjuntamente.","B":"Em geral não se indicam pílulas anticoncepcionais na fase de ciclos menstruais irregulares\npós-menarca.","C":"Em emergência pós-coital, a ?pílula do dia seguinte? deve ser utilizada dentro das primeiras 72\nhoras após o intercurso.","D":"Todas as alternativas estão corretas."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134787","number":"134787","sourceNumber":"134787","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A puberdade precoce deve sempre ser bloqueada com a GnRH quando apresentar as\nseguintes características. Analise-as. I. Ser dependente de gonadotrofinas.; II. Ter evolução\nrápida.; III. Ter previsão de estatura final prejudicada.; IV. Apresentar comprometimento evidente\ndo ponto de vista psicológico e/ou social. Estão CORRETAS, as características contidas em:","options":{"A":"I e II, apenas.","B":"I e IV, apenas.","C":"II e III, apenas.","D":"I, II, III e IV."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134790","number":"134790","sourceNumber":"134790","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em meninos, qual é a idade limite inferior da normalidade para o início da\npuberdade e a característica sexual presente MAIS frequente?","options":{"A":"8 anos e aumento do pênis.","B":"8 anos e pelos pubianos.","C":"9 anos e pelos pubianos.","D":"9 anos e aumento testicular."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-139783","number":"139783","sourceNumber":"139783","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Mulher, com sorologia para HIV positiva, dá à luz a recém-nascido (RN) com 3.000 g. A\nsorologia para HIV do RN, pelo ELISA, revela-se positiva. A amamentação dessa criança deve ser:","options":{"A":"incentivada, uma vez que o risco de aquisição da doença pelo aleitamento materno é baixo.","B":"incentivada, uma vez que a sorologia do RN é positiva.","C":"substituída por aleitamento artificial, uma vez que o risco de aquisição da doença através do\naleitamento é elevado.","D":"incentivada apenas se a mãe e o RN submeterem-se a tratamento com drogas antirretrovirais."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134673","number":"134673","sourceNumber":"134673","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Dentre os principais hormônios ligados na síntese primária da caseína do leite e na\nejeção do leite estão, respectivamente:","options":{"A":"TRH e prolactina.","B":"Prolactina e ocitocina.","C":"Prolactina e dopamina.","D":"Ocitocina e TRH."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-111934","number":"111934","sourceNumber":"111934","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Adolescente de 15 anos é trazida ao consultório pela mãe porque apresentou menarca\nhá 2 meses e depois não menstruou mais.\nPaciente nega relações sexuais. Trouxe beta BCG\nnegativo realizado por conta própria. Exame físico sem alterações, hímem íntegro. Que tipo de\norientação será necessária?","options":{"A":"Solicitar RNM de abdômen.","B":"Tranquilizar a mãe e orientar que os primeiros ciclos menstruais podem ser irregulares.","C":"Solicitar dosagens hormonais: FSH / LH / Testosterona.","D":"Iniciar anticoncepcional oral."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-111851","number":"111851","sourceNumber":"111851","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Mãe procura você no consultório para acompanhamento do bebê. Lactente encontra-se\ncom 6 meses de idade, em aleitamento materno\nexclusivo, sem alterações ao exame físico.\n\nDesenvolvimento neuropsicomotor adequado, crescimento, peso no percentil 20% e estatura no\npercentil 25%. O que você orientaria para a mãe?","options":{"A":"Manter aleitamento materno exclusivo e retornar em 1 mês para pesar.","B":"Manter aleitamento materno e iniciar papas.","C":"Suspender aleitamento materno, iniciar fórmula infantil e retornar em 1 mês para pesar.","D":"Manter aleitamento materno e associar leite integral com frutas."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-350821","number":"350821","sourceNumber":"350821","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma alimentação adequada e saudável é fundamental para o crescimento e\ndesenvolvimento da criança. A partir dos 6\nmeses o aleitamento materno deve ser mantido e novos\nalimentos devem ser oferecidos, com diversidade de cores sabores, texturas e cheiros. Quanto à\nintrodução da alimentação complementar, é correto afirmar:","options":{"A":"As frutas devem ser ofertadas na forma de suco, raspadas ou amassadas.","B":"Não é recomendável a oferta de leite materno no horário dos lanches e das papas principais.","C":"Para facilitar a aceitação, a papa principal pode ser processada, em mixer ou liquidificador, e\nofertada na colher.","D":"A papa principal deve ser composta por 1 alimento dos grupos: cereais ou tubérculos; feijões; 1\nou mais legumes e verduras, 1 alimento do\ngrupo das carnes e ovos."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-350817","number":"350817","sourceNumber":"350817","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma determinada mãe está preocupada com o desenvolvimento do filho para aceitar\nmensagens de que NÃO pode fazer determinadas coisas. Nesses momentos ele costuma reagir\ncom crises intensas de birra. Essa mesma mãe compreende que o comportamento de birra significa\na tentativa da criança de alcançar um objetivo ao tempo em que revela que ela já compreende as\nregras e reluta em aceitá-las. Em que idade (em anos) a criança já é capaz de utilizar\nadequadamente a linguagem para compreender explicações e ir reduzindo suas reações birrentas?","options":{"A":"Dois anos.","B":"Três anos.","C":"Quatro anos.","D":"Cinco anos."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-350816","number":"350816","sourceNumber":"350816","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Na Puericultura, o mais frequente é o médico atender crianças com desenvolvimento da\nlinguagem e da comunicação em contextos que possibilitam desenvolvimento típico. Qual a\nalternativa correta em relação aos marcos de desenvolvimento das crianças nessa área da\nlinguagem?","options":{"A":"12-18 meses: ainda com dificuldade para compreender e reconhecer boa parte das situações e\nobjetos que fazem parte de seu cotidiano; compreende ordens ou solicitações simples (<me dê a\nbola=).","B":"2-3 anos: estabelece relações entre objetos e palavras, amplia o tempo de atenção e\nconcentração, não segue as instruções com 2\nou 3 etapas, nem fala o primeiro nome, idade e sexo.","C":"Entre 4-5 anos, adquiriu um vocabulário alargado, manifestando um grande interesse pela\nlinguagem. Apresenta grande curiosidade e faz muitas perguntas, gostando de contar e inventar\nhistórias.","D":"Entre 5-6 anos aprecia conversar durante as refeições, realizando muitos questionamentos (fase\ndos porquês?); ainda não utiliza corretamente o\nplural, os pronomes e tempos verbais."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-321319","number":"321319","sourceNumber":"321319","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Recém-nascido termo, 6 dias de vida, peso de 3100g, em aleitamento materno\nexclusivo, vem ao posto de saúde para coleta\ndo teste do pezinho. Sendo observado icterícia Zona\n2 de Kramer. Relato de 7 diureses e 6 evacuações nas últimas 24 horas, com fezes amarelas,\nexplosivas e pastosas. Nasceu de parto vaginal, hospitalar, com 3300g, recebendo alta com 30\nhoras de vida. A mãe fez pré-natal sem intercorrências e tem tipo sanguíneo A+. Qual a melhor\nconduta para o bebê?","options":{"A":"Internação hospitalar para investigar e tratar a icterícia.","B":"Manter o aleitamento materno exclusivo e retorno com 1 mês de vida.","C":"Internação hospitalar para investigação e tratamento do quadro diarreico.","D":"Solicitar exames ABO, Rh, bilirrubinas e hemograma completo de urgência."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-321321","number":"321321","sourceNumber":"321321","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Puérpera, de parto vaginal, que fez pré-natal sem intercorrências, está no alojamento\nconjunto com seu filho que nasceu a termo\ncom peso de 3200 g. Ela considera ter leite insuficiente\npara o filho que chora com frequência. O bebê tem 24 horas de vida, com exame físico normal,\nevacuou e apresentou duas diureses. Dentre as abaixo citadas, qual a melhor conduta a ser\norientada?","options":{"A":"Aleitamento materno em livre demanda com aumento da frequência das mamadas.","B":"Associar o uso de outro leite após a mamada até que ocorra a apojadura e o bebê aumente a\ndiurese.","C":"Aleitamento materno com orientação para aumentar o tempo de mamada e pelo menos de 3/3\nhoras.","D":"Aleitamento materno e solicitação de exames complementares (hemograma, proteína C reativa,\neletrólitos e glicemia)."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-321330","number":"321330","sourceNumber":"321330","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma criança de 3 meses de vida comparece à consulta de rotina e a mãe queixa-se\nque o bebê está \"abusando o peito\" pois\ntem mamado pouco tempo (menos de 10 minutos/vez),\ncerca de 8 vezes ao dia. Apresenta diurese de 6-8 vezes ao dia, evacua 1 vez a cada dois dias e\nganhou 25 gramas de peso/dia e 2 cm no perímetro cefálico no último mês. Apresenta sorriso social\ne sustenta a cabeça. Qual a melhor orientação para esta criança?","options":{"A":"Agendar consulta de puericultura de rotina já que criança está eutrófica.","B":"Orientar ordenha de leite e ofertar ao final da mamada, com reavaliação em uma semana.","C":"Introduzir fórmula infantil como suplementação após a mamada, reavaliando a criança em 15\ndias.","D":"Introduzir novos alimentos (sucos e papinha de frutas), manter o aleitamento materno e solicitar\nexames (hemograma e urina tipo 1)."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-321331","number":"321331","sourceNumber":"321331","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A mãe de uma criança de 2 anos de idade vem à consulta preocupada com os hábitos\nalimentares de seu filho. Qual das alternativas é a correta em relação às orientações para hábitos\nalimentares saudáveis de crianças dessa faixa de idade?","options":{"A":"Pode-se oferecer refrigerantes, sucos de caixinha e alguns tipos de balas e doces.","B":"Pode-se oferecer líquidos durante a refeição, como água, sucos; evitar refrigerantes.","C":"Fazer a adequação do prato de acordo com a necessidade da criança, evitando deixar a criança\nrepetir.","D":"A sobremesa pode ser oferecida como parte da refeição, não como recompensa; deve-se dar\npreferência às frutas."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-321335","number":"321335","sourceNumber":"321335","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma senhora vem à consulta de rotina e deseja saber do médico algumas das\ncaracterísticas de desenvolvimento normais para seu filho de 15 meses de idade. Assinale a\nalternativa correta.","options":{"A":"É precária a demonstração de afeto por pessoas conhecidas.","B":"Nessa idade, a criança já regulou os acessos de raiva quando frustrada.","C":"A criança ainda não compartilha, com os outros objetos, que considera interessante.","D":"A criança já é capaz de explorar sozinha o ambiente em que está na presença vigilante dos pais."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-321362","number":"321362","sourceNumber":"321362","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"CVA, 25 anos, G1P1A0, primeiro pós-operatório de cesárea, realizada com 39 semanas\nde gestação, por conta de herpes genital em\natividade. Encontra-se em uso de aciclovir, e\nquestiona seu obstetra sobre riscos na amamentação. Sobre amamentação, marque a alternativa\ncorreta.","options":{"A":"São condições relacionadas à mãe que contraindicam a amamentação: ser portadora do vírus\nHIV, ter tuberculose ativa não tratada e estar na vigência de infecção perinatal por varicela.","B":"A prática do desmame bilateral intermitente em mamas túrgidas, a hidratação materna vigorosa\ne o uso de corticoterapia tópica são medidas\nque previnem a ocorrência de mastite puerperal.","C":"No caso da paciente acima, a amamentação não deve ser descontinuada devido ao uso de\naciclovir. Outras drogas que não contraindicam a amamentação são: sertralina, losartana e\nmetotrexato.","D":"Podemos considerar a diminuição do risco de estenose hipertrófica do piloro, um melhor aporte\nnutricional e o fortalecimento da imunidade, como sendo benefícios da amamentação para o\nrecém-nascido."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-292831","number":"292831","sourceNumber":"292831","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um casal de adolescentes traz seu filho de 6 meses à Unidade de Saúde, preocupado\nse seu desenvolvimento está se dando de forma\nnormal. O lactente nasceu a termo e está em\naleitamento materno exclusivo. Ao examiná-lo, o médico orienta o casal em relação à aquisição de\nnovas habilidades pelo bebê. Aos 6 meses, o que se espera que um lactente com desenvolvimento\nnormal seja capaz de fazer?","options":{"A":"Arrastar-se e dar \"\"tchau\"\".","B":"Engatinhar e bater palmas.","C":"Ficar em pé com apoio e falar ao menos 1 palavra com sentido.","D":"Segurar um objeto com as duas mãos, levá-lo à boca e rolar no leito."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-292835","number":"292835","sourceNumber":"292835","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O Guia Alimentar para crianças brasileiras menores de 2 anos trouxe uma atualização\nde Dez Passos para Doze Passos para uma\nAlimentação Saudável, ampliando a importância do\nconhecimento na manutenção da alimentação saudável no lactente. Qual recomendação é dada\npelo Guia Alimentar para crianças brasileiras menores de 2 anos acerca da oferta da alimentação\ninfantil?","options":{"A":"Não deve ser oferecido açúcar nem preparações ou produtos que contenham açúcar à criança\naté 2 anos de idade.","B":"Podem ser oferecidos à criança menor de 2 anos alimentos preparados em casa com pequenas\nquantidades de açúcar.","C":"Produtos ultraprocessados que não contenham açúcar em suas preparações, podem ser\noferecidos a partir de 1 ano de idade.","D":"Para uma alimentação variada, oferecer à criança, além de água própria para o consumo, sucos\ne outras bebidas açucaradas."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-292845","number":"292845","sourceNumber":"292845","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Na Atenção Básica de Saúde você atende uma puérpera amamentando seu filho de 45\ndias de vida. Ela informa suas dúvidas acerca do bem estar do filho por causa do ritmo de\nmamadas, do sono e do ganho de peso dele. Qual a alternativa correta em relação a tais aspectos?","options":{"A":"Se a mãe estiver acima do peso é recomendável iniciar dieta para emagrecimento e aumentar a\ningesta de líquidos.","B":"Se o bebê dorme bem, está ganhando peso (curva de crescimento revela percentil 15, a\nquantidade de leite deve estar sendo suficiente para ele.","C":"Essa puérpera deveria ter uma alimentação saudável, tomar líquidos em quantidade suficiente\npara saciar a sede e incluir alimentos\nhipercalóricos.","D":"Se após a mamada, a mãe percebe que o bebê está satisfeito, mas ela ainda tem muito leite,\ndeveria continuar oferecendo a mama até sentir que elas esvaziaram."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-259733","number":"259733","sourceNumber":"259733","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Os pais de um bebê recém-nascido vão ao seu primeiro atendimento ambulatorial de\npuericultura. Um momento de estabelecimento de vínculo entre o pediatra e os pais. Assinale a\nalternativa verdadeira onde encontramos requisitos básicos para que a consulta se estabeleça com\nacolhimento e empatia.","options":{"A":"É importante chamar os pais de \"\"mãezinha\"\" e \"\"paizinho\"\" para personalizar o atendimento e\naproximá-los do médico pediatra.","B":"Deve-se buscar conhecer, com gentileza, as condições financeiras, o ambiente físico, social e\nfamiliar no qual o bebê se desenvolverá.","C":"Fatores ecológicos de moradia e conferência da vacinação são atributos da consulta de\nenfermagem antes do atendimento médico.","D":"Não é necessário saber o grau de relacionamento dos pais ou se moram juntos para evitar a\ninvasão da privacidade dos mesmos."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-259734","number":"259734","sourceNumber":"259734","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Mãe leva filho de 6 meses para consulta de puericultura em unidade básica de saúde.\nCriança em aleitamento materno exclusivo com bom ganho ponderoestatural e genitora deseja\nsolucionar algumas dúvidas em relação à alimentação do seu filho. Baseado no Guia Alimentar\npara Crianças Brasileiras Menores de 2 Anos (Ministério da Saúde, 2019), o pediatra orientou\nCORRETAMENTE:","options":{"A":"Introduza ovos, peixe e outros alimentos potencialmente alergênicos a partir do 9º mês de vida.","B":"Priorize o uso de mel de abelha em relação a açúcar para adoçar sucos e outras preparações do\nbebê.","C":"Interrompa o aleitamento materno assim que o bebê começar a ter 4 refeições (lanche da\nmanhã, lanche da tarde, almoço e jantar).","D":"Ofereça inicialmente alimentos com consistência pastosa (papas/purês) e, gradativamente,\naumente a consistência até chegar à\nalimentação da família."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-259748","number":"259748","sourceNumber":"259748","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um adolescente de 14 anos é trazido à consulta e seus pais queixam-se de que ele\nmudou completamente o modo de relacionar-se em\ncasa. Não aceita mais os padrões vigentes na\nfamília, não mantém mais suas coisas arrumadas e passa muitas horas ouvindo música com o som\nexcessivamente alto. Na escola, o padrão de comportamento de Pedro é normal, não havendo\nqualquer queixa dos professores. É um aluno bastante responsável com suas obrigações\nescolares. Ao orientar a família, qual a explicação que o médico deve fornecer à família sobre o\ncomportamento do filho?","options":{"A":"Está apresentando a Síndrome da Personalidade Dupla.","B":"Está vivenciando um evidente conflito e deve ser encaminhado à psicoterapia.","C":"Está apresentando características normais, assumindo identidades circunstanciais.","D":"Está vivenciando um intenso conflito e a melhor abordagem é a farmacológica."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-259762","number":"259762","sourceNumber":"259762","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente, de 4 meses, comparece à Unidade de Saúde acompanhado de sua mãe de\n18 anos. É atendido pela primeira vez pelo\nmédico de família após isolamento social necessário à\nfamília durante a pandemia pelo COVID19. Segundo a mãe, o aleitamento materno ocorreu até 45\ndias de vida, tendo sido substituído por fórmula infantil de partida, por queixa de \"leite fraco\".\n\nQuando questionada sobre a possibilidade de retornar o aleitamento materno, a mãe informa que\nnão está mais produzindo leite. A família é\ncomposta pela mãe, o lactente de 4 meses e outro filho\nde 2 anos. A renda familiar atual é de 600 reais. Em relação às recomendações alimentares para o\nbebê, considerando recomendações científicas e o contexto social, econômico e cultural, assinale a\nmelhor conduta.","options":{"A":"Manter a fórmula de partida utilizando maior diluição.","B":"Substituir a fórmula de partida por leite de vaca in natura.","C":"Manter a fórmula de partida e introduzir papa salgada e papa de frutas.","D":"Substituir a fórmula de partida para a fórmula de seguimento, visto esta ter menor custo."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-234045","number":"234045","sourceNumber":"234045","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente, 2 meses, é levado ao posto de saúde para consulta de puericultura. Bebê\nnasceu de parto normal, a termo, sem\nintercorrências, peso de nascimento: 3,1 kg. Está em\naleitamento materno exclusivo. Apresenta crescimento e desenvolvimento normais para a idade. Ao\nexame físico: bom estado geral, pálido (+/4+), hidratado, anictérico, ativo, afebril. Ausculta\ncardiopulmonar sem alterações. Abdome flácido, sem visceromegalias. Mãe queixa-se que a\ncriança é pálida. Trouxe um hemograma do lactente que fez por conta própria devido à suspeita de\nanemia: Hb = 9,6 g/dl; Ht = 30%; VCM = 84 fL; CHCM = 32 g/dl; leucograma: 6.300; plaquetas:\n\n350.000. Com base nesse quadro clínico e nos resultados do hemograma apresentados, a melhor\nconduta a ser tomada é:","options":{"A":"Seguir acompanhamento de puericultura.","B":"Solicitar exames para investigação de hemólise.","C":"Solicitar sangue oculto nas fezes e dosagem de ferritina.","D":"Iniciar suplementação de ferro oral em dose terapêutica."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-234059","number":"234059","sourceNumber":"234059","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Paciente, 6 anos, sexo feminino, é atendida no ambulatório de Endocrinologia com\nqueixa de dor e aumento das mamas\nbilateralmente. Ao exame: bom estado geral, eupneica,\nnormocorada. Peso: 21 kg (Z = +0,24). Estatura = 1,20 m (Z = +1). Estágio puberal de Tanner:\nM3P2. Presença de odor axilar, sem pelos axilares ou acne. Foram solicitados exames com os\nrespectivos resultados: idade óssea = 8 anos; LH com valores puberais; ultrassonografia pélvica\ncom volume de útero e ovários acima do esperado para a idade. Diante do caso apresentado, qual\na conduta mais indicada?","options":{"A":"Prescrever análogo de GnRH.","B":"Prescrever inibidor da aromatase.","C":"Solicitar dosagem de andrógenos e exame de imagem da suprarrenal.","D":"Manter acompanhamento de crescimento e desenvolvimento puberal."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-234079","number":"234079","sourceNumber":"234079","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente de 8 meses é trazido para acompanhamento de rotina em UBS. Está em uso\nde mingau com fórmula infantil e amido de\nmilho duas vezes ao dia, associado ao aleitamento ao\nseio em livre demanda. Está sem queixas e a criança encontra-se entre o percentil 50 e o percentil\n25 do peso e da altura para a idade, marcos do desenvolvimento normais para a idade. Além de\nretirar a fórmula infantil e a mucilagem, qual orientação dietética deve ser fornecida?","options":{"A":"Substituição do aleitamento materno, gradualmente, por alimentos pastosos, cinco vezes ao dia.","B":"Retirar, gradualmente, o aleitamento materno e acrescentar alimentos sólidos, cinco vezes ao\ndia.","C":"Manutenção do aleitamento materno e introdução de sucos de frutas e sopas ralas, três vezes\nao dia.","D":"Manutenção do aleitamento materno e acréscimo de alimentos sólidos, gradualmente, três vezes\nao dia."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-199694","number":"199694","sourceNumber":"199694","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Dona Marta traz o seu filho de 45 dias de vida à unidade básica de saúde por notar\nmuito choro nos últimos dois dias. Questiona se\nestá produzindo pouco leite e solicita a prescrição\nde fórmula láctea. Na anamnese e exame físico, o profissional não identifica obstáculos à\namamentação, considera boa a técnica de aleitamento e constata bom ganho de peso. Qual a\nconduta adequada para esta situação?","options":{"A":"Prescrição de fórmula láctea adaptada ao 1° semestre.","B":"Prescrição de domperidona para a mãe para aumentar a produção de leite.","C":"Estímulo ao aleitamento materno exclusivo em horários de 3 em 3 horas, inclusive à noite.","D":"Estímulo ao aleitamento materno exclusivo e explicação sobre os períodos de aceleração do\ncrescimento de lactente."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-199648","number":"199648","sourceNumber":"199648","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Na Puericultura, o médico solicita aos pais de uma criança de 9 meses de idade que\nlistem as aquisições no desenvolvimento ocorridas desde a última consulta. Quais aquisições são\npróprias para essa criança?","options":{"A":"Primeiras palavras; primeiros passos; é ativa e curiosa; rabisca; retira uma vestimenta.","B":"Bate palmas, acena; combina sílabas; fica em pé; pinça completa (polpa a polpa); segura o copo\nou a mamadeira.","C":"Observa sua própria mão; segue com o olhar até 180°; grita; senta com apoio, sustenta a\ncabeça; agarra um brinquedo colocado em sua mão.","D":"Transmite objetos de uma mão para a outra; pinça polegar-dedo; balbucia; senta sem apoio;\nestranhamento (prefere pessoas de seu convívio); brinca de esconde-achou."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-199665","number":"199665","sourceNumber":"199665","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente de 10 meses de idade é levado para consulta de rotina. Na avaliação oral é\nobservada mancha branca opaca nos dentes, bem junto à gengiva, compatível com o estágio inicial\nde cárie da primeira infância. Restante do exame físico sem outras alterações. Quais os cuidados\nsão recomendados na prevenção do aparecimento dessas lesões?","options":{"A":"Suplementação oral de flúor pela mãe durante a gestação.","B":"Uso de dentifrício fluoretado a partir da irrupção do primeiro dente.","C":"Ingestão diária de suplementos de flúor durante o estágio de formação dos dentes.","D":"Escovação dentária sem flúor até completar 12 meses, pelo risco de fluorose dentária."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-172983","number":"172983","sourceNumber":"172983","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Aos 3 meses de vida, uma criança em aleitamento materno exclusivo comparece ao\nposto de saúde para consulta de rotina. Tem\nhistória confirmada por exame laboratorial que a mãe\nteve infecção por Zika no último mês de gestação e ela está apreensiva com o crescimento da\ncabeça da criança. Ao nascer, a menina pesou 2.780 g e perímetro cefálico de 33 cm. Os dados\natuais são: peso de 4.800 g e perímetro cefálico de 40 cm. Qual a melhor conduta quanto ao\ncrescimento da menina?","options":{"A":"Referenciar imediatamente por atraso no crescimento do perímetro cefálico.","B":"Reavaliar em 15 dias, pois ambos peso e perímetro cefálico estão baixos.","C":"Reagendar em 1 semana por apresentar baixo ganho ponderal.","D":"Considerar crescimento somático normal e tranquilizar a mãe."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-173028","number":"173028","sourceNumber":"173028","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O médico de família atende uma paciente de 23 anos que comparece a unidade de\nsaúde no quinto dia após parto vaginal para\nrevisão puerperal. O recém-nascido encontra-se em\naleitamento materno exclusivo. A paciente queixa-se de dificuldade para a amamentação, pois o\nbebê dorme a maior parte do tempo. Refere mamas dolorosas. Ao exame, o médico observou\nmamas edemaciadas, com pele brilhante e avermelhada bilateralmente. Não apresentou febre e\nmal-estar. Qual a conduta correta nesse caso?","options":{"A":"Prescrever antibiótico sistêmico.","B":"Fazer compressas mornas e evitar sutiã.","C":"Amamentar frequentemente e analgesia.","D":"Suspender a amamentação por 24 horas."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-150860","number":"150860","sourceNumber":"150860","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Ao orientar uma primípara, no alojamento conjunto, cujo recém-nascido é de termo,\npeso de 3 kg e com boas condições de\nnascimento, observa-se que a pega está adequada. Desse\nmodo, o que pode ser afirmado?","options":{"A":"O queixo e o nariz tocam a mama.","B":"O lábio inferior está virado para fora.","C":"Abocanha bem o mamilo, com aréola livre.","D":"Aréola mais visível abaixo da boca do bebê que acima."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-150873","number":"150873","sourceNumber":"150873","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Ao retornar ao posto de saúde, um recém-nascido de termo, com 15 dias de vida, que\nnasceu em boas condições, pré-natal sem\nintercorrências, pesando 2400 g, encontra-se com 2300\ng, em aleitamento materno exclusivo. A mãe informa que o bebê está irritado, procura muitas vezes\no peito, porém tem pegas rápidas de cerca de poucos minutos em cada mama. Ao exame,\nencontra-se alerta, hidratado, corado, anictérico, ativo, com choro forte e sem outros achados. Qual\na melhor conduta para este recém-nascido, com relação ao estado nutricional?","options":{"A":"Como está dentro do esperado, manter o aleitamento materno conforme vem sendo feito.","B":"Orientar que o bebê esvazie bem uma mama, evitando a troca para outra antes de 20-30\nminutos.","C":"Após a mamada, associar suplemento com fórmula infantil oferecida com colher ou no copinho.","D":"Ordenhar o leite materno e oferecer por via oral para evitar a mamada direto no peito, em virtude\ndo esforço."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-150889","number":"150889","sourceNumber":"150889","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Criança de 15 meses, nascida a termo e saudável, está em consulta com enfermeira na\nUnidade Básica de Saúde. A profissional solicita ao médico da equipe que a ajude em relação às\naquisições do desenvolvimento da criança. Que aquisições do desenvolvimento são esperadas,\ncomo média, para essa idade?","options":{"A":"Rolar e engatinhar.","B":"Correr e subir escadas.","C":"Retirar uma peça de roupa e construir frases.","D":"Falar as primeiras palavras e andar sem apoio."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-150793","number":"150793","sourceNumber":"150793","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Criança de 3 anos está em consulta na Unidade Básica de Saúde (UBS) por apresentar\ntosse. Ao ser examinada, constata-se\npéssimo estado de saúde oral, situação frequente nos\natendimentos de crianças da área. Os profissionais de saúde da UBS enfatizam para sua mãe a\nnecessidade de tratamento dentário e medidas de prevenção. Qual a medida de prevenção em\nsaúde bucal mais eficaz como estratégia de caráter coletivo?","options":{"A":"Fluoretação das águas de abastecimento.","B":"Utilização de pastas com flúor e fio dental.","C":"Realização de oficinas de promoção de saúde bucal nas UBS.","D":"Técnicas de escovação específicas para cada tipo de arcada e disposição dentária."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-126979","number":"126979","sourceNumber":"126979","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"No centro de saúde, a mãe de uma criança de 7 meses de idade solicita orientação\npara alimentação complementar de sua filha. Quais as\norientações mais adequadas?","options":{"A":"Dar os alimentos semissólidos e sólidos. Colocar as porções de cada alimento no prato,\nmisturando-os. Oferecer à criança diferentes alimentos ao dia.","B":"Os alimentos devem ser bem cozidos, passados pela peneira e batidos no liquidificador. Desde\ncedo a criança deve acostumar-se a comer\nalimentos variados.","C":"Sopas e comidas ralas/moles fornecem energia suficiente para a criança; pode-se oferecê-las de\n\nmamadeira; deve-se ter cuidado com contaminação e transmissão de doenças.","D":"Deve-se dar comida espessa desde o início e oferecida de colher; começar com consistência\npastosa (papas/purês) e, gradativamente, aumentar a\nconsistência até chegar à alimentação da\nfamília."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-126989","number":"126989","sourceNumber":"126989","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Conversando acerca do desenvolvimento do filho de 5 meses, a mãe questiona ao\nmédico se o filho está se desenvolvendo normalmente. Das aquisições abaixo, em quais o médico\npoderá se basear para emitir um parecer de que essa criança está se desenvolvendo bem?","options":{"A":"O bebê sabe quando se dirigem a ele.","B":"A criança aponta para as coisas que ele quer.","C":"O bebê fala, pelo menos, uma palavra com sentido.","D":"A criança dá adeus, bate palmas; gosta de imitar os pais."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-126982","number":"126982","sourceNumber":"126982","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Joana leva sua filha de 4 meses à consulta de puericultura na unidade de saúde. A\ncriança apresenta crescimento e desenvolvimento\nneuropsicomotor adequados para a idade. Está\nem aleitamento materno exclusivo. Joana está preocupada, pois trabalha em um empresa privada e\ndeverá voltar ao trabalho na próxima semana. Não sabe como deve proceder em relação à\nalimentação da filha. Qual a orientação mais adequada para oferecer à mãe?","options":{"A":"Orientar para iniciar o desmame parcial, utilizando a reconstituição do leite em pó a 15%, ou\nseja, 1 colher de sopa cheia (15 g) em cada 100 ml de água.","B":"Manter o aleitamento materno antes e após o trabalho, e introduzir fórmula infantil adequada\npara a idade nos horários que a mãe\nestiver ausente.","C":"Iniciar, de modo complementar, a introdução de novos alimentos, começando por papas de\nfrutas\n\ne papas salgadas.","D":"Realizar ordenha do leite materno que pode ser conservado no congelador por 15 dias, e\noferecer\n\napós esquentar em banho-maria."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-102100","number":"102100","sourceNumber":"102100","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Ao concluir o exame de uma criança de quatro meses de idade, o médico comunica à\nmãe da criança que esta apresenta atraso em\nseu desenvolvimento motor. Qual dos sinais abaixo\nrepresenta essa condição de hipotonia?","options":{"A":"Em suspensão ventral, a criança mantém a cabeça abaixo do tronco.","B":"Em decúbito dorsal, segurada pelos braços, a criança ergue a cabeça.","C":"Em decúbito ventral, a criança levanta a cabeça e parte do tronco.","D":"Em pé, a criança mantém os pés cruzados em extensão."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-102107","number":"102107","sourceNumber":"102107","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente de 10 meses vem à consulta de puericultura e sua mãe solicita orientação\nquanto à alimentação, já que o bebê recebe\napenas mingau de leite integral de vaca com maisena\ne açúcar em mamadeira, desde o 3° mês. Em alguns intervalos consome ?danoninho? e biscoitos.\nNão recebe complexos vitamínicos, nem ferro. Está com crescimento e desenvolvimento\nadequados para a idade. Quais as consequências da dieta desse bebê?","options":{"A":"Hipervitaminose A e D.","B":"Anemia ferropriva e sobrecarga renal.","C":"Doença celíaca e dermatite herpetiforme.","D":"Deficiência de vitaminas do complexo B e cálcio."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-102175","number":"102175","sourceNumber":"102175","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menina vem à Unidade Básica de Saúde, para acompanhamento do crescimento,\nportando radiografia do punho esquerdo mostrando\natraso de 2 anos da idade óssea em relação à\nidade cronológica. Hemograma e sumário de urina normais. Exibe as seguintes medições: Aos sete\nanos: 110 cm, aos 8 anos ? 117 cm, aos 9 anos ? 122 cm e aos 10 anos ? 128 cm. Não apresenta\ntelarca ou pubarca e tem peso adequado para a idade. (VER IMAGEM). Após plotar as medidas no\ngráfico de crescimento, qual a conduta adequada para esse caso?","options":{"A":"Solicitar curva de hormônio de crescimento.","B":"Iniciar tratamento com solução de zinco e arginina.","C":"Solicitar dosagens hormonais ? FSH, LH, TSH.","D":"Monitorar crescimento, reforçar condições adequadas de nutrição, sono e atividade física."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-81323","number":"81323","sourceNumber":"81323","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma criança de 2 anos é levada ao posto de saúde por sua mãe, que estava\npreocupada, pois seu filho não falava. Relata\nque os seus filhos mais velhos falaram com 1 ano.\nDurante a consulta, o médico percebeu que a criança vestiu a camiseta após o exame, pulou com\nos dois pés, conseguiu empilhar seis cubos sem que eles caíssem e falou: ?Mamãe... embora\nagora?. Nega intercorrências na gestação, sem intercorrências prévias. Situação vacinal em dia.\nDiante dessa situação, qual a conduta mais adequada para esse paciente e sua família?","options":{"A":"Referir para avaliação neuropsicomotora.","B":"Informar a mãe sobre os sinais de alerta e agendar consulta para 60 dias.","C":"Orientar a mãe sobre a estimulação da criança e encaminhar para avaliação com o\nneuropediatra.","D":"Orientar a mãe para que continue estimulando a criança, e agendar retorno conforme rotina do\nserviço."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-65746","number":"65746","sourceNumber":"65746","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma criança de dois anos de idade, com dieta predominantemente láctea, é atendida\nno centro de saúde. O médico decide utilizar\ncompostos à base de ferro. Que orientações o médico\ndeve fornecer à família?","options":{"A":"Os estoques são recompostos nos primeiros 15 dias do tratamento.","B":"O ferro é mais bem absorvido quando administrado após a refeição de sal.","C":"Podem-se oferecer chás, leite, cereais e fibras, pois não interferem na absorção de ferro.","D":"Devem-se oferecer frutas cítricas e carboidratos, pois facilitam a absorção do ferro não heme.","E":"Em casos de crianças que aceitam mal a medicação, a alternativa é a transfusão de glóbulos\nvermelhos."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-65725","number":"65725","sourceNumber":"65725","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Após entrevista clínica com adolescente de 15 anos de idade, o médico identifica\natitudes e comportamentos preocupantes que\nprecisam ser adequadamente manejados. Assinale a\nalternativa que contém um desses comportamentos.","options":{"A":"O adolescente declara estar apaixonado definitivamente.","B":"O adolescente revela consumo de bebidas alcoólicas por duas vezes.","C":"O adolescente faz afirmativas que denotam certo radicalismo religioso.","D":"O adolescente responde laconicamente, ao ser indagado sobre suas transformações físicas.","E":"O adolescente declara-se desesperado em função de uma grave discussão com a namorada."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-65740","number":"65740","sourceNumber":"65740","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A avaliação de uma família é de que o filho de cinco meses de idade não está se\ndesenvolvendo bem. Qual a alternativa que contém sinais de alarme para o desenvolvimento da\ncriança?","options":{"A":"Senta sem apoio.","B":"Apresenta sorriso alto.","C":"Rola na cama com facilidade.","D":"Não vira a cabeça para localizar sons.","E":"Acompanha com o olhar objetos a curta distância."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-65719","number":"65719","sourceNumber":"65719","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma criança de seis meses e 15 dias de idade, saudável desde as condições de\nnascimento até o presente, chega ao\nambulatório com a seguinte alimentação: fórmula modificada\n(horários: 8, 12, 15, 18, 21 horas); frutas (10 horas). Qual a recomendação mais adequada, quanto\na sua nutrição?","options":{"A":"Manter a mesma alimentação até o 7º mês de vida.","B":"Acrescentar uma papa de frutas no horário da tarde.","C":"Introduzir clara de ovo cozida, peixe, fígado, doces caseiros.","D":"Introduzir papa salgada com adição de gorduras de origem animal.","E":"Introduzir refeição com carne ou ovo, legumes, verduras, cereais e leguminosas com óleo/azeite\nno horário do almoço."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-65698","number":"65698","sourceNumber":"65698","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Médico de família e comunidade e agente comunitário de saúde visitam em domicílio\npuérpera de 20 anos de idade e seu Recém-Nascido (RN) com 5 dias de vida. O RN nasceu de\nparto vaginal, com 38 semanas, pesando 2.800 gramas. O pré-natal foi realizado na Unidade de\nSaúde da Família e sem intercorrências. Durante o parto, foi necessário o uso de cefalosporina de\n1ª geração. Em relação à amamentação do RN acima, qual recomendação deve ser dada?","options":{"A":"O uso de antibiótico durante o parto contraindica a amamentação.","B":"A mamada deve durar em média de 30 a 45 minutos em cada seio.","C":"Nos casos de ingurgitamento mamário, as mamas podem ser esvaziadas e o leite, descartado.","D":"Em caso de mastite puerperal instalada, a amamentação deve ser suspensa pelo risco de\ncontaminar a criança.","E":"A preensão incorreta do mamilo pela criança leva a fissuras na mama, principal responsável pela\nsuspensão da amamentação."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-141618","number":"141618","sourceNumber":"141618","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Para realizar a orientação alimentar de uma criança, assinale a assertiva que contem\nduas orientações corretas para prevenção de\nobesidade infantil.","options":{"A":"Respeitar o horário das alimentações e incremento das atividades físicas.","B":"Incremento da atividade física e aumento da ingesta de líquidos para deglutir alimentos mal\nmastigados.","C":"Mastigar muito bem os alimentos e utilização líquidos para deglutir alimentos mal mastigados.","D":"Liberdade de horários de alimentação e comer durante atividades que desviem a atenção do\nalimento."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-141606","number":"141606","sourceNumber":"141606","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Durante o atendimento de uma criança de quatro meses, a mãe relata que tem dúvidas\nsobre o desenvolvimento do seu filho.\nPara afirmar que desenvolvimento apresenta sinais de alerta,\nao examinar esse lactente, você encontrou ao exame físico:","options":{"A":"Olhar vago e pouco interessado e mãos persistentemente fechadas.","B":"Controle esfincteriano deficiente.","C":"Não senta sem apoio.","D":"Não fala sílabas."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-45393","number":"45393","sourceNumber":"45393","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Identifique, dentre as abaixo, a opção correta referente ao crescimento de uma criança\nnormal:","options":{"A":"O recém-nascido a termo e saudável perde\n\naproximadamente 18% do peso corporal nos primeiros dias de vida.","B":"Dos 2 aos 8 anos de idade, o ganho corporal médio é de, aproximadamente, 1 kg por ano.","C":"O perímetro cefálico aumenta 10 cm no primeiro\n\nsemestre de vida e é um dos índices de menor variação para os diferentes grupos etários.","D":"No primeiro ano de vida, a criança cresce em média 25 cm/ano e o pré-escolar cresce, em\nmédia, 4,5 cm por ano.","E":"Ao nascimento, a relação segmento superior / segmento inferior (SS/SI) é em torno de 1,0,\naumentando para 1,5 até a idade de 8 anos."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-45389","number":"45389","sourceNumber":"45389","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente com 40 dias de vida, amamentado exclusivamente ao seio. Nasceu de parto\nnormal a termo, peso 3.350 g e teve icterícia fisiológica. Atualmente, pesa 5.300 g e apresenta\naproximadamente seis evacuações semilíquidas e amareladas ao dia. Qual a conduta mais\nadequada diante do quadro?","options":{"A":"Manter aleitamento materno exclusivo.","B":"Substituir a dieta por leite de soja ou leite de cabra.","C":"Associar chás e soro da OMS à vontade.","D":"Suspender leite materno e iniciar a dieta isenta de lactose.","E":"Fazer pausa alimentar por 24 horas."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-45379","number":"45379","sourceNumber":"45379","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação às anemias na infância, é correto afirmar:","options":{"A":"O diagnóstico laboratorial da anemia ferropriva inclui ferro sérico e ferritina sérica baixos,\ncapacidade total de ligação do ferro baixa e saturação de transferrina alta.","B":"A deficiência de B12 e as talassemias são exemplos clássicos de anemias macrocíticas.","C":"Nas crianças com anemias hemolíticas esferocíticas estão contraindicados o uso de sulfas e\nquinolonas.","D":"Baixo peso ao nascimento, desmame precoce e baixa disponibilidade de ferro na dieta\npredispõem as anemias ferroprivas.","E":"Lactentes com deficiência de ferro quando apresentam alterações de desenvolvimento e\ncomportamento, geralmente são reversíveis após o tratamento."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-365639","number":"365639","sourceNumber":"365639","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma criança de 1 ano de idade foi levada para consulta de rotina. Na história clínica, a\nmãe referiu desmame completo aos 3 meses de vida, passando a ofertar leite de vaca integral.\n\nNegou uso de ferro oral até o momento. Foram solicitados exames complementares para avaliar\npossível deficiência de ferro. Acerca do referido caso clínico, poucos dias depois, os pais\nretornaram com os resultados dos exames, os quais revelaram todos os parâmetros dentro da\nnormalidade, não havendo sinais de deficiência de ferro ou anemia. Assinale a alternativa que\ncorresponde à conduta a ser adotada nesse caso.","options":{"A":"Orientar os pais acerca de alimentação saudável, não prescrever ferro nesse momento e repetir\nos exames em um ano.","B":"Orientar os pais com relação a alimentação saudável, não prescrever ferro nesse momento e\ntrocar o leite de vaca integral por fórmula infantil.","C":"Orientar os familiares a respeito de alimentação saudável e iniciar ferro profilático.","D":"Orientar os pais quanto a alimentação saudável, prescrever dose terapêutica de ferro (3-6\nmg/kg/dia) em razão de fatores de risco e manter seguimento de rotina."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-349726","number":"349726","sourceNumber":"349726","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um recém-nascido de 27 dias de vida, que recebe aleitamento exclusivo ao seio\nmaterno, é levado para consulta de\npuericultura. O peso e comprimento estão adequados para\nesse tempo de vida, comparado ao nascimento. Há relato de seis evacuações por dia, das quais\nduas ou três são semilíquidas e amareladas. Ao exame, o paciente está hidratado com bom estado\ngeral. Qual é a conduta mais adequada diante do quadro?","options":{"A":"Manter o aleitamento materno exclusivo.","B":"Substituir o leite materno por dieta isenta de lactose.","C":"Iniciar leite de soja.","D":"Sugerir pausa alimentar por 24 horas.","E":"Recomendar leite de vaca a 50% com água."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-365577","number":"365577","sourceNumber":"365577","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"No dia primeiro de agosto, é comemorado o Dia Mundial da Amamentação. Sabe-se\nque essa prática oferece inúmeros benefícios\npara o crescimento e o desenvolvimento da criança,\nalém de fortalecer o vínculo mãe-bebê. Entretanto, existem algumas contraindicações a essa\nprática. Assinale a alternativa que corresponde a uma condição materna considerada\ncontraindicação absoluta à amamentação.","options":{"A":"Hanseníase não tratada","B":"Uso de antidepressivos","C":"Tuberculose pulmonar ativa sem tratamento","D":"Infecção pelo HTLV"},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-337545","number":"337545","sourceNumber":"337545","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um menino, com 8 anos de idade, vem ao ambulatório levado pela mãe com queixa de\nbaixa estatura. Ele diz que é o mais baixo dos seus amigos, e a mãe acha que ele está crescendo\npouco. A estatura do paciente é de 120cm, estando no escore Z -1 na curva da estatura. Em\nrelação ao caso clínico descrito e aos conhecimentos médicos relacionados, julgue o item a seguir.\nExistem alterações sindrômicas que possuem associação com baixa estatura, como as síndromes\nde Marfan e Soto.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-337546","number":"337546","sourceNumber":"337546","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um menino, com 8 anos de idade, vem ao ambulatório levado pela mãe com queixa de\nbaixa estatura. Ele diz que é o mais baixo dos seus amigos, e a mãe acha que ele está crescendo\npouco. A estatura do paciente é de 120cm, estando no escore Z -1 na curva da estatura. Em\nrelação ao caso clínico descrito e aos conhecimentos médicos relacionados, julgue o item a seguir.\nA aferição da altura, em criança maior de 2 anos, deve ser realizada com a criança em pé, em\nbalança plataforma com antropômetro, ou em antropômetro de parede.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-337595","number":"337595","sourceNumber":"337595","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Miguel é uma criança de 3 meses, que foi levada por sua mãe, Rafaela, para consulta\nde puericultura. Miguel nasceu com peso de\n3450g, perímetro cefálico de 34cm e 48cm de\ncomprimento; seu exame físico, hoje, apresenta as seguintes medidas: peso de 6830g, perímetro\ncefálico de 41cm e comprimento de 61cm. Quando questionada, Rafaela traz algumas\npreocupações: refere que está preocupada com o peso de Miguel, pois acha que produz pouco\nleite; está preocupada também com o desenvolvimento do bebê e se ele já não deveria estar\nsentando. Ao conferir o cartão de vacinas de Miguel, o médico da UBS verifica as seguintes vacinas\nno cartão: BCG, DTP, Hib, VIP e pneumo conjugada. Considerando o caso descrito e seus\nconhecimentos, julgue o item a seguir. A escolaridade dos pais é fator de risco para\ndesenvolvimento e crescimento infantil inadequado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-337596","number":"337596","sourceNumber":"337596","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Miguel é uma criança de 3 meses, que foi levada por sua mãe, Rafaela, para consulta\nde puericultura. Miguel nasceu com peso de\n3450g, perímetro cefálico de 34cm e 48cm de\ncomprimento; seu exame físico, hoje, apresenta as seguintes medidas: peso de 6830g, perímetro\ncefálico de 41cm e comprimento de 61cm. Quando questionada, Rafaela traz algumas\npreocupações: refere que está preocupada com o peso de Miguel, pois acha que produz pouco\nleite; está preocupada também com o desenvolvimento do bebê e se ele já não deveria estar\nsentando. Ao conferir o cartão de vacinas de Miguel, o médico da UBS verifica as seguintes vacinas\nno cartão: BCG, DTP, Hib, VIP e pneumo conjugada. Considerando o caso descrito e seus\nconhecimentos, julgue o item a seguir. Pelo relato de Rafaela, Miguel apresenta atraso no\ndesenvolvimento, pois, nessa idade, já é esperado que a criança sente sem apoio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-337598","number":"337598","sourceNumber":"337598","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Miguel é uma criança de 3 meses, que foi levada por sua mãe, Rafaela, para consulta\nde puericultura. Miguel nasceu com peso de\n3450g, perímetro cefálico de 34cm e 48cm de\ncomprimento; seu exame físico, hoje, apresenta as seguintes medidas: peso de 6830g, perímetro\ncefálico de 41cm e comprimento de 61cm. Quando questionada, Rafaela traz algumas\npreocupações: refere que está preocupada com o peso de Miguel, pois acha que produz pouco\nleite; está preocupada também com o desenvolvimento do bebê e se ele já não deveria estar\nsentando. Ao conferir o cartão de vacinas de Miguel, o médico da UBS verifica as seguintes vacinas\nno cartão: BCG, DTP, Hib, VIP e pneumo conjugada. Considerando o caso descrito e seus\nconhecimentos, julgue o item a seguir. A velocidade de crescimento esperada para uma criança\ngira em torno de 15 cm no 1º semestre de vida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-337600","number":"337600","sourceNumber":"337600","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Miguel é uma criança de 3 meses, que foi levada por sua mãe, Rafaela, para consulta\nde puericultura. Miguel nasceu com peso de\n3450g, perímetro cefálico de 34cm e 48cm de\ncomprimento; seu exame físico, hoje, apresenta as seguintes medidas: peso de 6830g, perímetro\ncefálico de 41cm e comprimento de 61cm. Quando questionada, Rafaela traz algumas\npreocupações: refere que está preocupada com o peso de Miguel, pois acha que produz pouco\nleite; está preocupada também com o desenvolvimento do bebê e se ele já não deveria estar\nsentando. Ao conferir o cartão de vacinas de Miguel, o médico da UBS verifica as seguintes vacinas\nno cartão: BCG, DTP, Hib, VIP e pneumo conjugada. Considerando o caso descrito e seus\nconhecimentos, julgue o item a seguir. Considerando a velocidade padrão de ganho ponderal nos 3\nprimeiros meses, Miguel está com o ganho de peso inadequado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-305307","number":"305307","sourceNumber":"305307","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma adolescente de 16 anos pede para que sua mãe dê licença, durante a consulta,\npara que ela tire algumas dúvidas com seu\npediatra. Após a mãe se retirar, a paciente conta que\niniciou a vida sexual com seu namorado e que gostaria de usar anticoncepcional oral (ACO), mas\nsem que sua mãe saiba. Nesse caso, qual das seguintes opções é a conduta mais adequada do\nmédico quanto à prescrição de anticoncepcional oral?","options":{"A":"O sigilo médico, nessa situação, pode ser quebrado, uma vez que a paciente está sob risco de\nengravidar ou de contrair infecção sexualmente transmissível.","B":"O pediatra pode prescrever o ACO, mas somente com o consentimento da mãe.","C":"O pediatra pode prescrever o ACO, mas, após a consulta, deve comunicar sua conduta à mãe,\nem segredo.","D":"O pediatra pode prescrever o ACO, respeitando a vontade da paciente em manter o assunto em\nsigilo.","E":"O pediatra deve conversar sobre opções contraceptivas, mas não deve prescrever ACO, por se\ntratar de adolescente."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-298896","number":"298896","sourceNumber":"298896","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um paciente de 2 anos e 3 meses de idade foi levado ao ambulatório de pediatria pela\nmãe, pois ela está preocupada com um \"caroço\" no pescoço do filho, que ela notou há cinco\nmeses. Relatou que o filho é bastante ativo, que se alimenta bem, sempre ganhou peso, mas fala\npouco e palavras difíceis de compreender. Ademais, há muito tempo apareceram alguns\nmachucados no couro cabeludo dele, que o menino coça bastante e tem algumas crostas. Ao\nexame físico, constataram-se altura = 90 cm (escore z 0), peso = 12,300 kg (escore z entre 0 e -2),\nFC = 120 bpm, FR = 26 irpm e SatO2 = 97% em AA. No couro cabeludo, há várias lesões com\ncrostas melicéricas e presença de linfonodo retroauricular medindo 1,5 cm, móvel, fibroelástico,\nindolor à palpação. Observaram-se oroscopia, dentes em bom estado, sem lesões, sem frênulo\nlingual, otoscopia, com membrana timpânica translúcida, sem abaulamentos ou retrações e\nausculta cardíaca, BNF, RR, 2t, sem sopro. Verificaram-se, ainda, ausculta pulmonar, MVUD, sem\nRA, abdome, RHA+, depressível, sem megalias, indolor à palpação e genitália com testículos em\nbolsa escrotal e fimose. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. É bastante comum meninos não falarem até os 2 anos de idade; nesses\ncasos, deve-se aguardar até os 2 anos e meio e orientar que os pais estimulem a criança a falar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-298931","number":"298931","sourceNumber":"298931","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um bebê de 6 meses de vida foi levado pela mãe à equipe de Saúde da Família (eSF)\npara consulta de rotina de puericultura. A mãe\nrelata que está preocupada, pois a criança\n\nmostra-se mais chorosa, apresentando irritabilidade, dificuldade para dormir e pico febril de 39ºC\nna\nnoite anterior. A criança está previamente hígida, em aleitamento materno exclusivo, fez uso de\nparacetamol há duas horas e sua temperatura é de 37,5ºC no momento. A mãe nega que a criança\ntenha alergias medicamentosas. Ao exame físico, verificam-se auscultas pulmonar e cardíaca sem\nalterações, abdome sem particularidades, otoscopia direita com presença de membrana timpânica\nabaulada e hiperemiada, sem presença de otorreia. A criança é capaz de firmar a cabeça e\napanhar objetos, e as medidas antropométricas estão próximas ao percentil 50. Carteira de\nvacinação atualizada. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. Apesar de medidas antropométricas estarem adequadas nesse momento, o\ndesenvolvimento neuropsicomotor está atrasado, pois a criança com essa idade já deveria ser\ncapaz de sentar sem apoio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-298932","number":"298932","sourceNumber":"298932","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um bebê de 6 meses de vida foi levado pela mãe à equipe de Saúde da Família (eSF)\npara consulta de rotina de puericultura. A mãe\nrelata que está preocupada, pois a criança\n\nmostra-se mais chorosa, apresentando irritabilidade, dificuldade para dormir e pico febril de 39ºC\nna\nnoite anterior. A criança está previamente hígida, em aleitamento materno exclusivo, fez uso de\nparacetamol há duas horas e sua temperatura é de 37,5ºC no momento. A mãe nega que a criança\ntenha alergias medicamentosas. Ao exame físico, verificam-se auscultas pulmonar e cardíaca sem\nalterações, abdome sem particularidades, otoscopia direita com presença de membrana timpânica\nabaulada e hiperemiada, sem presença de otorreia. A criança é capaz de firmar a cabeça e\napanhar objetos, e as medidas antropométricas estão próximas ao percentil 50. Carteira de\nvacinação atualizada. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. Nessa consulta, já é possível orientar acerca da introdução de alimentação\ncomplementar ao aleitamento materno.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-284298","number":"284298","sourceNumber":"284298","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um lactente com dez meses de vida, nascido de parto normal a termo, com peso\nadequado e sem intercorrência, foi levado\npor sua mãe à unidade de atenção básica para uma\nconsulta de puericultura, apresentando unhas quebradiças, irritabilidade, queilite angular e\nastenia.\nAo exame físico, o pediatra observou palidez da face, das palmas das mãos e da mucosa oral e\nconjuntival e solicitou um hemograma, que demonstrou hemoglobina igual a 10,5 g/dl e hematócrito\n31%, o que o fez suspeitar de anemia ferropriva. A mãe informou que ele é amamentado ao seio\nmaterno, mas recebe complementação com leite de vaca em pó desde o 6.º mês, aceita pouca\nalimentação de sal e nunca fez suplementação com ferro oral. Com base nessa situação hipotética,\njulgue o item a seguir. A prevenção de anemia para lactente a termo com peso adequado é feita\ncom a prescrição de 1 mg/kg de ferro elementar, do 3.º ao 24.º mês de vida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-284299","number":"284299","sourceNumber":"284299","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um lactente com dez meses de vida, nascido de parto normal a termo, com peso\nadequado e sem intercorrência, foi levado\npor sua mãe à unidade de atenção básica para uma\nconsulta de puericultura, apresentando unhas quebradiças, irritabilidade, queilite angular e\nastenia.\nAo exame físico, o pediatra observou palidez da face, das palmas das mãos e da mucosa oral e\nconjuntival e solicitou um hemograma, que demonstrou hemoglobina igual a 10,5 g/dl e hematócrito\n31%, o que o fez suspeitar de anemia ferropriva. A mãe informou que ele é amamentado ao seio\nmaterno, mas recebe complementação com leite de vaca em pó desde o 6.º mês, aceita pouca\nalimentação de sal e nunca fez suplementação com ferro oral. Com base nessa situação hipotética,\njulgue o item a seguir. A suplementação da alimentação com leite de vaca a partir do 6.º mês\nprotege contra a deficiência de ferro do lactente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-261252","number":"261252","sourceNumber":"261252","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Certo recém-nascido (RN) a termo, de parto vaginal, com peso ao nascimento de 3.200\ngramas, é encaminhado à consulta de puericultura aos sete dias de vida, em aleitamento materno\nexclusivo. A lactante relata dor extrema ao amamentar. O peso atual do paciente é de 2.600\ngramas. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. A dor mamária e a perda de peso são sinais sugestivos de má pega do RN.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-261253","number":"261253","sourceNumber":"261253","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Certo recém-nascido (RN) a termo, de parto vaginal, com peso ao nascimento de 3.200\ngramas, é encaminhado à consulta de puericultura aos sete dias de vida, em aleitamento materno\nexclusivo. A lactante relata dor extrema ao amamentar. O peso atual do paciente é de 2.600\ngramas. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. Recomenda-se aleitamento materno exclusivo até os 4 meses de idade, para todas as\ncrianças em condições de serem amamentadas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-261254","number":"261254","sourceNumber":"261254","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Certo recém-nascido (RN) a termo, de parto vaginal, com peso ao nascimento de 3.200\ngramas, é encaminhado à consulta de puericultura aos sete dias de vida, em aleitamento materno\nexclusivo. A lactante relata dor extrema ao amamentar. O peso atual do paciente é de 2.600\ngramas. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. A perda de peso do paciente indica que o leite está fraco.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-261255","number":"261255","sourceNumber":"261255","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Certo Recém-Nascido (RN) a termo, de parto vaginal, com peso ao nascimento de\n\n3.200 gramas, é encaminhado à consulta de puericultura aos sete dias de vida, em aleitamento\nmaterno exclusivo. A lactante relata dor extrema\nao amamentar. O peso atual do paciente é de\n2.600 gramas. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item\na seguir. O paciente mencionado deve apresentar sorriso social nessa idade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-274390","number":"274390","sourceNumber":"274390","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Sobre as características farmacológicas das substâncias e seu uso por lactantes,\nassinale a alternativa correta.","options":{"A":"Fármacos com alto peso molecular atingem mais facilmente o leite materno que aqueles com\npeso molecular menor.","B":"Fármacos com alta afinidade a proteínas plasmáticas apresentam maior facilidade para atingir o\ncompartimento lácteo, uma vez que os fármacos passam para o leite materno ligados às proteínas\nplasmáticas.","C":"Fármacos lipossolúveis apresentam mais dificuldade para atingir o compartimento lácteo.","D":"Fármacos de ação longa mantêm níveis circulantes por maior tempo no sangue materno, mas,\npor terem efeito mais duradouro e lento, não\npassam para o leite materno.","E":"Fármacos com baixa biodisponibilidade são ideais para uso durante a lactação porque, mesmo\nquando presentes no leite, são pouco ou nada\nabsorvidos pelo lactente."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-274424","number":"274424","sourceNumber":"274424","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Referente à Saúde da Criança, informe se é verdadeiro (V) ou falso (F) o que se afirma\na seguir e assinale a alternativa com a\nsequência correta. ( ) A mortalidade infantil diminuiu muito\nnas últimas décadas, tendo maior queda a mortalidade pós-neonatal. ( ) A obesidade infantil e a má\nqualidade da alimentação superaram a desnutrição como problema de saúde das crianças. ( ) As\nprimeiras consultas devem ser feitas preferencialmente pelo médico, mas as demais podem ser\nfeitas exclusivamente por enfermeiros para crianças de baixo risco. ( ) Crianças de alto risco não\ndevem ser acompanhadas na atenção primária, ficando seu acompanhamento restrito aos\nambulatórios de especialidades.","options":{"A":"F ? V ? V ? F.","B":"F ? F ? F ? V.","C":"V ? V ? F ? F.","D":"V ? V ? V ? F.","E":"F ? F ? V ? V."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-261303","number":"261303","sourceNumber":"261303","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma criança de 1 ano e 4 meses de idade, com histórico de aleitamento materno\nexclusivo até os 6 meses, é levada a\natendimento pela mãe que referiu tosse, febre, hiperemia\nocular e aparecimento de \"manchas\" brancas em mucosa oral, com posterior aparecimento de\n\"manchas\" vermelhas no corpo. Ao exame, apresenta temperatura axilar de 38 ºC e exantema\nmaculopapular avermelhado, de progressão craniocaudal. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. A respeito do aleitamento materno, a\nrecomendação do Ministério da Saúde é de amamentar, se possível, até os 2 anos de idade ou\nmais, oferecendo aleitamento materno exclusivo até os 6 meses de vida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-250098","number":"250098","sourceNumber":"250098","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Recentemente o Ministério da Saúde publicou o Guia Alimentar para Crianças\nBrasileiras Menores de Dois Anos. Com relação a\nesse tema, julgue o item a seguir. Mulheres com\nhepatites dos vírus A, B e C podem amamentar, exceto as portadoras do vírus C que estiverem\ncom mamilos com fissuras.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-250099","number":"250099","sourceNumber":"250099","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Recentemente o Ministério da Saúde publicou o Guia Alimentar para Crianças\nBrasileiras Menores de Dois Anos. Com relação a\nesse tema, julgue o item a seguir. Com o advento\ndo desmame, os alimentos processados, enriquecidos ou calóricos, como, por exemplo, o melado\nou a rapadura, na população carente, devem ser a base do início da alimentação da criança.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-250100","number":"250100","sourceNumber":"250100","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Recentemente o Ministério da Saúde publicou o Guia Alimentar para Crianças\nBrasileiras Menores de Dois Anos. Com relação a\nesse tema, julgue o item a seguir. Nos dois\nprimeiros anos de vida, as bebidas não devem ser adoçadas com açúcar, devendo ser utilizados\nadoçantes naturais como a stevia ou o mel, com a finalidade de criar hábitos saudáveis e evitar\ncáries dentárias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-250101","number":"250101","sourceNumber":"250101","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Recentemente o Ministério da Saúde publicou o Guia Alimentar para Crianças\nBrasileiras Menores de Dois Anos. Com relação a\nesse tema, julgue o item a seguir. Na\nimpossibilidade de amamentação até os quatro meses de vida, o leite de vaca deve ser diluído ou\ndeve ser utilizada fórmula de leite desnatado ou semidesnatado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-239311","number":"239311","sourceNumber":"239311","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma mãe de primeira viagem, apresenta grandes inseguranças acerca do\ndesenvolvimento da filha, de quais situações\nsão normais ou anormais, além de quando ela deve\nesperar que a criança consiga demonstrar certas capacidades. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, considerando principalmente as informações do Tratado de\nPediatria (Nelson), julgue o item a seguir. Espera-se a expressão do sorriso social da criança a\npartir dos 3 meses de vida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-239312","number":"239312","sourceNumber":"239312","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma mãe de primeira viagem, apresenta grandes inseguranças acerca do\ndesenvolvimento da filha, de quais situações\nsão normais ou anormais, além de quando ela deve\nesperar que a criança consiga demonstrar certas capacidades. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, considerando principalmente as informações do Tratado de\nPediatria (Nelson), julgue o item a seguir. Gargalhadas podem ser observadas a partir dos 4 meses\nde vida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-239313","number":"239313","sourceNumber":"239313","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma mãe de primeira viagem, apresenta grandes inseguranças acerca do\ndesenvolvimento da filha, de quais situações\nsão normais ou anormais, além de quando ela deve\nesperar que a criança consiga demonstrar certas capacidades. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, considerando principalmente as informações do Tratado de\nPediatria (Nelson), julgue o item a seguir. O desenvolvimento da capacidade de engatinhar,\nnecessariamente, precede o da capacidade de andar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-239314","number":"239314","sourceNumber":"239314","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma mãe de primeira viagem, apresenta grandes inseguranças acerca do\ndesenvolvimento da filha, de quais situações\nsão normais ou anormais, além de quando ela deve\nesperar que a criança consiga demonstrar certas capacidades. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, considerando principalmente as informações do Tratado de\nPediatria (Nelson), julgue o item a seguir. O movimento de pinça anatômica com o polegar e\nindicador costuma surgir aos 6 meses de vida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-239315","number":"239315","sourceNumber":"239315","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma mãe de primeira viagem, apresenta grandes inseguranças acerca do\ndesenvolvimento da filha, de quais situações\nsão normais ou anormais, além de quando ela deve\nesperar que a criança consiga demonstrar certas capacidades. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, considerando principalmente as informações do Tratado de\nPediatria (Nelson), julgue o item a seguir. O reflexo cutâneo-plantar em flexão desaparece em torno\nde 6 a 8 meses de vida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-255734","number":"255734","sourceNumber":"255734","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Os pais de uma criança de 4 anos de idade levam seu filho a um pediatra credenciado\npela Sociedade Brasileira de Pediatria para uma\nrotina de puericultura. Durante a consulta, são\nfeitas várias perguntas relacionadas ao desenvolvimento infantil da criança, que são respondidas\npelos pais, e são realizados testes pelo pediatra. Com base no exposto e tendo em vista as\nrecomendações da Sociedade Brasileira de Pediatria, julgue o item a seguir. Nessa fase, a criança\né considerada como pré-escolar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-255736","number":"255736","sourceNumber":"255736","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Os pais de uma criança de 4 anos de idade levam seu filho a um pediatra credenciado\npela Sociedade Brasileira de Pediatria para uma\nrotina de puericultura. Durante a consulta, são\nfeitas várias perguntas relacionadas ao desenvolvimento infantil da criança, que são respondidas\npelos pais, e são realizados testes pelo pediatra. Com base no exposto e tendo em vista as\nrecomendações da Sociedade Brasileira de Pediatria, julgue o item a seguir. Provavelmente a\ncriança começa a controlar a micção noturna nessa idade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-255737","number":"255737","sourceNumber":"255737","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Os pais de uma criança de 4 anos de idade levam seu filho a um pediatra credenciado\npela Sociedade Brasileira de Pediatria para uma\nrotina de puericultura. Durante a consulta, são\nfeitas várias perguntas relacionadas ao desenvolvimento infantil da criança, que são respondidas\npelos pais, e são realizados testes pelo pediatra. Com base no exposto e tendo em vista as\nrecomendações da Sociedade Brasileira de Pediatria, julgue o item a seguir. Independentemente\ndo local de atendimento, o médico deve manter um papel de educador, e não de socorrista nas\nsituações de desenvolvimento infantil.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-239350","number":"239350","sourceNumber":"239350","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma paciente de 12 anos de idade vai à consulta agendada em Unidade de Saúde da\nFamília acompanhada pela mãe. A familiar demonstra preocupações quanto ao desenvolvimento\nda filha, alegando ser esta uma das mais baixas entre as respectivas colegas e que ainda não teve\na primeira menstruação, a despeito de estar notando desenvolvimento das mamas há 10 meses,\nobservando-se a presença de broto mamário ao exame físico. Refere-se, também, que a mãe está\nreceosa de a filha vir a ser diagnosticada com síndrome dos ovários policísticos (SOP), tendo base\ntal preocupação em leitura de informações da internet em correlação com o fato de a filha\napresentar acne facial, de ainda nunca ter menstruado e de possuir histórico familiar de primeiro\ngrau de obesidade e diabetes mellitus tipo 2. Faz uso de metilfenidato 10 mg/dia por diagnóstico\nprévio de transtorno de deficit de atenção e hiperatividade, demonstrando manter atenção apenas\npara atividades do próprio interesse, sem, no entanto, apresentar histórico de baixo desempenho\nescolar ou prejuízo da vida social. Em avaliação ponderoestatural, verifica-se IMC de 21 kg/m²,\nconsiderado adequado para a idade da paciente. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. Conforme a normalidade de crescimento\ne desenvolvimento previsto para o sexo feminino, é esperado que a paciente apresente pico da\nvelocidade de crescimento em período de aproximadamente um ano após o aparecimento do broto\nmamário, período em que também se espera a menarca.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-255780","number":"255780","sourceNumber":"255780","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma criança de 11 meses de vida foi levada à unidade de saúde da família com história\nde tosse produtiva, febre há quatro dias e\ndificuldade respiratória. Além do quadro agudo, a mãe\ndemostrava preocupação pelo fato de a filha ainda não conseguir sentar sem apoio. Exame físico:\nbom estado geral; corada; hidratada; anictérica; acianótica; sem tiragem subcostal; presença de\nestertoração crepitante na base esquerda; FR = 68 irpm; FC = 118; SpO2 = 97%. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Conforme instrumento\nde vigilância do desenvolvimento, presente na Caderneta de Saúde da Criança, a criança deverá\nsentar sem apoio até o final do nono mês de vida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-196679","number":"196679","sourceNumber":"196679","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Paciente de 6 meses e 20 dias de vida, nascido com 35 semanas de idade gestacional,\né levado a uma consulta de puericultura pela\nmãe. Recebe aleitamento materno, papas de frutas e\nduas papas principais. A mãe demonstra muita preocupação, pois o lactente não senta sem apoio e\nnão rola no leito. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. Como o paciente ainda está em aleitamento materno, não é necessária a\nsuplementação com ferro.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-214399","number":"214399","sourceNumber":"214399","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Determinado paciente, atualmente com 24 meses de vida, é levado pela própria mãe,\nde 18 anos de idade, a consulta com\nespecialista em desenvolvimento. No histórico, observa- se\ngestação durante a adolêscencia da mãe, complicada por trauma abdominal durante discussão\ncom o pai da criança, às 34 semanas de gestação, causando descolamento prematuro da placenta,\ncom necessidade de parto cesáreo de emergência por sofrimento fetal agudo por ocasião. O RN\nnasceu com 1.800 g, sendo necessária a realização de manobras de reanimação neonatal. Ele\npermaneceu internado na unidade de terapia intensiva neonatal por quatro semanas. Apresentou,\nao exame físico, FC de 90 bpm, FR de 20 irpm, saturação de oxigênio de 99%, reflexo cutâneo\nplantar em extensão, reflexo de preensão palmar ausente e capacidade de marchar com apoio\n(mas não sozinho). Refere ausência de controle esfincteriano no momento. O paciente fala algumas\npalavras com duas sílabas. Em relação ao caso clínico descrito, julgue o item a seguir. A presença\ndo reflexo cutâneo plantar em extensão deve ser considerada normal até dois anos de idade; logo,\né normal nesse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-196689","number":"196689","sourceNumber":"196689","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Paciente de 6 meses e 20 dias de vida, nascido com 35 semanas de idade gestacional,\né levado a uma consulta de puericultura pela\nmãe. Recebe aleitamento materno, papas de frutas e\nduas papas principais. A mãe demonstra muita preocupação, pois o lactente não senta sem apoio e\nnão rola no leito. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. A criança apresenta atraso no desenvolvimento neuropsicomotor.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-196694","number":"196694","sourceNumber":"196694","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Paciente de 6 meses e 20 dias de vida, nascido com 35 semanas de idade gestacional,\né levado a uma consulta de puericultura pela\nmãe. Recebe aleitamento materno, papas de frutas e\nduas papas principais. A mãe demonstra muita preocupação, pois o lactente não senta sem apoio e\nnão rola no leito. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. A interpretação do peso, da estatura e do perímetro cefálico nas curvas de\ncrescimento da Organização Mundial da Saúde deve respeitar a idade corrigida do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-196699","number":"196699","sourceNumber":"196699","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Paciente de 6 meses e 20 dias de vida, nascido com 35 semanas de idade gestacional,\né levado a uma consulta de puericultura pela\nmãe. Recebe aleitamento materno, papas de frutas e\nduas papas principais. A mãe demonstra muita preocupação, pois o lactente não senta sem apoio e\nnão rola no leito. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. Nessa faixa etária, espera-se que o paciente tenha sorriso social, que reaja ao som,\nque vocalize e que agarre um brinquedo quando colocado na respectiva mão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-196612","number":"196612","sourceNumber":"196612","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Paciente de 6 meses e 20 dias de vida, nascido com 35 semanas de idade gestacional,\né levado a uma consulta de puericultura pela\nmãe. Recebe aleitamento materno, papas de frutas e\nduas papas principais. A mãe demonstra muita preocupação, pois o lactante não senta sem apoio e\nnão rola no leito. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. O desenvolvimento do paciente precisa ser estimulado com o uso de andadores.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-196681","number":"196681","sourceNumber":"196681","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Recém-nascido de parto vaginal, prematuro tardio, pequeno para a idade gestacional,\nApgar 8 ao primeiro minuto e 10 ao quinto\nminuto, apresenta, em regiões palmoplantares, lesões\ncutâneas bolhosas, com áreas de descamação subjacentes, além de esplenomegalia. A gestante\nnão realizou pré-natal. Com base, nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. Até que se obtenham resultados de testes rápidos maternos, efetuados no\npré-parto, a criança não deve ser amamentada, uma vez que a gestante não realizou pré-natal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-214482","number":"214482","sourceNumber":"214482","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"H. C. S., primeiro filho de C. C. S., realizou acompanhamento de puericultura em posto\nde saúde desde a primeira consulta pós-natal\naté atualmente, quando tem 8 anos de idade. Ao\nlongo desse acompanhamento, as variações antropométricas foram registradas nas curvas de\ncrescimento (peso para idade, estatura/altura para a idade, IMC para a idade), e o desenvolvimento\npsiconeuromotor foi avaliado. Na primeira consulta, foi verificada história de parto vaginal\nlaborioso,\nmas não havia histórico de outras complicações gestacionais ou periparto. Atualmente, nas curvas\nantropométricas, observam-se z-score de +3,34 no IMC para a idade e z-score de -1,75 na altura\npara a idade. Considerando as várias consultas realizadas nesse período, os raciocínios\ndiagnósticos e as condutas a serem tomadas frente ao crescimento e desenvolvimento normal e\npatológico, julgue o item a seguir. Tendo em vista que H.C.S. teve um desenvolvimento\nneuromuscular normal, certamente desenvolveu capacidade de engatinhar antes de andar com\napoio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-214503","number":"214503","sourceNumber":"214503","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"H. C. S., primeiro filho de C. C. S., realizou acompanhamento de puericultura em posto\nde saúde desde a primeira consulta pós-natal\naté atualmente, quando tem 8 anos de idade. Ao\nlongo desse acompanhamento, as variações antropométricas foram registradas nas curvas de\ncrescimento (peso para idade, estatura/altura para a idade, IMC para a idade), e o desenvolvimento\npsiconeuromotor foi avaliado. Na primeira consulta, foi verificada história de parto vaginal\nlaborioso,\nmas não havia histórico de outras complicações gestacionais ou periparto. Atualmente, nas curvas\nantropométricas, observam-se z-score de +3,34 no IMC para a idade e z-score de -1,75 na altura\npara a idade. Considerando as várias consultas realizadas nesse período, os raciocínios\ndiagnósticos e as condutas a serem tomadas frente ao crescimento e desenvolvimento normal e\npatológico, julgue o item a seguir. A realização de hemograma para rastreamento de anemia aos 24\nmeses de idade deve ser recomendada, na ocasião da suspensão da suplementação de ferro\nprofilática.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-196655","number":"196655","sourceNumber":"196655","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Determinada paciente de 16 anos de idade iniciou atendimento pré-natal em posto de\nsaúde da família e foi diagnosticada com\nHIV nas sorologias de primeiro trimestre, iniciando terapia\nantirretroviral adequada e com boa adesão imediatamente. Os demais exames de rotina de\n\npré-natal mostraram-se normais. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Apesar dos\ninúmeros benefícios do aleitamento materno para o\ncrescimento e o desenvolvimento da criança, ele está contraindicado na vigência da infecção\nmaterna pelo HIV. Tal contraindicação não se aplica nas infecções maternas por citomegalovírus,\ncaxumba, herpes simples (não mamária) e HTLV.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-179188","number":"179188","sourceNumber":"179188","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação à necessidade de ferro do lactente, é correto afirmar que","options":{"A":"O leite materno nos primeiros seis meses de vida previna anemia por possuir quantidades bem\nsuperiores de ferro que o leite de vaca.","B":"O ferro heme presente na hemoglobina e na mioglobina das carnes e vísceras tenha menor\nbiodisponibilidade e absorção que os contidos no feijão e no ovo.","C":"Fitatos, taninos, cálcio e fosfatos possuam efeito facilitador, aumentando a absorção do ferro.","D":"A vitamina A seja fator inibidor da absorção do ferro e deva ser oferecida como complementação\nsomente após um ano de idade.","E":"Crianças de seis a dezoito meses de vida devam receber o suplemento de ferro mesmo em\naleitamento materno."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-177649","number":"177649","sourceNumber":"177649","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"R.G.R., uma criança de 7 meses de idade, foi levada pelos pais a um pronto\natendimento infantil com quadro de tosse e\nsecreção nasal há cerca de 10 dias, com o\ndesenvolvimento de febre, nos últimos 2 dias, e respiração rápida. Ao exame físico, foram\nobservados uma orofaringe com hiperemia discreta, linfodonos cervicais normais, otoscopia normal\nbilateral, ausculta pulmonar com estertores crepitantes à esquerda, palpação abdominal normal,\nausência de sinais de irritação meníngea e inexistência de alterações dermatológicas. A frequência\nrespiratória foi de 52 incursões por minuto. Não havia presença de tiragem subcostal, nem de\ninsuficiência ventilatória, nem de cianose. A paciente consegue alimentar-se ao seio materno com\npouca dificuldade. A saturação periférica de oxigênio é de 96%. A radiografia de tórax demonstra\nárea de consolidação em lobo inferior esquerdo e derrame pleural de cerca de 1,5 cm. R.G.R., após\na resolução de seu quadro de saúde, foi levada por seus pais para um atendimento rotineiro de\npuericultura, agora com 9 meses de idade, com o médico de família e comunidade do posto de\nsaúde próximo à casa deles. Os pais estão realizando, na criança, a introdução alimentar de forma\nadequada, associada a 600 mL de fórmula láctea apropriada para a idade. A criança não está em\nuso de qualquer medicação ou suplemento. A respeito do caso clínico apresentado e de\nconhecimentos médicos correlatos, julgue o item a seguir. A suplementação de ferro profilática\ndeve ser iniciada ou reiniciada imediatamente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-177658","number":"177658","sourceNumber":"177658","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"R.G.R., uma criança de 7 meses de idade, foi levada pelos pais a um pronto\natendimento infantil com quadro de tosse e\nsecreção nasal há cerca de 10 dias, com o\ndesenvolvimento de febre, nos últimos 2 dias, e respiração rápida. Ao exame físico, foram\nobservados uma orofaringe com hiperemia discreta, linfodonos cervicais normais, otoscopia normal\nbilateral, ausculta pulmonar com estertores crepitantes à esquerda, palpação abdominal normal,\nausência de sinais de irritação meníngea e inexistência de alterações dermatológicas. A frequência\nrespiratória foi de 52 incursões por minuto. Não havia presença de tiragem subcostal, nem de\ninsuficiência ventilatória, nem de cianose. A paciente consegue alimentar-se ao seio materno com\npouca dificuldade. A saturação periférica de oxigênio é de 96%. A radiografia de tórax demonstra\nárea de consolidação em lobo inferior esquerdo e derrame pleural de cerca de 1,5 cm. R.G.R., após\na resolução de seu quadro de saúde, foi levada por seus pais para um atendimento rotineiro de\npuericultura, agora com 9 meses de idade, com o médico de família e comunidade do posto de\nsaúde próximo à casa deles. Os pais estão realizando, na criança, a introdução alimentar de forma\nadequada, associada a 600 mL de fórmula láctea apropriada para a idade. A criança não está em\nuso de qualquer medicação ou suplemento. A respeito do caso clínico apresentado e de\nconhecimentos médicos correlatos, julgue o item a seguir. De acordo com o Caderno de Atenção\nBásica de Saúde da Criança, recomendam-se sete consultas rotineiras no 1º ano de vida, para que\nhaja, entre outras ações, o acompanhemento do crescimento e do desenvolvimento da criança.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-177662","number":"177662","sourceNumber":"177662","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"R.G.R., uma criança de 7 meses de idade, foi levada pelos pais a um pronto\natendimento infantil com quadro de tosse e\nsecreção nasal há cerca de 10 dias, com o\ndesenvolvimento de febre, nos últimos 2 dias, e respiração rápida. Ao exame físico, foram\nobservados uma orofaringe com hiperemia discreta, linfonodos cervicais normais, otoscopia normal\nbilateral, ausculta pulmonar com estertores crepitantes à esquerda, palpação abdominal normal,\nausência de sinais de irritação meníngea e inexistência de alterações dermatológicas. A frequência\nrespiratória foi de 52 incursões por minuto. Não havia presença de tiragem subcostal nem de\ninsuficiência ventilatória nem de cianose. A paciente consegue alimentar-se ao seio materno com\npouca dificuldade. A saturação periférica de oxigênio é de 96%. A radiografia de tórax demonstra\nárea de consolidação em lobo inferior esquerdo e derrame pleural de cerca de 1,5 cm. R.G.R., após\na resolução de seu quadro de saúde, foi levada por seus pais para um atendimento rotineiro de\npuericultura, agora com 9 meses de idade, com o médico de família e comunidade do posto de\nsaúde próximo à casa deles. Os pais estão realizando, na criança, a introdução alimentar de forma\nadequada, associada a 600 ml de fórmula láctea apropriada para a idade. A criança não está em\nuso de qualquer medicação ou suplemento. A respeito do caso clínico apresentado e de\nconhecimentos médicos correlatos, julgue o item a seguir. O primeiro ano de vida é um momento\nde importante aceleração da velocidade de crescimento da criança.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-177613","number":"177613","sourceNumber":"177613","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"C.A.S., filho de J.A.S., agora está com 9 meses de idade. A mãe, muito atarefada\ndevido às responsabilidades maternais\nassociadas à necessidade de prover o sustento da família,\nresolveu comprar um andador (aparelho com rodas no qual a criança fica suspensa, podendo se\npropulsionar para frente ou para os lados), para que o filho tivesse mais liberdade para\n\nlocomover-se pela casa antes de aprender a andar. A respeito do andador e da relação desse\nobjeto com os traumas infantis, julgue o item a seguir. O andador facilita o desenvolvimento da\npercepção corporal e da capacidade de equilíbrio, essenciais para a marcha sem quedas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-177693","number":"177693","sourceNumber":"177693","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O escopo da abordagem comunitária do médico de família foge do completo isolamento\ndo consultório médico, envolvendo, também, ações\nde modificação do ambiente da comunidade,\nvisando à promoção da qualidade de vida e à prevenção de doenças da população. Considerando\nesse contexto, Rafael, residente do 2º ano de medicina de família e comunidade, procurou auxílio\nda prefeitura para implantar um programa de incentivo à atividade física, na área geográfica de sua\natuação, o qual incluía a revitalização da praça próxima ao posto, a implantação de academia ao ar\nlivre e a pista de caminhada. Três vezes por semana, Rafael investia a 1ª hora de sua manhã\norganizando um grupo de caminhada e orientando a população na prática de exercícios físicos.\n\nConsiderando a situação hipotética apresentada e os conhecimentos médicos correlatos, julgue o\nitem a seguir. Os exercícios resistidos são contraindicados para crianças, logo, na academia ao ar\nlivre, devem-se afixar placas solicitando que elas não utilizem os aparelhos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289437","number":"289437","sourceNumber":"289437","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considere que uma paciente de 7 anos de idade, previamente hígida, foi encaminhada\npelo clínico da unidade básica por estar\napresentando, há mais de quatro meses, crescimento\nmamário e pelos pubianos terminais. Apresentava dosagem de hormônio luteinizante (LH)\naumentada pós-estímulo, com hormônio liberador de gonadotrofina (GnRH). A respeito desse caso\nclínico, julgue o item a seguir. Trata-se provavelmente de puberdade precoce de origem central.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289439","number":"289439","sourceNumber":"289439","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considere que uma paciente de 7 anos de idade, previamente hígida, foi encaminhada\npelo clínico da unidade básica por estar\napresentando, há mais de quatro meses, crescimento\nmamário e pelos pubianos terminais. Apresentava dosagem de hormônio luteinizante (LH)\naumentada pós-estímulo, com hormônio liberador de gonadotrofina (GnRH). A respeito desse caso\nclínico, julgue o item a seguir. A dosagem sérica de GnRH não determina o diagnóstico bioquímico\nde puberdade precoce.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289441","number":"289441","sourceNumber":"289441","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considere que uma paciente de 7 anos de idade, previamente hígida, foi encaminhada\npelo clínico da unidade básica por estar\napresentando, há mais de quatro meses, crescimento\nmamário e pelos pubianos terminais. Apresentava dosagem de hormônio luteinizante (LH)\naumentada pós-estímulo, com hormônio liberador de gonadotrofina (GnRH). A respeito desse caso\nclínico, julgue o item a seguir. Deve-se solicitar ressonância magnética de crânio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289443","number":"289443","sourceNumber":"289443","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considere que uma paciente de 7 anos de idade, previamente hígida, foi encaminhada\npelo clínico da unidade básica por estar\napresentando, há mais de quatro meses, crescimento\nmamário e pelos pubianos terminais. Apresentava dosagem de hormônio luteinizante (LH)\naumentada pós-estímulo, com hormônio liberador de gonadotrofina (GnRH). A respeito desse caso\nclínico, julgue o item a seguir. A pubarca também poderia ser manifestação de puberdade precoce\nde origem periférica, embora a telarca precoce não possa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289445","number":"289445","sourceNumber":"289445","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considere que uma paciente de 7 anos de idade, previamente hígida, foi encaminhada\npelo clínico da unidade básica por estar\napresentando, há mais de quatro meses, crescimento\nmamário e pelos pubianos terminais. Apresentava dosagem de hormônio luteinizante (LH)\naumentada pós-estímulo, com hormônio liberador de gonadotrofina (GnRH). A respeito desse caso\nclínico, julgue o item a seguir. Espera-se encontrar idade óssea avançada em relação à idade\ncronológica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289473","number":"289473","sourceNumber":"289473","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um lactente de 6 meses de idade, nascido a termo de parto cesáreo, sem\nintercorrências no período neonatal, foi\nlevado à consulta de puericultura, sem queixas por parte da\nmãe. Ao nascer, pesava 2.900 kg, tinha estatura de 45 cm e perímetro cefálico de 34 cm. No\nmomento da consulta, apresenta peso de 7,00 kg, estatura de 60 cm e perímetro cefálico de 40 cm.\nPossui a fontanela anterior ainda aberta e normotensa. Com base nesse caso clínico, e acerca dos\nconhecimentos médicos relacionados ao crescimento e ao desenvolvimento nessa faixa etária,\njulgue o item a seguir. O paciente descrito apresenta peso e estatura abaixo do esperado para a\nidade, mas tem perímetro cefálico adequado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289478","number":"289478","sourceNumber":"289478","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um lactente de 6 meses de idade, nascido a termo de parto cesáreo, sem\nintercorrências no período neonatal, foi\nlevado à consulta de puericultura, sem queixas por parte da\nmãe. Ao nascer, pesava 2.900 kg, tinha estatura de 45 cm e perímetro cefálico de 34 cm. No\nmomento da consulta, apresenta peso de 7,00 kg, estatura de 60 cm e perímetro cefálico de 40 cm.\nPossui a fontanela anterior ainda aberta e normotensa. Com base nesse caso clínico, e acerca dos\nconhecimentos médicos relacionados ao crescimento e ao desenvolvimento nessa faixa etária,\njulgue o item a seguir. A fontanela anterior do paciente já deveria estar fechada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289480","number":"289480","sourceNumber":"289480","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considere hipoteticamente que um paciente de 11 anos de idade, hígido, é levado à\nconsulta pela mãe por queixar-se de apresentar estatura menor que a da irmã gêmea, além de\nginecomastia com broto mamário de 2,5 cm de diâmetro e ausência de pelos axilares e de pubarca,\nembora apresente aumento testicular. A respeito desse caso clínico, e considerando os\nconhecimentos médicos relacionados à puberdade masculina, julgue o item a seguir. Após o\ndesenvolvimento dos túbulos seminíferos, ocorre a maturação das células de Leydig e a produção\nde andrógenos testiculares. Por essa razão, os pelos pubianos aparecerão posteriormente ao\ncrescimento testicular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289482","number":"289482","sourceNumber":"289482","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considere hipoteticamente que um paciente de 11 anos de idade, hígido, é levado à\nconsulta pela mãe por queixar-se de apresentar estatura menor que a da irmã gêmea, além de\nginecomastia com broto mamário de 2,5 cm de diâmetro e ausência de pelos axilares e de pubarca,\nembora apresente aumento testicular. A respeito desse caso clínico, e considerando os\nconhecimentos médicos relacionados à puberdade masculina, julgue o item a seguir. O atraso do\ncrescimento em relação ao da irmã é motivo para o início de investigação de causas secundárias\nde baixa estatura.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289484","number":"289484","sourceNumber":"289484","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considere hipoteticamente que um paciente de 11 anos de idade, hígido, é levado à\nconsulta pela mãe por queixar-se de apresentar estatura menor que a da irmã gêmea, além de\nginecomastia com broto mamário de 2,5 cm de diâmetro e ausência de pelos axilares e de pubarca,\nembora apresente aumento testicular. A respeito desse caso clínico, e considerando os\nconhecimentos médicos relacionados à puberdade masculina, julgue o item a seguir. A massa\nmagra, que geralmente corresponde a 80% no período pré-puberal, aumenta para até 90% nos\nmeninos e diminui para cerca de 70%-75% nas meninas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289487","number":"289487","sourceNumber":"289487","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considere hipoteticamente que um paciente de 11 anos de idade, hígido, é levado à\nconsulta pela mãe por queixar-se de apresentar estatura menor que a da irmã gêmea, além de\nginecomastia com broto mamário de 2,5 cm de diâmetro e ausência de pelos axilares e de pubarca,\nembora apresente aumento testicular. A respeito desse caso clínico, e considerando os\nconhecimentos médicos relacionados à puberdade masculina, julgue o item a seguir. A\nginecomastia é fenômeno normal e comum na puberdade, chegando a acometer 60% dos meninos,\nmais frequentemente de apresentação unilateral.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289489","number":"289489","sourceNumber":"289489","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Considere hipoteticamente que um paciente de 11 anos de idade, hígido, é levado à\nconsulta pela mãe por queixar-se de apresentar estatura menor que a da irmã gêmea, além de\nginecomastia com broto mamário de 2,5 cm de diâmetro e ausência de pelos axilares e de pubarca,\nembora apresente aumento testicular. A respeito desse caso clínico, e considerando os\nconhecimentos médicos relacionados à puberdade masculina, julgue o item a seguir. Nesse caso, é\nimprovável que ocorra involução espontânea da ginecomastia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289491","number":"289491","sourceNumber":"289491","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma lactente de 10 meses de idade, nascida a termo, é levada ao pronto atendimento\npor apresentar coriza e tosse de leve\nintensidade. Ao exame físico, pode-se observar que necessita\ndo apoio do pediatra para manter-se sentada, ou inclina-se para frente apoiando as mãos na maca,\ne não mantém-se em pé, mesmo com apoio. A paciente rola e rasteja, mas não engatinha. Há\npresença de reflexos de preensão palmar e plantar. Quanto ao caso clínico apresentado, e\nconsiderando o desenvolvimento da paciente, julgue o item a seguir. O desenvolvimento da\npaciente está compatível com a respectiva idade cronológica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289493","number":"289493","sourceNumber":"289493","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma lactente de 10 meses de idade, nascida a termo, é levada ao pronto atendimento\npor apresentar coriza e tosse de leve\nintensidade. Ao exame físico, pode-se observar que necessita\ndo apoio do pediatra para manter-se sentada, ou inclina-se para frente apoiando as mãos na maca,\ne não mantém-se em pé, mesmo com apoio. A paciente rola e rasteja, mas não engatinha. Há\npresença de reflexos de preensão palmar e plantar. Quanto ao caso clínico apresentado, e\nconsiderando o desenvolvimento da paciente, julgue o item a seguir. Deveriam estar ausentes os\nreflexos de preensão palmar e plantar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289495","number":"289495","sourceNumber":"289495","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma lactente de 10 meses de idade, nascida a termo, é levada ao pronto atendimento\npor apresentar coriza e tosse de leve\nintensidade. Ao exame físico, pode-se observar que necessita\ndo apoio do pediatra para manter-se sentada, ou inclina-se para frente apoiando as mãos na maca,\ne não mantém-se em pé, mesmo com apoio. A paciente rola e rasteja, mas não engatinha. Há\npresença de reflexos de preensão palmar e plantar. Quanto ao caso clínico apresentado, e\nconsiderando o desenvolvimento da paciente, julgue o item a seguir. Deve-se interrogar os pais\nacerca do controle do esfíncter vesical, pois este já deve ter sido adquirido.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289497","number":"289497","sourceNumber":"289497","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma lactente de 10 meses de idade, nascida a termo, é levada ao pronto atendimento\npor apresentar coriza e tosse de leve\nintensidade. Ao exame físico, pode-se observar que necessita\ndo apoio do pediatra para manter-se sentada, ou inclina-se para frente apoiando as mãos na maca,\ne não mantém-se em pé, mesmo com apoio. A paciente rola e rasteja, mas não engatinha. Há\npresença de reflexos de preensão palmar e plantar. Quanto ao caso clínico apresentado, e\nconsiderando o desenvolvimento da paciente, julgue o item a seguir. Deve ser avaliada a\ncapacidade de transferir objetos de uma mão a outra, visto que essa habilidade já deve ter sido\nadquirida nessa idade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-289500","number":"289500","sourceNumber":"289500","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma lactente de 10 meses de idade, nascida a termo, é levada ao pronto atendimento\npor apresentar coriza e tosse de leve\nintensidade. Ao exame físico, pode-se observar que necessita\ndo apoio do pediatra para manter-se sentada, ou inclina-se para frente apoiando as mãos na maca,\ne não mantém-se em pé, mesmo com apoio. A paciente rola e rasteja, mas não engatinha. Há\npresença de reflexos de preensão palmar e plantar. Quanto ao caso clínico apresentado, e\nconsiderando o desenvolvimento da paciente, julgue o item a seguir. O desenvolvimento está muito\natrasado, e a lactente deveria estar andando sem apoio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-152112","number":"152112","sourceNumber":"152112","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente de um mês de idade é levado à unidade básica de saúde para sua segunda\nconsulta de puericultura. A mãe relata que\no paciente está em aleitamento materno exclusivo,\npeso= 4.125 g ( peso de nascimento = 3.620 g), comprimento de 53 cm, e perímetro cefálico de 36\ncm. Com base nessa situação, e considerando os conhecimentos médicos a ele relacionados,\njulgue o item a seguir. Recém-nascidos amamentados exclusivamente perdem, em média, entre\n5% e 7% do peso do nascimento nos primeiros dois ou três dias de vida, mas pode ser aceita a\nperda ponderal de até 10%, desde que recuperado o peso do nascimento até os 15 dias de vida do\npaciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-152120","number":"152120","sourceNumber":"152120","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente de um mês de idade é levado à unidade básica de saúde para sua segunda\nconsulta de puericultura. A mãe relata que\no paciente está em aleitamento materno exclusivo, peso\n\n= 4.125 g ( peso de nascimento = 3.620 g), comprimento de 53 cm, e perímetro cefálico de 36 cm.\nCom base nessa situação, e considerando os conhecimentos médicos a ele relacionados, julgue o\nitem a seguir. No final do primeiro ano de vida, segundo o Ministério da Saúde, esse paciente deve\nter comparecido a, no mínimo, oito consultas de puericultura.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-152128","number":"152128","sourceNumber":"152128","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O aleitamento materno é a mais sábia estratégia natural de afeto, vínculo, proteção e\nnutrição para a criança, e constitui a mais econômica, sensível e eficaz intervenção para redução\nda morbimortalidade infantil. Permite, ainda, um grandioso impacto na promoção da saúde integral\ndo binômio mãe/bebê e regozijo de toda a sociedade. Com base nas características do leite\nmaterno e nos benefícios do ato de amamentar, julgue o item a seguir: as principais dificuldades no\naleitamento materno ocorrem por erros de técnica de amamentação.","options":{"A":"CERTO","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-152139","number":"152139","sourceNumber":"152139","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O aleitamento materno é a mais sábia estratégia natural de afeto, vínculo, proteção e\nnutrição para a criança, e constitui a mais econômica, sensível e eficaz intervenção para redução\nda morbimortalidade infantil. Permite, ainda, um grandioso impacto na promoção da saúde integral\ndo binômio mãe/bebê e regozijo de toda a sociedade. Com base nas características do leite\nmaterno e nos benefícios do ato de amamentar, julgue o item a seguir: a Organização Mundial da\nSaúde e o Ministério da Saúde recomendam aleitamento materno exclusivo, sob livre demanda,\ndesde a sala de parto até os seis meses de vida, quando se inicia alimentação complementar,\nmantendo, contudo, até, no mínimo, os dois anos de idade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-152145","number":"152145","sourceNumber":"152145","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O aleitamento materno é a mais sábia estratégia natural de afeto, vínculo, proteção e\nnutrição para a criança, e constitui a mais econômica, sensível e eficaz intervenção para redução\nda morbimortalidade infantil. Permite, ainda, um grandioso impacto na promoção da saúde integral\ndo binômio mãe/bebê e regozijo de toda a sociedade. Com base nas características do leite\nmaterno e nos benefícios do ato de amamentar, julgue o item a seguir: uma das contraindicações\nda amamentação ocorre em neonatos que apresentam icterícia associada ao aleitamento materno.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-152076","number":"152076","sourceNumber":"152076","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O aleitamento materno é a mais sábia estratégia natural de afeto, vínculo, proteção e\nnutrição para a criança, e constitui a mais econômica, sensível e eficaz intervenção para redução\nda morbimortalidade infantil. Permite, ainda, um grandioso impacto na promoção da saúde integral\ndo binômio mãe/bebê e regozijo de toda a sociedade. Com base nas características do leite\nmaterno e nos benefícios do ato de amamentar, julgue o item a seguir: o neonato que se encontra\ncom a boca bem aberta, lábio inferior evertido, queixo tocando a mama e aréola materna mais\nvisível acima da boca do bebê do que abaixo apresenta sinais de uma pega efetiva.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-152096","number":"152096","sourceNumber":"152096","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O aleitamento materno é a mais sábia estratégia natural de afeto, vínculo, proteção e\nnutrição para a criança, e constitui a mais econômica, sensível e eficaz intervenção para redução\nda morbimortalidade infantil. Permite, ainda, um grandioso impacto na promoção da saúde integral\ndo binômio mãe/bebê e regozijo de toda a sociedade. Com base nas características do leite\nmaterno e nos benefícios do ato de amamentar, julgue o item a seguir: o leite materno possui maior\nconcentração de proteínas que o leite de vaca, predominando a caseína que tem a função de\ndefesa.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-131843","number":"131843","sourceNumber":"131843","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Acerca do aleitamento materno, assinale a alternativa CORRETA:","options":{"A":"São contraindicações absolutas ao aleitamento materno: mãe HIV-positiva, tuberculose materna\ncom doença ativa e uso de drogas\nantineoplásicas pela mãe.","B":"Uma boa técnica de amamentação engloba deglutição visível e audível, a boca do bebê deve\nestar bem aberta e abocanhando a maior parte da aréola da mama, o lábio inferior invertido e o\nqueixo deve estar tocando a mama materna.","C":"O colostro possui maior concentração de proteínas, imunoglobulinas, sais, vitamina A, vitamina\nE e lactoferrina, com menor concentração de\ngordura e lactose em relação ao leite maduro.","D":"A betalactoglobulina é a proteína do soro de maior concentração no leite materno.","E":"O aleitamento materno misto ou parcial é definido quando o bebê se alimenta de leite materno\nassociado a alimentos sólidos ou semissólidos."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134984","number":"134984","sourceNumber":"134984","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A respeito da baixa estatura na infância, julgue o item subsequente. A síndrome de\nCushing causa aumento crônico dos níveis séricos de cortisol, o que implica prejuízos ao processo\nde crescimento. A principal causa dessa patologia é a iatrogênica, motivada pelo uso de\ncorticosteroides na infância.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-134993","number":"134993","sourceNumber":"134993","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A respeito da baixa estatura na infância, julgue o item subsequente. Em regra, a\ndeficiência na produção dos hormônios tireoidianos durante a infância acarreta retardo do\ncrescimento, atraso na idade óssea e sinais clínicos como obstipação intestinal, apatia e lentidão.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-140755","number":"140755","sourceNumber":"140755","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Acerca do raquitismo na infância, julgue o item a seguir. O raquitismo é uma doença\nóssea caracterizada pela redução da mineralização\nda placa epifisária do osso em crescimento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-105548","number":"105548","sourceNumber":"105548","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O crescimento é um indicador bastante sensível do estado nutricional da criança. As\nsuas desacelerações ou acelerações estão\nassociadas ao aumento do risco de desenvolvimento de\ndoenças a curto e a longo prazos. No acompanhamento da curva de crescimento no ambulatório de\ncrescimento e desenvolvimento, é CORRETO afirmar que:","options":{"A":"As crianças com baixo peso ao nascer têm menor risco de apresentar doenças cardiovasculares.","B":"Uma elevada velocidade de crescimento durante a infância apresenta risco aumentado para\ndesenvolver obesidade e diabetes tipo I.","C":"A baixa estatura é um alerta para a presença de doenças crônicas.","D":"A diminuição de apetite da criança, informada pela mãe, geralmente está associada a doenças\ncrônicas, mesmo com as curvas de crescimento dentro do normal.","E":"A recuperação geralmente é muito lenta e às vezes irreversível após a perda ponderal devido a\nalguma doença aguda."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-108238","number":"108238","sourceNumber":"108238","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"No item abaixo, é apresentado um caso clínico a respeito do crescimento e do\ndesenvolvimento na infância e na\nadolescência, seguido de uma assertiva que deve ser julgada. A\nmãe de um lactente, de quatro meses de idade, alimentado exclusivamente com leite materno,\nqueixou-se ao pediatra que o leite dela não estava sendo suficiente para nutrir o bebê, uma vez que\nele estava crescendo pouco e deveria, portanto, receber outros tipos de alimento. O exame médico\nda criança mostrou um desenvolvimento psicomotor normal com peso e altura situados no escore Z\n\n= 0. A caderneta de vacinação da criança estava atualizada até o 3° mês de vida. Nesse caso, o\nmédico deve recomendar que a mãe mantenha o aleitamento materno exclusivo, que exponha o\nbebê diretamente à luz solar por uma hora pela manhã e que faça as segundas doses das vacinas\npentavalentes antipoliomielite injetável, antipneumocócica decavalente e antirrotavírus.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-108176","number":"108176","sourceNumber":"108176","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Julgue o item a seguir, relativo à deficiência de crescimento do corpo. Diversos genes\nresponsáveis por codificar fatores de transcrição estão implicados na etiologia da deficiência\ncombinada dos hormônios hipofisários (pan-hipopituitarismo), sendo o gene PROP-1 o mais\nfrequentemente envolvido.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-79673","number":"79673","sourceNumber":"79673","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Criança de 4 anos, com crescimento normal até os 2 anos de idade, com velocidade de\ncrescimento de 3 cm/ano no último ano. Assinale a alternativa que apresenta a hipótese\ndiagnóstica:","options":{"A":"Crescimento normal.","B":"Deficit de hormônio de crescimento.","C":"Gigantismo.","D":"Crescimento acelerado por possível hiperalimentação/obesidade.","E":"Crescimento tipo \"catch-up\" em crianças com histórico de prematuridade."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-88630","number":"88630","sourceNumber":"88630","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação ao acompanhamento do crescimento e ao desenvolvimento infantil, julgue\no item subsecutivo. O uso de hormônio de\ncrescimento é contraindicado para as pacientes com\nsíndrome de Turner, que apresentam baixa estatura, mas elevada predisposição a desenvolver\nneoplasias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-88640","number":"88640","sourceNumber":"88640","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação ao acompanhamento do crescimento e ao desenvolvimento infantil, julgue\no item subsecutivo. No raquitismo por\nresistência à vitamina D, o mecanismo fisiopatológico é uma\nmutação no gene que codifica a enzima 1-alfa-hidroxilase, o que compromete a conversão da\nmolécula inativa (25-hidroxi-vitamina D) na molécula ativa (1,25-diidroxi-vitamina D).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-88643","number":"88643","sourceNumber":"88643","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação ao acompanhamento do crescimento e ao desenvolvimento infantil, julgue\no item subsecutivo: Cerca de 40% a 50% dos\nneonatos que nascem a termo e pequenos para a\nidade gestacional recuperam sua curva de crescimento até os trinta e seis meses de idade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-88649","number":"88649","sourceNumber":"88649","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação ao acompanhamento do crescimento e ao desenvolvimento infantil, julgue\no item subsecutivo. Crianças com baixa\nestatura constitucional (retardo constitucional do\ncrescimento e puberdade) apresentam estatura abaixo do percentil 3 da curva de crescimento,\nvelocidade de crescimento adequada para a faixa etária e atraso na idade óssea, com previsão de\nestatura na vida adulta de acordo com a hereditariedade familiar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-82075","number":"82075","sourceNumber":"82075","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"No que concerne à atenção à saúde da criança, julgue o próximo item. A caderneta de\nsaúde da criança do Ministério da Saúde\nutiliza como parâmetros para avaliação do crescimento de\ncrianças os gráficos de perímetro cefálico, peso para a idade, comprimento/estatura para a idade e\nÍndice de Massa Corporal (IMC).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-64646","number":"64646","sourceNumber":"64646","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação ao crescimento e ao desenvolvimento de uma criança de 2 (dois) meses, é\nesperado que ela tenha determinadas respostas. A esse respeito, analise as assertivas abaixo: I. A\ncriança observa rostos. II. A criança segue objetos ultrapassando a linha média. III. A criança\nreage\nao som. IV. A criança eleva a cabeça e a mantém a 45°. V. A criança transfere um objeto de uma\nmão para outra. É correto o que se afirma em:","options":{"A":"I e V, apenas.","B":"II e III, apenas.","C":"III e IV, apenas.","D":"II, III e IV, apenas.","E":"I, II, III e IV, apenas."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343406","number":"343406","sourceNumber":"343406","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Na Pediatria, diferentemente da população adulta, os valores pressóricos normais são\ndefinidos de acordo com dados obtidos a partir da aferição da Pressão Arterial de crianças sadias e\ndistribuídos em uma tabela normativa com base em:","options":{"A":"Idade, estatura e peso.","B":"Sexo, peso, estatura.","C":"Idade, sexo e estatura.","D":"Sexo, idade e peso."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-334890","number":"334890","sourceNumber":"334890","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Acerca do tem síndrome de Down, assinale a alternativa correta.","options":{"A":"Por causa de o risco de hipotireoidismo ser alto ao longo da vida, deve-se solicitar a dosagem de\nTSH anualmente.","B":"O ecocardiograma se faz necessário caso se auscultem sopros cardíacos, pois cardiopatia é\nrara nesses pacientes.","C":"Recomenda-se evitar cambalhotas, futebol e mergulhos em razão da língua protusa da\nmicrognatia.","D":"Há um calendário de imunização específico para as crianças com síndrome de Down, com\ndiferenças nas idades das vacinas.","E":"Intervenções como fisioterapia motora e fonoaudiologia são indicadas somente quando há\nqueixa específica."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343423","number":"343423","sourceNumber":"343423","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"PGL, 3 meses, portador de Síndrome de Down. Mãe comparece à consulta pediátrica\nrelatando que seu filho tem cansaço ao\nmamar. Na avaliação, foi constatado baixo ganho ponderal.\nAo exame cardiológico, observa-se ritmo cardíaco regular, em 2 tempos, B2 hiperfonética em foco\npulmonar, com sopro sistólico em borda esternal esquerda, sendo que a saturação periférica de\noxigênio era de 98%. O diagnóstico mais provável é:","options":{"A":"Transposição das grandes artérias.","B":"Defeito do septo atrioventricular forma total.","C":"Tetralogia de Fallot.","D":"Comunicação interatrial."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-343424","number":"343424","sourceNumber":"343424","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Após 5 (cinco) dias de alta da maternidade, um recém-nascido a termo apresentou\ntendência em manter uma postura com extensão de cabeça e tronco. Tal atitude postural é:","options":{"A":"Normal nessa e em qualquer faixa etária, com necessidade de intervenção por meio de\norientação aos pais.","B":"Anormal e com necessidade de encaminhamento imediato à equipe de reabilitação.","C":"Anormal, mas com conduta expectante.","D":"Normal nessa faixa etária, não necessitando de intervenção."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-273319","number":"273319","sourceNumber":"273319","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente com quatro meses é trazido à consulta rotineira, porém a avó diz estar\npreocupada porque tem notado que as mãos do\nseu neto estão constantemente fechadas. Qual a\nconduta adequada?","options":{"A":"Considerar como uma observação extremamente importante e que necessita de uma avaliação\nneurológica detalhada, antes de qualquer conclusão, já que é um sinal importante de espasticidade.","B":"Considerar como uma preocupação excessiva da avó, porém mandaria retornar para reavaliação\napós 1 mês.","C":"Considerar como uma preocupação excessiva da avó já que esta postura é normal até os 4\nmeses.","D":"Considerar como uma preocupação bastante comum das avós e que geralmente não tem\nsignificado patológico."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-268901","number":"268901","sourceNumber":"268901","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um lactente de 4 meses de idade, amamentado exclusivamente com leite materno, é\nlevado à unidade básica de saúde para consulta de puericultura. Durante a verificação da curva de\npeso da Caderneta de Saúde da Criança, observa-se um declínio dessa curva. Considerando o\nmencionado quadro clínico e os conhecimentos médicos a ele relacionados, assinale a alternativa\ncorreta.","options":{"A":"A Caderneta de Saúde da Criança não deve ser parâmetro para avaliação do crescimento.","B":"As novas curvas de crescimento da Organização Mundial da Saúde definem o que seria um\ncrescimento ideal para crianças pequenas.","C":"As curvas de crescimento somente devem ser usadas quando há dúvida quanto ao crescimento\napós o exame físico.","D":"Nesse caso, a melhor conduta seria a retirada do aleitamento materno com substituição por\nfórmula infantil.","E":"A curva de peso é um bom parâmetro, utilizado isoladamente, para avaliação do crescimento\ninfantil."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-268905","number":"268905","sourceNumber":"268905","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Durante a consulta de puericultura, a mãe de um lactente de 1 mês de vida queixa-se\nde muita dor ao oferecer a mama esquerda para o\nfilho. A mama está turgida, vermelha e quente.\nNo que se refere ao diagnóstico de mastite, assinale a alternativa correta.","options":{"A":"Para a prevenção da mastite, é necessário orientar as mães a oferecerem mamadas com\nhorários regulares.","B":"Nos recém-nascidos prematuros que não esvaziam a mama, pode-se melhorar a sucção\noferecendo o bico da mamadeira.","C":"O sabor do leite materno costuma alterar-se nas mastites em razão do aumento dos níveis de\nsódio e da diminuição dos níveis de lactose.","D":"Deve-se explicar à mãe que a dor, muitas vezes, faz parte da amamentação, sendo necessários\nanalgésicos regulares.","E":"No lactente sadio, a conduta imediata é a suspensão do aleitamento materno."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-268909","number":"268909","sourceNumber":"268909","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma menina de 7 anos de idade apresenta cheiro axilar forte, pelos pubianos e axilares\nralos e mamas em fase de botão (elevação\nda mama e aréola como pequeno montículo). Tendo em\nvista o mencionado quadro clínico e os conhecimentos médicos correlatos, assinale a alternativa\ncorreta.","options":{"A":"Pela descrição, o estadiamento de Tanner é de M3 P3.","B":"O diagnóstico é de puberdade precoce, em razão do aparecimento das mamas antes dos 8 anos\nde idade nas meninas.","C":"Espera-se, normalmente, um ritmo de desenvolvimento rápido entre o início das mamas e a\nprimeira menstruação.","D":"O crescimento exagerado de mãos e pés pode ser o primeiro sinal de puberdade central.","E":"Os desreguladores endócrinos podem ajudar a reduzir os casos de puberdade precoce."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-274626","number":"274626","sourceNumber":"274626","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Várias patologias podem também apresentar anomalias laboratoriais comuns com\nsinais e sintomas clínicos diferentes. As síndromes usualmente são denominadas pelo nome do\nmédico ou cientista que primeiro as descreveu. Quanto às características da Síndrome de\nHutchinson-Gilford, é CORRETO afirmar:","options":{"A":"É conhecida como a doença dos tiques e as crianças que a sofrem realizam movimentos rápidos\ne involuntários dos músculos e produção\ninvoluntária de ruídos e palavras.","B":"É uma doença genética rara caracterizada pelo envelhecimento acelerado das crianças. As\ncrianças nascem saudáveis, mas em poucos meses a doença mostra o seu lado, dando o aspecto\nà criança como de um ancião.","C":"É uma doença genética rara caracterizada pelo não envelhecimento das crianças. As crianças\nnascem saudáveis, mas não se desenvolvem, apresentando aspecto infantil até mesmo na fase\nadulta.","D":"É conhecida como a doença dos ossos de vidro, que é uma condição rara que tem como\nprincipal característica a fragilidade dos ossos, que quebram com enorme facilidade."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-266466","number":"266466","sourceNumber":"266466","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma menina de seis anos de idade foi levada ao pediatra por apresentar discreto\nsangramento vaginal. A mãe informou que a criança\napresentava aumento do volume das mamas\nseguido do aparecimento de pelos pubianos havia um ano. Não havia história familiar semelhante e\noutros antecedentes significativos. Ao exame físico, foram verificados: peso = 22 kg (escore Z = +1\npara a idade); altura = 122,5 cm (escore +1<Z<+2 para a idade); sem achados morfológicos\nsignificativos; Tanner: M3P1. Os exames complementares apresentaram os seguintes resultados:\nLH 3 mU/mL (VR < 1,3); FSH 7mU/mL (VR = 0,11 a 1,6); estradiol 80 mU/mL (VR = 0 a 46); US\n\npélvica: útero de volume normal, com linha endometrial e ovários aumentados de volume; idade\nóssea: 8 anos. Com relação a esse caso\nclínico, julgue o item a seguir. Nesse caso, não está\nindicada a realização de ressonância magnética do cérebro com contraste como método avaliativo\nadicional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-291519","number":"291519","sourceNumber":"291519","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma lactente de 13 meses de idade, de sexo feminino, é levada à Unidade Básica de\nSaúde para consulta de rotina. A mãe está\npreocupada, pois a criança ainda não é capaz de andar\nsem apoio. Não há outras queixas. O pré-natal materno não possui intercorrências; nasceu de parto\nnormal, com 40 semanas de idade gestacional; Boletim de Apgar no 1º. minuto = 6; no 5º. minuto =\n9; e no 10º. minuto = 10; com peso ao nascer = 3 200 g e comprimento ao nascer = 50 cm. No\nexame clínico neonatal, observou-se estalido à manobra de Ortolani à direita; na ocasião, realizou\nexame ultrassonográfico de quadril apresentando resultado I pelo método de Graf. Recebeu alta no\nsegundo dia de vida. Sem antecedentes pessoais ou familiares relevantes. Desenvolvimento\nneuropsicomotor prévio: sorriso social aos 2 meses; fixou o pescoço aos três meses; sentou sem\napoio aos sete meses; passou a distinguir familiares de estranhos e a reconhecer seu nome aos\nnove meses; primeiras palavras com significado aos 11 meses. Atualmente engatinha, fica em pé\ncom apoio das mãos e arrisca alguns passos sem apoio, mas logo cai; usa copo com ajuda,\ncompreende ordens simples, bate palma, manda beijo, fala ''mama'' e ''papa'' para referir-se à mãe\ne ao pai respectivamente. Não apresenta alterações ao exame clínico. A conduta adequada para\nessa criança, considerando o desenvolvimento da marcha é","options":{"A":"manter acompanhamento de rotina.","B":"encaminhar para fisioterapia motora para membros inferiores.","C":"encaminhar ao neurologista devido à anoxia perinatal.","D":"encaminhar ao ortopedista por suspeita de displasia congênita do quadril."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-266469","number":"266469","sourceNumber":"266469","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A ginecologia infanto-puberal é a área de estudo que abrange os cuidados do sistema\nreprodutor feminino, desde o nascimento até a puberdade. Essa área abarca, por exemplo,\ndistúrbios de diferenciação sexual, sinequias, corrimentos e traumas genitais. A respeito desse\nassunto, julgue o item a seguir. A puberdade precoce, que se manifesta por meio do\ndesenvolvimento de caracteres sexuais secundários antes dos oito anos de idade, pode ser dividida\nem puberdade precoce verdadeira - até 80% dos casos - ou pseudopuberdade precoce - cerca\n20% dos casos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-266471","number":"266471","sourceNumber":"266471","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A ginecologia infanto-puberal é a área de estudo que abrange os cuidados do sistema\nreprodutor feminino, desde o nascimento até a puberdade. Essa área abarca, por exemplo,\ndistúrbios de diferenciação sexual, sinequias, corrimentos e traumas genitais. A respeito desse\nassunto, julgue o item a seguir. No processo de investigação do tipo de puberdade tardia - a qual\npode ser dividida em hipogonadismo hipogonadotrófico, hipogonadismo hipergonadotrófico e atraso\nconstitucional do desenvolvimento puberal -, além de anamnese e de exames físicos, são\nnecessárias dosagens hormonais e realização de exames de imagem para elucidação diagnóstica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-263404","number":"263404","sourceNumber":"263404","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um lactente com 1 mês de vida, nascido a termo de parto normal sem intercorrências,\nem aleitamento materno exclusivo, retornou à\nUnidade Básica de Saúde para consulta de\npuericultura. A mãe começou a apresentar febre (temperatura axilar = 38ºC) há 2 dias e\n\nencontra-se em bom estado geral. Apresenta dor, calor, edema e rubor em quadrante superior\nesquerdo da mama direita, sendo indicado tratamento domiciliar com cefalexina e ibuprofeno.\nNesse caso, o aleitamento materno deverá","options":{"A":"ser mantido em ambas as mamas como parte da terapêutica materna.","B":"ser mantido, oferecendo somente a mama esquerda e preservando a mama afetada.","C":"ser suspenso pelo risco de contaminação do lactente pelas bactérias presentes no leite.","D":"ser suspenso devido ao uso materno de medicamentos incompatíveis com a amamentação."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-266498","number":"266498","sourceNumber":"266498","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Alice, com 16 anos de idade, questionou, durante consulta médica, sobre a\npossibilidade de colocar um DIU na UBS,\npois tivera relação sexual desprotegida havia cerca de\nquatro dias. Ao médico ela relatou que a sua última menstruação havia ocorrido 15 dias atrás e que\no seu ciclo menstrual era irregular, de 20 a 28 dias, com 7 dias de fluxo normal, sem cólicas. Tendo\ncomo referência esse caso clínico hipotético, julgue o item subsecutivo. Um termo de\nconsentimento para a inserção do DIU em Alice, que é menor de idade, deve ser necessariamente\nassinado pela paciente e por seu responsável legal maior de idade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-244485","number":"244485","sourceNumber":"244485","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Determinada mulher leva o respectivo filho de 2 anos de idade para consulta ao\npediatra. Queixa-se de que acha seu filho\ndiferente das outras crianças, dizendo que ele tem um\ncomportamento estranho. A criança apresenta grande dificuldade para se alimentar, sendo\nbastante seletivo. Tem comportamento muitas vezes agitado e ainda não fala. Com base na\navaliação clínica feita pelo pediatra, suspeita-se de transtorno do espectro autista. Tendo em\nvista o\ncaso clínico descrito, assinale a alternativa correspondente aos sinais clínicos que podem, em\nconjunto, estar relacionados a esse diagnóstico.","options":{"A":"Ser afetuoso com os pais; gostar de carinhos; correr bem sem apoio.","B":"Ter movimentos estereotipados ao brincar; pode dar gritos; preferir contato com figuras humanas\nque objetos; pedir ajuda para empilhar\nblocos.","C":"Tender a ordenar objetos de forma sistemática; não dar \"\"tchau\"\" ou mandar beijo; dificilmente\nexpressar afeto.","D":"Estabelecer pouco contato visual; ser muito apegado à mãe; preferir brincar com cuidador\nhabitual que sozinho.","E":"Responder bem quando é chamado; ser agitado; ter dificuldade de se concentrar em atividades\ndirigidas, mas ficar quieto quando tem grande interesse."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-227412","number":"227412","sourceNumber":"227412","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma menina de sete anos de idade foi levada a um pediatra porque a mãe havia\nobservado aumento das mamas da criança seguido\npelo aparecimento de pilificação pubiana, fatos\nesses ocorridos nos últimos 3 meses anteriores à consulta. Não havia relato de metrorragia. A\nmenina pesava 25 kg (Z Score +1) e media 125 cm (Z Score +1). No exame físico, o médico\nobservou aumento da aréola e da papila, sem separação do contorno da mama, e pelugem fina,\nlonga e pouco escura na linha central da região pubiana. O restante do exame físico somático e o\nexame neurológico resultaram normais. O valor do nível de LH após estímulo com GnRH foi de 6\nUI/L. Com base nesse caso clínico, julgue o item que se segue. O tratamento mais indicado ao\ncaso é a administração de agonistas de longa ação do GnRH (hormônio liberador de\ngonadotrofinas), com o objetivo de suprimir a produção de gonadotrofinas hipofisárias e de\nesteroides sexuais, para, assim, promover-se a regressão dos caracteres sexuais secundários e\ndiminuir a velocidade de crescimento e progressão da idade óssea.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-230599","number":"230599","sourceNumber":"230599","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A ginecomastia é a proliferação benigna mais comum do tecido glandular da mama\nmasculina, causada pela alteração do equilíbrio entre as concentrações de estrógeno e\nandrogênios. Pela Classificação de Simon, a mama que apresenta aumento mamário moderado\ncom redundância de pele definida, similar a mama feminina corresponde ao grau:","options":{"A":"I.","B":"II.","C":"III.","D":"IV."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-206173","number":"206173","sourceNumber":"206173","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Assinale a alternativa CORRETA sobre a Puberdade Precoce (PP):","options":{"A":"Tumor ovariano é a causa mais comum de PP em meninas.","B":"Telarca é o marco inicial da PP Central (Dependente de Gonadotrofinas) em meninas.","C":"Pacientes com telarca precoce habitualmente cursam com atraso na idade óssea.","D":"Em meninos com PP central, há predomínio da forma idiopática."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-203154","number":"203154","sourceNumber":"203154","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Os pais levam a filha de 8 meses de idade a uma consulta de rotina de puericultura. A\ncriança é nascida a termo, de 40 semanas de gestação, com peso e comprimento ao nascimento\nadequados para idade gestacional e previamente hígida. Durante a avaliação do desenvolvimento\nneuropsicomotor, os pais questionam se o desenvolvimento da menina está dentro do normal para\na idade. Acerca desse caso clínico, é correto afirmar que o desenvolvimento neuropsicomotor\ndessa paciente está adequado se ela apresentar as seguintes características:","options":{"A":"brinca de esconde-achou, produz \"jargão\", imita gestos e senta-se sem apoio.","B":"Transfere objetos de uma mão para outra, produz \"jargão\", duplica sílabas e senta-se sem apoio.","C":"Brinca de esconde-achou, transfere objetos de uma mão para outra, duplica sílabas e senta-se\nsem apoio.","D":"Transfere objetos de uma mão para outra, faz pinça, imita objetos e duplica sílabas.","E":"Brinca de esconde-achou, transfere objetos de uma mão para outra, \"produz jargão\" e imita\ngestos."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-206164","number":"206164","sourceNumber":"206164","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"No hipogonadismo hipogonadotrófico, encontramos:","options":{"A":"Atraso puberal por deficiência primária das gônodas.","B":"Atraso puberal na Síndrome de Turnner.","C":"Atraso puberal por deficiência hipofisária ou hipotalâmica.","D":"Atraso puberal na Síndrome de Klinefelter."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-203075","number":"203075","sourceNumber":"203075","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação aos princípios éticos em uma consulta de hebiatria, assinale a alternativa\ncorreta.","options":{"A":"O adolescente de 10 anos a 14 anos de idade frequentemente ainda não tem a capacidade de\nassumir todas as responsabilidades, porém pode ser visto sozinho durante toda a consulta, desde\nque conste em prontuário tal informação.","B":"O adolescente terá autonomia para dar assentimento à assistência ou recusá-la, mesmo à\nrevelia dos pais, caso isso conste em prontuário, exceto em situações consideradas de risco.","C":"O termo de assentimento é recomendado para adolescentes que têm a capacidade de tomar\ndecisões com relação à vida futura.","D":"O termo de consentimento é fornecido para adolescentes que têm a capacidade de tomar\ndecisões a respeito da própria vida futura.","E":"O adolescente terá autonomia para dar assentimento à assistência ou recusá-la, mesmo à\nrevelia dos pais, caso isso conste em prontuário, independentemente do tipo de assistência."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-203063","number":"203063","sourceNumber":"203063","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma paciente de 9 anos de idade é levada ao consultório pela mãe para avaliação, já\nque a mãe se apresentava muito preocupada em razão do surgimento de broto mamário e\npilificação pubiana da filha, que ainda não apresentou menarca. Ao exame físico, apresenta\nestatura no percentil 75 para a idade, mamas no estágio M2 de Tanner e pilificação no estágio P3.\nQuanto a esse caso clínico, assinale a alternativa que indica a conduta a ser tomada pelo médico\nassistente.","options":{"A":"Orientar a paciente e a respectiva mãe de que se trata de quadro de puberdade fisiológica, e\nnão há necessidade de realizar, no momento,\ninvestigação com dosagem hormonal sérica.","B":"Avaliar a idade óssea com raio X da mão direita para definição da compatibilidade da idade\nóssea e puberal.","C":"Iniciar agonista de GnRh para evitar a continuação do desenvolvimento puberal no momento,\ntendo em vista que se trata de puberdade\nprecoce.","D":"Realizar o rastreio de condições clínicas que cursam com hirsutismo, como síndrome dos\novários policísticos e hiperplasia adrenal congênita.","E":"Solicitar ecografia mamária para exclusão de ginecomastia."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-212124","number":"212124","sourceNumber":"212124","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Para consulta de rotina, uma mãe levou ao pediatra seus filhos: Mariana, de 7 anos de\nidade, e João, de 11 anos de idade. No exame físico, de acordo com os critérios de Tanner:\nMariana - M2P2; e João - G1P1. Considerando essas informações e os vários aspectos a elas\nrelacionados, julgue o item a seguir. Segundo os critérios de Tanner, João está com atraso puberal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-212127","number":"212127","sourceNumber":"212127","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Para consulta de rotina, uma mãe levou ao pediatra seus filhos: Mariana, de 7 anos de\nidade, e João, de 11 anos de idade. No exame físico, de acordo com os critérios de Tanner:\nMariana - M2P2; e João - G1P1. Considerando essas informações e os vários aspectos a elas\nrelacionados, julgue o item a seguir. O marco biológico do início da puberdade no menino é, o\naumento testicular, que corresponde a G2 dos critérios de Tanner.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-212019","number":"212019","sourceNumber":"212019","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Para consulta de rotina, uma mãe levou ao pediatra seus filhos: Mariana, de 7 anos de\nidade, e João, de 11 anos de idade. No exame físico, de acordo com os critérios de Tanner:\nMariana - M2P2; e João - G1P1. Considerando essas informações e os vários aspectos a elas\nrelacionados, julgue o item a seguir. É esperado que a menarca da Mariana ocorra entre dois, e\ndois ano e meio a partir da telarca.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-212028","number":"212028","sourceNumber":"212028","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Para consulta de rotina, uma mãe levou ao pediatra seus filhos: Mariana, de 7 anos de\nidade, e João, de 11 anos de idade. No exame físico, de acordo com os critérios de Tanner:\nMariana - M2P2; e João - G1P1. Considerando essas informações e os vários aspectos a elas\nrelacionados, julgue o item a seguir. Verifica-se o estirão puberal nas fases iniciais da puberdade:\nno sexo masculino, ocorre no estágio G2; no sexo feminino, no estágio M3 e M4 das mamas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-175101","number":"175101","sourceNumber":"175101","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A Sociedade Brasileira de Pediatria orienta que a alimentação e a suplementação\nvitamínica em crianças seja:","options":{"A":"Vitamina D 400 UI/dia e Ferro 1 mg/Kg dia, desde o nascimento até os seis meses de vida, para\ncrianças em aleitamento materno exclusivo.","B":"Vitamina D 600 UI/dia e Ferro 2 mg/Kg dia para crianças com seis meses de vida que se\nalimentem com aleitamento materno, duas papas de frutas/dia e duas papas salgadas/dia.","C":"Vitamina D 600 UI/dia e Ferro elementar 1 mg/Kg dia para crianças com 13 meses que estejam\nrecebendo aleitamento materno, duas papas de frutas/dia e duas refeições salgadas/dia.","D":"Viamina D 400 UI/dia e Ferro elementar 1 mg/Kg dia para crianças com 18 meses que recebem\naleitamento materno, duas papas de frutas/dia e duas refeições salgadas/dia."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-177225","number":"177225","sourceNumber":"177225","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma paciente puérpera, no quinto dia após o parto vaginal, começa a apresentar\nlesões vesiculares peribucais. O filho da paciente\né saudável e não apresenta lesões.\n\nConsiderando-se o mencionado caso hipotético e os conhecimentos médicos relacionados a ele, é\ncorreto afirmar que a conduta recomendada é","options":{"A":"suspender o aleitamento materno, isolando o recém-nascido da mãe até a melhora das lesões.","B":"suspender o aleitamento materno e utilizar fórmula.","C":"manter o aleitamento materno e iniciar tratamento com aciclovir.","D":"manter o aleitamento materno.","E":"suspender o aleitamento materno, isolando o recém nascido da mãe e iniciando tratamento com\naciclovir tópico."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-175102","number":"175102","sourceNumber":"175102","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O crescimento e desenvolvimento da criança no primeiro ano de vida devem ser\nmonitorados com rigor para o reconhecimento de patologias de risco. Deve-se esperar que no","options":{"A":"primeiro semestre de vida, o lactente deva crescer 10 cm.","B":"segundo trimestre de vida, o lactente deva ganhar 15g/dia.","C":"quinto mês de vida, o seu peso será o triplo do peso do seu nascimento.","D":"primeiro mês de vida, o perímetro cefálico deva crescer 0,5 cm/semana."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-175103","number":"175103","sourceNumber":"175103","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"As crianças vão ganhando aptidões ao longo dos seus dias de vida devido ao\ndesenvolvimento neuropssicomotor, que quando adequado","options":{"A":"a criança anda com apoio a partir do oitavo mês.","B":"a criança transfere objetos de uma mão para outra, desde o quinto mês de vida.","C":"a criança senta-se sem apoio a partir do sexto mês de vida.","D":"a criança segura objetos a partir do sexto mês de vida."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-183884","number":"183884","sourceNumber":"183884","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O acompanhamento do crescimento e do desenvolvimento da criança é fundamental\ncomo medida de medicina preventiva.\nConsiderando esse assunto e os múltiplos aspectos a ele\nrelacionados, julgue o item que se segue. O hormônio de crescimento atua diretamente sobre a\nsíntese dos condroblastos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-183914","number":"183914","sourceNumber":"183914","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Tendo como referência as diretrizes da Política Nacional de Promoção da Saúde\n(PNPS), da Política Nacional de Atenção\nBásica (PNAB), da Política Nacional de Alimentação e\nNutrição (PNAN), da Política Nacional de Promoção, Proteção e Apoio ao Aleitamento Materno e da\nRede Cegonha, julgue o item seguinte. Para a segurança do recém-nascido, caso a mãe seja\ndiagnosticada com tuberculose pulmonar bacilífera, a amamentação deve ser interrompida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-183919","number":"183919","sourceNumber":"183919","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Tendo como referência as diretrizes da Política Nacional de Promoção da Saúde\n(PNPS), da Política Nacional de Atenção\nBásica (PNAB), da Política Nacional de Alimentação e\nNutrição (PNAN), da Política Nacional de Promoção, Proteção e Apoio ao Aleitamento Materno e da\nRede Cegonha, julgue o item seguinte. Não há restrição à amamentação por portadora de doenças\nde Chagas na fase aguda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-183925","number":"183925","sourceNumber":"183925","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Tendo como referência as diretrizes da Política Nacional de Promoção da Saúde\n(PNPS), da Política Nacional de Atenção\nBásica (PNAB), da Política Nacional de Alimentação e\nNutrição (PNAN), da Política Nacional de Promoção, Proteção e Apoio ao Aleitamento Materno e da\nRede Cegonha, julgue o item seguinte. A vacinação contra hepatite B e a administração de\nimunoglobulina específica (IGHAHB) à mãe após o parto não eliminam o risco de transmissão da\ndoença via leite materno.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-157998","number":"157998","sourceNumber":"157998","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Mãe deseja saber a respeito da altura final que o filho dela, de 12 anos de idade,\npoderá ter. Sabendo-se que a estatura da mãe\né de 1,69 m. e a do pai de 1,86 m. a provável altura\ndo adolescente, quando adulto, será de, aproximadamente:","options":{"A":"178 cm.","B":"180 cm.","C":"184 cm.","D":"186 cm.","E":"189 cm."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-154482","number":"154482","sourceNumber":"154482","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A respeito do crescimento e desenvolvimento físico da criança no primeiro ano de vida,\né possível afirmar que:","options":{"A":"A criança alcança o dobro do peso de nascimento por volta de 6 meses e o comprimento\naumenta em 50%.","B":"Entre 3 e 4 meses, o ganho ponderal esperado é de 20 g/dia e o peso está em torno do dobro do\npeso de nascimento.","C":"Ao final do primeiro ano de vida, o peso de nascimento encontra- se triplicado e o perímetro\ncefálico com um aumento de 15 cm.","D":"Aos 12 meses, a circunferência cefálica apresenta um aumento de 50% em relação a medida do\nnascimento.","E":"Lactentes de termo têm até a primeira semana de vida para recuperar o peso de nascimento."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-154494","number":"154494","sourceNumber":"154494","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Sobre o desenvolvimento neuropsicomotor, o pediatra deve estar atento se seu\npaciente aos 7 meses é capaz de:","options":{"A":"Transferir objetos entre as mãos.","B":"Dizer palavras como \"mama\" e \"papa\".","C":"Segurar objetos entre o polegar e o indicador.","D":"Responder quando é chamado pelo nome.","E":"Apresentar pensamento simbólico como fingir beber chá em uma xícara."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-159536","number":"159536","sourceNumber":"159536","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O item a seguir apresenta uma situação hipotética seguida de uma assertiva a ser\njulgada a propósito da fisiopatologia, do diagnóstico precoce e do tratamento de doenças em\ncrianças e adolescentes. Um recém-nascido foi diagnosticado com síndrome de\n\nBeckwith-Wiedemann. Nesse caso, ele deverá ser submetido ao rastreamento ultrassonografico de\nabdome a cada três meses até completar\noito anos de idade e a dosagem sérica de\nalfafetoproteína a cada três meses até os quatro anos de idade, para detecção precoce de\nhepatoblastoma e tumor de Wilms, para os quais o recém-nascido apresenta predisposição.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-159619","number":"159619","sourceNumber":"159619","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Com relação a aspectos técnicos e éticos do planejamento familiar, julgue o próximo\nitem. Caso uma adolescente de dezesseis anos\nde idade, hígida, solicite receita médica de\ncontraceptivo oral, o médico poderá realizar essa prescrição, mesmo que não haja o consentimento\ndos pais da paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-133991","number":"133991","sourceNumber":"133991","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Criança de 1 ano de idade, nascida de parto vaginal, a termo, de gestação sem\nintercorrências, apresenta peso ao nascimento de 3.000 g, estatura de nascimento de 50 cm e\nperímetro cefálico de 35 cm. No momento, possui as medidas antropométricas de peso igual a\n\n9.500 g, estatura de 78 cm e perímetro cefálico de 48 cm. Considerando essa situação hipotética,\nde acordo com a progressão de peso, estatura e\nperímetro cefálico, é CORRETO afirmar que se\ntrata de criança com:","options":{"A":"Baixo ganho de peso, mas com crescimento estatural e de perímetro cefálico esperados para o\nprimeiro ano de vida.","B":"Bom ganho de peso e crescimento estatural esperado para o primeiro ano de vida, mas com\nperímetro cefálico abaixo do esperado para a idade.","C":"Bom ganho de peso e crescimento estrutural e de perímetro cefálico esperados para o primeiro\nano de vida.","D":"Baixo ganho de peso, pouco crescimento estatural e pouco aumento de perímetro cefálico\nesperados para o primeiro ano de vida.","E":"Baixo ganho de peso, pouco crescimento estatural, mas com perímetro cefálico esperado para o\nprimeiro ano de vida."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-133941","number":"133941","sourceNumber":"133941","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Criança de 2 anos de idade é levada à consulta de puericultura, com queixa de palidez\ne seletividade alimentar. Traz hemograma de rotina\ncom hemoglobina de 10,3 g/dL. Considerando\nessa situação hipotética, em relação à anemia ferropriva na infância, assinale a alternativa\ncorreta.","options":{"A":"A criança não possui anemia ferropriva, já que a faixa etária de 2 anos de idade, somente é\nconsiderado anemia uma hemoglobina menor de 10 g/dL.","B":"Essa anemia caracteriza-se por ferritina e ferro séricos baixos, microcitose, hipocromia,\nanisocitose e reticulócitos aumentados.","C":"Deve-se ser realizado a reposição de ferro elementar na dose de 3-6 mg/Kg/dia até oito\nsemanas após a normalização da hemoglobina.","D":"Essa anemia não dever ser tratada em crianças menores de 2 anos de idade, e sim deve-se\nofertar maior carga de alimentos ricos em\nferro.","E":"Na tentativa de reduzir o risco dessa anemia dos lactentes a termo, AIG e em aleitamento\nmaterno exclusivo, a profilaxia com uso de ferro\noral deve ser realizada desde o nascimento, com\ndose de 1 mg/Kg/dia de ferro elementar, até os 2 anos de idade."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-129076","number":"129076","sourceNumber":"129076","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"No que diz respeito ao tema \"alimentação saudável\", assinale a alternativa CORRETA:","options":{"A":"Gordura trans e gordura vegetal hidrogenada são semelhantes, pois o fato de não haver gordura\ntrans na tabela nutricional não impede que\no produto contenha gordura vegetal hidrogenada.","B":"Além de verificar na tabela nutricional, outra maneira de perceber a quantidade de sódio no\nalimento é o gosto salgado, pois, proporcionalmente à sua quantidade, o produto ficará salgado.","C":"A substituição do sal por orégano, salsa e manjericão não deve ser incentivada, pois essas\nervas ocasionam outros tipos de danos à saúde, às\nvezes até piores que os ocasionados pelo sal.","D":"A tabela nutricional, obrigatória nos alimentos processados, contém a quantidade de nutrientes\nem ordem crescente de concentração.","E":"Alimento diet e (ou) light é a melhor opção, pois sempre é menos calórico."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-129061","number":"129061","sourceNumber":"129061","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O Ministério da Saúde recomenda que alimentos in natura ou minimamente\nprocessados sejam a base da alimentação.\nConsiderando essa informação, assinale a alternativa\nque apresenta exemplo de alimento ultraprocessado que deve ser evitado:","options":{"A":"Milho em conserva.","B":"Pêssego em calda.","C":"Leite longa vida.","D":"Barrinha de cereais.","E":"Carne de gado."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-104774","number":"104774","sourceNumber":"104774","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Assinale a alternativa que apresenta a conduta CORRETA de alimentação saudável\npara crianças menores de dois anos de idade:","options":{"A":"Administrar vitamina D aos lactentes que não são amamentados ao seio materno.","B":"Estimular o consumo de leite de vaca e seus derivados no segundo ano de vida.","C":"A alimentação comum da família só deve ser ofertada à criança após os dois anos de idade.","D":"Lactentes e crianças jovens não têm capacidade de autorregular a ingestão calórica, por isso\nnão emitem sinais de saciedade, devendo a alimentação ter quantidades estabelecidas.","E":"A administração de vitamina A, na forma de megadoses, somente deve ser realizada com a\ncomprovação laboratorial de sua hipovitaminose."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-111313","number":"111313","sourceNumber":"111313","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"As características do desenvolvimento puberal ocorrem na seguinte ordem:","options":{"A":"Pubarca, velocidade máxima de crescimento telarca, menarca.","B":"Velocidade do crescimento máximo, pubarca, telarca e menarca.","C":"Telarca, menarca, pubarca, velocidade máxima de crescimento.","D":"Telarca, pubarca, velocidade máxima de crescimento, menarca.","E":"Pubarca, telarca, menarca, velocidade máxima de crescimento."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-111358","number":"111358","sourceNumber":"111358","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma criança do sexo feminino, de 11 meses de idade, é levada ao pediatra por falta de\napetite e palidez. História de prematuridade e aleitamento materno exclusivo até os 2 meses de\nidade, sendo então introduzido leite de vaca. Sem icterícia neonatal. Hemograma: hemoglobina =\n7,1 g/dl; hematócrito = 21%; VCM = 55 fl; reticulócitos = 0.5%; leucócitos = 6000/mm³; plaquetas\n700.000/mm³. Assinale a hipótese diagnóstica mais provável e os exames necessários para a\nconfirmação:","options":{"A":"Esferocitose - fragilidade osmótica.","B":"Anemia ferropriva - eletroforese de hemoglobina.","C":"Talassemia - dosagem de hemoglobina fetal.","D":"Deficiência de G6PD - dosagem de G6PD.","E":"Anemia ferropriva - dosagem de ferro sérico e ferritina."},"answer":"E","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-111314","number":"111314","sourceNumber":"111314","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A puberdade no sexo masculino é iniciada por:","options":{"A":"Surgimento de pelos pubianos.","B":"Surgimento de pelos axilares.","C":"Crescimento do pênis.","D":"Crescimento do testículo.","E":"Estirão do crescimento."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-111325","number":"111325","sourceNumber":"111325","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menino com 2 meses de idade é levado à uma Unidade Básica de Saúde, pois a mãe\nestá muito preocupada com o aumento de suas mamas. Ao examiná-lo, o médico detecta tecido\nmamário hipertrofiado, com mamas com diâmetro de cerca de 2,5 cm. O médico deve orientar:","options":{"A":"Observação, pois a ginecomastia é transitória e decorrente de estimulação pelos hormônios\nmaternos.","B":"Observação, pois a ginecomastia é um achado raro, porém benigno em lactentes, tornandose\nproblema estético se persistir até a idade escolar.","C":"Realização de ultrassonografia.","D":"Retirada cirúrgica, pois se trata de criança do sexo masculino, com possibilidade elevada de\ntumor de comportamento maligno.","E":"Realização de dosagem de prolactina e estrógeno, para investigar a presença de tumor produtor\nde um desses hormônios."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-111336","number":"111336","sourceNumber":"111336","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A estatura-alvo (tendência de crescimento) de um menino filho de um pai com 168 cm\nde estatura e de uma mãe com 155 cm é:","options":{"A":"155,0 cm.","B":"161,5 cm.","C":"164,5 cm.","D":"168,0 cm.","E":"169,5 cm."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-111284","number":"111284","sourceNumber":"111284","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Criança escolar, 8 anos, com suspeita de Baixa Estatura Familiar (BEF). O que esperar,\npara esse diagnóstico, da radiografia de\npunho e mão esquerda para idade óssea (IO)?","options":{"A":"IO igual à idade altura.","B":"IO maior que a idade cronológica.","C":"IO igual à idade cronológica.","D":"IO menor que a idade cronológica.","E":"IO igual à idade peso."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-97734","number":"97734","sourceNumber":"97734","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Puérpera no quinto dia após o parto normal, retorna à Unidade Básica de Saúde para\nreavaliação. Na consulta, paciente e recém-nascido apresentam-se em bom estado geral. No\nexame físico materno, mamas ingurgitadas, dolorosas à palpação, edemaciadas, com saída de leite\nà expressão. No decorrer da consulta, a paciente queixa-se de que o bebê \"chora muito\" e acredita\nque seu leite é muito \"fraco\" para ele. A puérpera demonstra preocupação e dúvidas sobre os\nbenefícios da amamentação. A conduta nessa situação deve ser:","options":{"A":"Substituir o leite materno pelo leite artificial, para satisfação do bebê e melhora da ansiedade\nmaterna.","B":"Encorajar a amamentação e orientar a expressão manual do leite, para evitar o ingurgitamento.","C":"Suspender a amamentação pelo quadro clínico de mastite e prescrever antibióticos via oral.","D":"Alternar o leite artificial com o leite materno, para a complementação nutricional do bebê."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-80702","number":"80702","sourceNumber":"80702","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um bebê que nasceu a termo de parto normal, sem intercorrências, com 3,2 kg, e que\ndurante os primeiros onze meses de vida sempre esteve no percentil 50 (p50) da curva de peso, é\nlevado pela mãe para a consulta de puericultura de um ano de idade. Com base no texto, assinale\na alternativa que apresenta o peso esperado do bebê.","options":{"A":"12,8 kg","B":"12 kg","C":"11,6 kg","D":"9,6 kg","E":"8 kg"},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-80709","number":"80709","sourceNumber":"80709","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Um bebê que nasceu a termo de parto normal, sem intercorrências, com 3,2 kg, e que\ndurante os primeiros onze meses de vida sempre esteve no percentil 50 (p50) da curva de peso, é\nlevado pela mãe para a consulta de puericultura de um ano de idade. Considerando que o bebê\nnasceu com 50 cm e que durante os primeiros onze meses de vida sempre esteve no percentil 50\n(p50) da curva de estatura, na consulta de puericultura de um ano de idade, estará com:","options":{"A":"65 cm.","B":"70 cm.","C":"75 cm.","D":"80 cm.","E":"90 cm."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-75524","number":"75524","sourceNumber":"75524","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Primípara, no 5º dia pós-parto, procura a Unidade Básica de Saúde queixando-se de\ndor e inchaço nas mamas, com dificuldade\npara amamentar. Relata que seu filho chora\nconstantemente e que ele é preguiçoso para sugar o leite. Ao exame físico apresenta mamas\nvolumosas, brilhantes, endurecidas, doloridas, com calor local. As aréolas apresentam-se tensas e\nos mamilos planos. Com base nos dados clínicos apresentados, a conduta correta a ser orientada\né:","options":{"A":"manter o aleitamento exclusivo sob livre demanda;\n\ncorrigir a pega; aumentar a frequência das mamadas; realizar ordenha manual antes da mamada\npara diminuir a tensão da aréola; e recomendar\nuso de sutiã com alças que suspendam as mamas.","B":"introduzir antibioticoterapia associada com analgésicos e anti-inflamatórios não hormonais;\nadministrar compressas frias nas mamas; e\nsuspender a amamentação até que se garanta uma\nboa pega e ocorra melhora dos sinais flogísticos nas mamas.","C":"suspender a amamentação até que se garanta uma boa pega e para que ocorra melhora dos\nsinais flogísticos nas mamas; administrar\ncompressas mornas para reduzir os aglomerados de leite\nnos ductos; e realizar a ordenha manual.","D":"suspender o aleitamento exclusivo até haver a melhora do processo inflamatório; administrar\nanalgésicos e anti-inflamatórios; iniciar exercícios para correção dos mamilos planos; e realizar a\nordenha manual.","E":"introduzir antibioticoterapia; realizar compressas\n\nmornas para reduzir os aglomerados de leite nos ductos; e manter o aleitamento exclusivo sob livre\ndemanda, após correção da pega."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-75474","number":"75474","sourceNumber":"75474","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Estudante, com 9 anos de idade, vem apresentando dificuldades de aprendizagem e\natos de indisciplina frequentes em relação\naos professores, principalmente aos novos, que tiveram\nde ser substituídos por três vezes nos últimos dois meses, por problemas de saúde. A escola\nsolicitou que a mãe procurasse um \"neurologista\" para o menino, esta levou a criança inicialmente\nao pediatra, referindo que ele tinha boa índole, ajudava nas tarefas de casa e tomava conta do\nirmão com 5 anos. Notou que tem apresentado notas mais baixas e reclama muito dos professores\nultimamente. Nega atos indisciplinares que não sejam próprios da idade. O menino não gosta de\nficar na rua, costuma brincar em casa e jogar futebol no final de semana com os amigos e primos.\nEm casa não tem computador e a mãe acha que esse é o motivo do mau desempenho escolar. A\ncriança perdeu o pai há um ano, vítima de atropelamento. Ao exame físico, o pediatra não\nencontrou alterações. Com base nessa narrativa, a suspeita clínica e a conduta do pediatra devem\nser:","options":{"A":"transtorno de distúrbio de comunicação\n(provavelmente linguagem); encaminhar para\navaliação com o neurologista infantil.","B":"déficit de atenção e hiperatividade; encaminhar para avaliação com o neurologista e com o\npsiquiatra infantil.","C":"comportamento aceitável para a idade; avaliar melhor com seguimento e então decidir se\nencaminha ao psiquiatra infantil.","D":"comportamento antissocial decorrente da perda\n\nfamiliar; encaminhar de imediato para avaliação com o psiquiatra infantil.","E":"transtorno de conduta (comportamento desafiador\nopositor); encaminhar para avaliação com o psiquiatra infantil."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-75538","number":"75538","sourceNumber":"75538","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menino com 7 meses de idade é levado pela mãe a Unidade Básica de Saúde em\nconsulta de Puericultura. A mãe está\npreocupada, pois acha que ele é mais lento que os irmãos.\nApós anamnese detalhada, o pediatra realizou o exame físico e afirmou que o exame neurológico e\no desenvolvimento neuropsicomotor estavam condizentes com a idade. O que o pediatra observou\nem relação a linguagem, motricidade, comportamento adaptativo e reflexos arcaicos,\nrespectivamente, para fazer tal afirmação?","options":{"A":"Emissão espontânea sem intenção imitativa;\n\nsustentação cefálica; dirige a mão para objetos; reflexo de Moro.","B":"Emissão bissilábica significante; engatinha durante a consulta; preensão palmar em pinça;\nreflexo de Landau II.","C":"Emissão espontânea sem intenção imitativa; senta-se com apoio; preensão palmar voluntária;\nreflexo de Moro incompleto.","D":"Ecolalia; senta-se sem apoio; muda objeto de uma mão para outra; reflexo de preensão plantar.","E":"Emissão de palavras-frase; capacidade de andar com apoio observada na consulta; bate\npalmas; reflexo do paraquedista."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-351606","number":"351606","sourceNumber":"351606","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Acerca do aleitamento do lactente, assinale V para as afirmativas verdadeiras e F para\nas falsas. ( ) O aleitamento exclusivo ao\nseio materno é preconizado até os 6 meses, não devendo\nser complementado por alimentos sólidos, sendo recomendado apenas água filtrada entre as\nmamadas. ( ) O leite humano maduro conta soro/caseína otimizada, havendo predomínio da\nconcentração lactoalbumina sobre a concentração de caseína, proporcionando melhor\ndigestibilidade. ( ) Em casos em que o leite materno se apresente como insuficiente, fórmulas de\nprimeiro semestre parcialmente hidrolisadas demonstram eficácia semelhante ao leite materno, no\ntocante à proteção imunológica. ( ) O aleitamento ao seio materno está expressamente\ncontraindicado em casos em que de mãe acometida por hepatite B aguda ou cronificada. Assinale\na alternativa que apresenta a sequência CORRETA.","options":{"A":"F ? V ? F ? F","B":"V ? V ? F ? F","C":"V ? V ? V ? F","D":"F ? V ? F ? V"},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-352159","number":"352159","sourceNumber":"352159","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A mãe de uma bebê com 10 dias de vida, vem à primeira consulta com muitas dúvidas\nsobre a amamentação. Das informações que\nela recebeu das pessoas que a estão apoiando nessa\netapa, qual é a correta?","options":{"A":"É recomendável que o bebê mame com regularidade, de 3 em 3 horas.","B":"É importante que a criança esvazie a mama por completo, pois o leite do final da mamada\ncontém mais calorias e sacia a criança.","C":"A aréola deve ficar bem visível ao redor da boca do bebê e os ruídos feitos com a língua,\ndurante a sucção, indicam uma boa pega.","D":"Para o bebê abocanhar o tecido mamário de forma eficiente, a mãe pode auxiliar segurando a\nmama com os dedos em \"\"forma de tesoura\"\"."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-351602","number":"351602","sourceNumber":"351602","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O aleitamento materno é um processo que envolve interação profunda entre a mãe e\nfilho, com repercussões no estado nutricional da criança, em sua habilidade de se defender de\ninfecções, em sua fisiologia e no seu desenvolvimento cognitivo e emocional, e em sua saúde no\nlongo prazo. Além de todos os benefícios para a criança, o aleitamento também pode trazer\nbenefícios, cientificamente comprovados, à mãe que amamenta, sendo eles, EXCETO:","options":{"A":"Proteção contra câncer de mama.","B":"Redução do risco de diabetes tipo 1.","C":"Diminuição do risco de recaída de esclerose múltipla pós-parto.","D":"Proteção contra câncer de ovário."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-337634","number":"337634","sourceNumber":"337634","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Além de alimentar a criança, o Aleitamento Materno (AM) protege mãe e criança contra\nalgumas doenças e promove o desenvolvimento cognitivo e emocional da criança e o bem-estar\nfísico e psíquico da díade mãe-filho. Sobre o aleitamento materno, assinale a alternativa\nCORRETA:","options":{"A":"Aleitamento Materno Exclusivo (AME) é aquele que a criança recebe somente leite materno,\ndireto da mama ou ordenhado, ou leite humano\nde outra fonte, além de água e bebidas à base de\nágua (chás e infusões).","B":"A mama na gravidez é preparada para a lactação sob a ação de diferentes hormônios, sendo os\nmais importantes a prolactina, que é responsável pela ramificação dos ductos lactíferos, e o\nprogestagênio, responsável pela formação dos lóbulos.","C":"O leite maduro só é secretado por volta do 15° dia pós-parto. Nos primeiros dias, a secreção\nláctea é chamada de colostro, que contém\nmenos proteínas e lipídios do que o leite maduro, e é\nrico em imunoglobulinas, em especial a IgA.","D":"O tempo de permanência na mama em cada mamada não deve ser preestabelecido, pois o\ntempo necessário para esvaziar uma mama varia\nentre os bebês e, em uma mesma criança, pode\nvariar dependendo da fome, do intervalo transcorrido desde a última mamada e do volume de leite\narmazenado na mama, entre outros fatores."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-321174","number":"321174","sourceNumber":"321174","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"M.C.D. 10 anos, comparece à consulta acompanhada do pai que se mostrava\npreocupado com o desenvolvimento de\ncaracterísticas sexuais na filha de forma precoce, mas\nrelatou ausência da menarca. Exame físico evidenciou M4 P3 segundo critérios de Tanner. Sobre a\npuberdade precoce, é CORRETO afirmar que:","options":{"A":"A puberdade precoce central é, na grande maioria dos casos, de origem idiopática, não\npossuindo também influência genética no seu desencadeamento.","B":"A puberdade precoce pode ser de origem central, independente das gonadotrofinas, ou\nperiférica, dependente das gonadotrofinas.","C":"A dosagem de LH basal, a radiografia de punho e mão não dominantes para avaliação da idade\nóssea, e a ultrassonografia pélvica para avaliação do volume ovariano e uterino, são exames\nindicados para complementar a avaliação em meninas.","D":"No caso em questão deve-se tranquilizar o pai quanto a possibilidade de puberdade precoce,\numa vez que para meninas ela ocorre quando o\ndesenvolvimento dos caracteres sexuais\nsecundários acontece, antes dos 9 anos."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-320438","number":"320438","sourceNumber":"320438","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Mãe de lactente de quatro meses em aleitamento materno exclusivo, procura\norientação porque volta a trabalhar em 15 dias.\nA orientação adequada é que a mãe retire seu leite\ne armazene em frascos de vidro com tampa plástica na geladeira:","options":{"A":"Por até 1 horas ou congelador/freezer por até três semanas; oferecer preferencialmente por\ncopinho.","B":"Por até duas horas ou congelador/freezer por até 12 horas; oferecer preferencialmente por\ncopinho.","C":"Por até 12 horas ou congelador/freezer por até duas semanas; oferecer preferencialmente por\ncopinho.","D":"Por até 12 horas ou congelador/freezer por até duas semanas; oferecer preferencialmente por\nmamadeira.","E":"Por até 24 horas ou congelador/freezer por até quatro semanas; oferecer preferencialmente por\nmamadeira."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-320440","number":"320440","sourceNumber":"320440","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Primípara procura o posto de saúde porque está apresentando ?dor no bico do peito?\nao amamentar, desde a segunda semana pós-parto.\nNo exame da mama, o pediatra identifica\nfissura mamilar. A conduta mais importante neste caso é:","options":{"A":"avaliar a mamada e corrigir a técnica de amamentar.","B":"amamentar em diferentes posições.","C":"passar o próprio leite nos mamilos após as mamadas e secar ao ar livre.","D":"usar, na aréola e nos mamilos, produtos (cremes ou pomadas) cicatrizantes.","E":"expor as mamas ao sol 4x ao dia."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-336279","number":"336279","sourceNumber":"336279","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Menino, 5 anos, chega ao ambulatório com queixa principal de aumento peniano há 1\nano associado ao rápido crescimento de pêlos\npubianos e voz grossa. História patológica pregressa\nde investigação de vômitos esporádicos desde os 2 anos de idade com o gastropediatra sendo\ndescartado refluxo gastro-esofágico. História familiar negativa para casos semelhantes a sua\nqueixa atual. Exame físico: peso 20,5 kg altura 117 cm , testículos de 6 cm3 cada, consistência\nfibroelástica, contornos regulares, ausência de sinais flogísticos. Pênis 8 cm ( maior que P 95 para\ntamanho de pênis para idade). Tanner G3P3. A principal hipótese diagnóstica é:","options":{"A":"Puberdade precoce central idiopática, já que apresenta todos os carácteres sexuais\ndesenvolvidos e este representa o principal\ndiagnóstico de puberdade precoce entre os acometidos\ndo sexo masculino.","B":"Tumor de sistema nervoso central com secreção de GnRH.","C":"Neurofibromatose tipo 1, que a criança ainda não apresentou neurofibromas devido a sua pouca\nidade.","D":"Hiperplasia suprarrenal congênita forma clássica perdedora de sal já que apresenta história de\nvômitos."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-334754","number":"334754","sourceNumber":"334754","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O acompanhamento do peso, altura/comprimento e perímetro craniano, este nos 3\nprimeiros anos de vida, pode orientar o médico sobre as condições de saúde de seu paciente. No\nacompanhamento do crescimento é correto afirmar:","options":{"A":"Se o recém-nascido apresenta um comprometimento só do peso, é maior a probabilidade de um\nagravo ter ocorrido nos meses finais da gestação.","B":"Crianças nascidas com peso inferior a 3 kg são denominadas de baixo peso.","C":"O crescimento intrauterino é predominantemente dependente do potencial genético da criança.","D":"A criança cresce aproximadamente 45 cm e duplica de peso em torno do seu primeiro\naniversário."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-334756","number":"334756","sourceNumber":"334756","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O aleitamento materno é a primeira prática alimentar a ser recomendada para a\npromoção da saúde e adequado desenvolvimento infantil. No aleitamento materno é correto\nafirmar:","options":{"A":"O leite materno tem mais caseína do que proteína do soro, o que leva a capacidade de provocar\nesvaziamento gástrico mais lento, deixando a criança mais saciada.","B":"Em recém-nascidos pré-termos, o leite materno deve ser evitado devido ao risco aumentado de\nenterocolite necrosante.","C":"A composição e aspecto do leite materno é bastante heterogêneo e varia com a alimentação,\nidade e raça da mãe.","D":"O colostro contém mais proteínas e menos lipídios do que o leite maduro e é rico em\nimunoglobulinas, em especial a IgA."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-334759","number":"334759","sourceNumber":"334759","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Na anemia ferropriva é correto afirmar:","options":{"A":"São fatores de risco para anemia ferropriva crianças grandes para idade gestacional (GIG), ou\ncom peso superior a 4 kg no nascimento, e\nlactente em crescimento lento.","B":"São fatores de risco para anemia ferropriva o clampeamento do cordão umbilical após cinco\nminutos de vida.","C":"Nos lactentes em aleitamento materno exclusivo, sem fatores de risco, recomenda-se a\nsuplementação medicamentosa profilática a partir\ndos 180 dias de vida, até o final do segundo ano.","D":"Em recém-nascidos prematuros (idade gestacional inferior a 39 semanas) ou com peso inferior a\n2.500g, o início da suplementação de ferro deve ocorrer ao nascimento."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-335110","number":"335110","sourceNumber":"335110","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"As crianças frequentemente utilizam a linguagem não verbal para se comunicarem, por\nexemplo, por meio de irritabilidade, agressividade, regressão, dores em geral, queda no rendimento\nescolar. A esse respeito, analise os aspectos a seguir. I. Dificuldade específica de aprendizagem\nII.\nMaus-tratos físicos e / ou emocionais III. Negligência IV. Alto nível de estresse dos pais É(são)\naspecto(s) que deve(m) ser investigado(s) diante de uma criança com essas manifestações","options":{"A":"I, apenas.","B":"I e II, apenas.","C":"II e III, apenas.","D":"I, II, III e IV."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-306705","number":"306705","sourceNumber":"306705","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Além de alimentar a criança, o aleitamento materno protege mãe e criança contra\nalgumas doenças e promove o desenvolvimento\ncognitivo e emocional da criança e o bem-estar\nfísico e psíquico da díade mãe- filho. Sobre o leite materno, assinale a alternativa CORRETA:","options":{"A":"A água contribui com quase 90% da composição do leite materno, o que garante o suprimento\ndas necessidades hídricas de uma criança em\naleitamento materno exclusivo.","B":"Nos primeiros dias de vida, a secreção láctea é chamada de colostro, que contém mais lipídeos\ne menos proteínas do que o leite maduro, e é\nrico em imunoglobulinas, em especial a IgA.","C":"A concentração de gordura no leite (e consequentemente o teor energético) reduz no decorrer\nde uma mamada. Assim, o leite do início da\nmamada (leite anterior) é mais rico em energia e sacia\nmelhor a criança.","D":"Alguns dos fatores de proteção do leite materno são total ou parcialmente ativados pelo calor,\nrazão pela qual o leite humano pasteurizado (submetido a uma temperatura de 62,5°C por 30\nminutos) tem o mesmo valor biológico que o leite cru."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-291930","number":"291930","sourceNumber":"291930","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação à ginecomastia, é INCORRETO afirmar que:","options":{"A":"Não há diferenças quanto à responsividade do tecido mamário masculino e feminino ao\nestrogênio.","B":"A maioria dos estrogênios circulantes no homem, deriva da conversão extra gonadal dos\nprecursores de estrogênios pelos tecidos\nextra-gonadais como pele, fígado, tecido gorduroso e\nmúsculo.","C":"Uma das maneiras de prevenir o desenvolvimento da ginecomastia é a administração de baixas\ndoses de radioterapia naqueles pacientes que devem receber estrogênio devido ao câncer de\npróstata.","D":"O percentual de ginecomastia induzida por drogas está em torno de 40-50% dos casos."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-291931","number":"291931","sourceNumber":"291931","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação à puberdade, assinale a alternativa INCORRETA:","options":{"A":"A puberdade é definida como o período durante o qual começam a se desenvolver as\ncaracterísticas sexuais secundárias e é obtida a capacidade de reprodução sexual.","B":"O estadiamento proposto por Tunner & Marshall dos pelos pubianos, está relacionado à\nquantidade e à sua distribuição sendo que no estádio I não há pelos pubianos sexualmente\nestimulados presentes, na área genital.","C":"A puberdade tardia existe em adolescentes do sexo feminino que não desenvolvem quaisquer\ncaracterísticas sexuais secundárias aos 13 anos, não tiveram menarca aos 16 anos ou nas quais\nse passaram 5 anos ou mais desde o início do desenvolvimento puberal ter tido a menarca.","D":"A puberdade precoce é o desenvolvimento puberal que se inicia antes de 8 anos e pode ser\ncaracterizado de várias formas como issosexual, heterossexual, verdadeira e\n\nhipotalâmica-hipofisária."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-291627","number":"291627","sourceNumber":"291627","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A mãe de um lactente de 4 meses, em amamentação exclusiva, procura orientação\nporque vai voltar a trabalhar em 15 dias. A\norientação adequada é que a mãe retire seu leite e\narmazene em frascos de vidro com tampa plástica na geladeira:","options":{"A":"Por até duas horas na geladeira ou 12 h congelador; oferecer preferencialmente por copinho.","B":"Por até 12 h no refrigerador e até duas semanas no congelador; oferecer preferencialmente no\ncopinho.","C":"Por até 48 horas no Refrigerador e duas semanas no congelador; preferencialmente por\ncopinho.","D":"Por até 12 horas refrigerador e duas semanas congelador; oferecer preferencialmente por\nmamadeira.","E":"Por até 24 horas no refrigerador ou congelador por até quatro semanas; oferecer\npreferencialmente por mamadeira."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-291937","number":"291937","sourceNumber":"291937","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Paciente sexo feminino de 11 anos é trazida à consulta pediátrica pela avó materna\ndevido à preocupação pela neta estar\n?virando moça? muito rápido, embora ainda não havia\nmenstruado. Ao exame físico, a paciente estava em M3 P4 segundo os critérios de Tanner. Sobre o\ncaso descrito, é CORRETO que:","options":{"A":"Após anamnese e exame físico completo, devemos tranquilizar a avó sobre a queixa trazida na\nconsulta, uma vez que, por definição, a puberdade precoce ocorre quando o desenvolvimento dos\ncaracteres sexuais secundários acontece antes dos 8 anos em meninas e antes dos 9 anos em\nmeninos.","B":"Deve-se dosar as gonadotrofinas, pois possivelmente se trata de um quadro de puberdade\nprecoce central.","C":"Deve-se dar à avó a possibilidade de intervenção farmacológica para o bloqueio hormonal da\npuberdade.","D":"Embora a menarca, o primeiro marco da puberdade nas meninas, ainda não tenha ocorrido na\npaciente, o desenvolvimento não parece patológico."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-306721","number":"306721","sourceNumber":"306721","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Lactente do sexo masculino, nascido prematuro com 28 semanas de idade gestacional,\nhoje, com 9 meses de idade, vem para consulta\nde puericultura. Na avaliação do desenvolvimento\nforam observados os seguintes marcos presentes: brinca de esconde-achou, rola no leito e leva\nobjetos a boca. Você nota que a criança não se senta sem apoio, não transfere objetos de uma\nmão para a outra e não apresenta o movimento de pinça. O desenvolvimento deste lactente está:","options":{"A":"atrasado para a idade cronológica e adequado para a idade corrigida pela prematuridade.","B":"atrasado para a idade cronológica e idade corrigida pela prematuridade.","C":"adequado para a idade cronológica e atrasado para a idade corrigida pela prematuridade.","D":"adequado para a idade cronológica e idade corrigida pela prematuridade."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-291943","number":"291943","sourceNumber":"291943","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A Organização Mundial da Saúde (OMS) recomenda o Aleitamento Materno (AM) por 2\nanos ou mais, sendo esse de forma exclusiva\nnos primeiros 6 meses. Essa recomendação se deve\na importância que o Leite Materno (LM) ter não apenas os aspectos nutricionais, mas também\nimunológicos e do desenvolvimento. Sobre a composiçao do LM, é CORRETO afirmar que:","options":{"A":"Apesar de rico em nutrientes, a parcela do leite que corresponde a água é baixa, sendo assim\nimportante para a lactante sempre complementar o aleitamento ofertando água para o neonato, de\nforma a manter a sua hidratação.","B":"O teor energético do leite não se mantem fixo durante toda a mamada, sendo sua concentração\nde gorduras no leite posterior mais alto, o que\ntorna muito importante a criança fazer um bom\nesvaziamento da mama, garantindo uma maior saciedade e energia.","C":"O leite maduro só é secretado por volta do 10º dia pós-parto, sendo nos primeiros dias a\nsecreção chamada colostro. São caracteristicas\ndesse colostro concentrações menores de\nproteinas e maiores de gorduras, quando comparado ao leite maduro, e também seu alto teor de\nimunoglobulinas, principalmente a IgA.","D":"O leite materno, embora rico em ferro, contém baixas concentrações das vitaminas K e D, o que\nfaz com que a suplementação dessas vitaminas sejam recomendadas. A vitamina K é\nsuplementada ao nascer, e a vitamina D é suplementada diariamente até os 18 meses, para\ncrianças com baixa exposição regular ao sol."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-304875","number":"304875","sourceNumber":"304875","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Existe uma ampla variação fisiológica em idade para o início da puberdade que\ndepende do eixo\nhipotalâmico-hipofisário-gonadal. A situação que deve ser investigada é:","options":{"A":"Menina que não apresenta telarca aos 14 anos de idade.","B":"Menino que não apresenta sinais de puberdade aos 12 anos.","C":"Menina com adrenarca aos oito anos de idade e telarca aos dez anos.","D":"Menino com aumento do volume testicular para 4mm³ aos nove anos."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-304880","number":"304880","sourceNumber":"304880","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"A mãe de um lactente de quatro meses em aleitamento materno exclusivo procura\norientação porque vai trabalhar em 15 dias. A\norientação adequada é que a mãe retire seu leite e\narmazene em frascos de vidro com tampa plástica:","options":{"A":"Na geladeira por até 2 horas ou congelador/freezer por até 12 horas; oferecer preferencialmente\npor copinho.","B":"Na geladeira por até 12 horas ou congelador/freezer por até duas semanas; oferecer\npreferencialmente por copinho.","C":"Na geladeira por até 12 horas ou congelador/freezer por até duas semanas; oferecer\npreferencialmente por mamadeira.","D":"Na geladeira por até 24 horas ou congelador/freezer por até quatro semanas; oferecer\npreferencialmente por mamadeira."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-291963","number":"291963","sourceNumber":"291963","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Sobre aleitamento materno, assinale a alternativa INCORRETA:","options":{"A":"A proteção do leite materno contra mortes infantis é maior quanto menor é a criança, e a\namamentação previne mais mortes entre as crianças de menor nível socioeconômico.","B":"O exercício que a criança faz para retirar o leite da mama é muito importante para o\ndesenvolvimento adequado de sua cavidade oral,\npropiciando uma melhor conformação do palato\nduro.","C":"Oferecer à criança amamentada água ou chás, prática considerada inadequada até pouco\ntempo atrás, pode reduzir o risco de desidratação nos primeiros seis meses.","D":"Estudos mostram que a amamentação exclusiva nos primeiros meses de vida diminui o risco de\nalergia à proteína do leite de vaca, de dermatite atópica e de outros tipos de alergias, incluindo\nasma e sibilos recorrentes."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-314074","number":"314074","sourceNumber":"314074","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Em relação à idade em que ocorre a puberdade, numerar a 2ª coluna de acordo com a\n1ª e, após, assinalar a alternativa que apresenta a sequência CORRETA: (1) Atraso puberal. (2)\nPuberdade precoce. (3) Puberdade normal. ( ) Ocorre quando a puberdade feminina se inicia, em\nmédia, aos 9,7 anos, e a dos meninos, 10,9 anos. ( ) Ocorre quando o desenvolvimento dos\ncaracteres sexuais secundários acontece antes dos 8 anos em meninas e antes dos 9 anos em\nmeninos. ( ) Ocorre quando há falta de desenvolvimento dos caracteres sexuais secundário aos 13\nanos de idade nas meninas, e 14 anos nos meninos, ou seja, ausência de broto mamário e\ntestículo menos que 4mL, respectivamente.","options":{"A":"1 - 2 - 3.","B":"3 - 2 - 1.","C":"2 - 3 - 1.","D":"2 - 1 - 3.","E":"3 - 1 - 2"},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-314075","number":"314075","sourceNumber":"314075","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"De acordo com CAMPOS, BURNS e LOPEZ, a gravidez na adolescência tem sido\nconsiderada um problema de saúde pública pelas repercussões clínicas, emocionais e sociais que\nacarreta para essa faixa etária, particularmente quando ocorre abaixo de 15 anos. Em relação à\ngestação de adolescentes, analisar a sentença abaixo: A negação da atividade sexual e a\nirregularidade menstrual não devem excluir o diagnóstico, pois a gravidez ainda é o diagnóstico\nmais comum em adolescentes com amenorreia secundária (1ª parte). Durante a gestação, a\nadolescente ainda está se adaptando emocionalmente às suas próprias características e formatos,\ne o corpo, que ainda está em transformação, sofre novas mudanças de tamanho e forma (2ª parte).\nA gravidez na adolescência pode cursar com sintomas tradicionais de gravidez: enjoo matinal,\nvômitos, mamas dolorosas, ganho de peso, estrias e amenorreia (3ª parte). A sentença está:","options":{"A":"Totalmente correta.","B":"Correta somente em sua 3ª parte.","C":"Correta somente em suas 1ª e 2ª partes.","D":"Correta somente em suas 2ª e 3ª partes.","E":"Totalmente incorreta."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-314088","number":"314088","sourceNumber":"314088","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"De acordo com CAMPOS, BURNS e LOPEZ, além de alimentar a criança, o\naleitamento materno (AM) protege mãe e criança contra algumas doenças e promove o\ndesenvolvimento cognitivo e emocional da criança e o bem-estar físico e psíquico da díade\n\nmãe-filho. Assinalar a alternativa que classifica CORRETAMENTE o padrão de aleitamento quando\na criança recebe somente leite materno, direto\nda mama ou ordenhado, ou leite humano de outra\nfonte, sem outros líquidos ou sólidos:","options":{"A":"Aleitamento Materno Predominante.","B":"Aleitamento Materno Misto.","C":"Aleitamento Materno Exclusivo.","D":"Aleitamento Materno Complementado.","E":"Aleitamento Materno Parcial."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-266359","number":"266359","sourceNumber":"266359","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Avaliar o crescimento da criança é uma atividade fundamental da prática pediátrica e a\nmonitoração detecta antecipadamente a desnutrição e alerta para outros agravos que podem estar\nafetando o crescimento das crianças. No acompanhamento do crescimento é CORRETO afirmar:","options":{"A":"As crianças nascidas com peso menor que 2.000 gramas são consideradas baixo peso e as\ncrianças nascidas com peso acima de 2.000 gramas são consideradas peso normal.","B":"Em torno do quarto mês de vida, o peso do nascimento duplica e próximo ao primeiro\naniversário, o peso triplica.","C":"Ao nascer, se o recém-nascido apresenta comprometimento somente da estatura, é maior a\nprobabilidade de o agravo ter ocorrido nos meses finais da gestação e se houver uma diminuição\nno peso, é mais provável que o agravo tenha ocorrido há mais tempo.","D":"É alta a correlação do tamanho ao nascer em relação à estatura final e o crescimento\nintrauterino é dependente do seu potencial genético."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-266360","number":"266360","sourceNumber":"266360","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O aleitamento materno, além de alimentar a criança, protege mãe e filho contra\nalgumas doenças e promove o desenvolvimento\ncognitivo e emocional da criança e o bem-estar\nfísico e psíquico da díade mãe-filho. No aleitamento materno é CORRETO afirmar:","options":{"A":"A composição e aspecto do leite materno é bastante heterogêneo e varia com a alimentação,\nidade e raça da mãe.","B":"Nos primeiros dias de amamentação, a secreção láctea é chamada de colostro, que contém\nmais lipídio e menos proteína do que o leite\nmaduro, e é rico em imunoglobulinas, em especial a\nIgG.","C":"O leite materno contém altas concentrações de vitamina K, vitamina D e ferro.","D":"Alguns dos fatores de proteção do leite materno são totalmente ou parcialmente inativados pelo\ncalor, razão pela qual o leite humano pasteurizado (submetido a uma temperatura de 62,5ºC por 30\nminutos) não tem o mesmo valor biológico que o leite cru."},"answer":"D","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-257359","number":"257359","sourceNumber":"257359","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"O aleitamento materno exclusivo é a alimentação ideal para todo lactente até o sexto\nmês, porém existem algumas situações que não\nse recomenda o aleitamento materno. Lembrando\nque a suspensão do aleitamento deve ser avaliada caso a caso. Dentre as CONTRAINDICAÇÕES\nclássicas para o aleitamento materno está a/o:","options":{"A":"Covid-19.","B":"Mastite.","C":"Galactosemia.","D":"Epstein Barr."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-260690","number":"260690","sourceNumber":"260690","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Suplementação profilática de ferro para lactente nascido a termo com peso adequado\npara a idade gestacional, que esteja em\naleitamento materno exclusivo, deve ser iniciada:","options":{"A":"6 meses.","B":"3 meses.","C":"1 ano.","D":"4 meses.","E":"9 meses."},"answer":"A","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-287350","number":"287350","sourceNumber":"287350","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Mãe leva o filho de 14 meses na Unidade Básica de Saúde para avaliação de rotina. A\ncriança está com o desenvolvimento normal. Qual a orientação correta sobre a retirada das fraldas\ne uso do sanitário?","options":{"A":"Esse treinamento já pode começar, pois a criança já senta.","B":"Orientar que o treinamento deve iniciar por volta dos 18 meses, compatível com o\ndesenvolvimento neurológico.","C":"Orientar que o treinamento deve iniciar quando a criança consegue avisar que evacuou.","D":"Orientar que o treinamento deve ocorrer depois dos 03 anos, para evitar traumas."},"answer":"B","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-2-260691","number":"260691","sourceNumber":"260691","collectionBlock":"medcurso:medcurso-pediatria-ped-2","collectionLabel":"Medcurso · PED 2","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 2","subtopic":"","stem":"Uma gestante dá a luz de parto vaginal com 39 semanas e cinco dias. Está tratando\ntuberculose forma pulmonar há um mês, com escarro negativo há três semanas. A amamentação\nao seio deverá ser realizada:","options":{"A":"Utilizando máscara e após 3 doses de isoniazida.","B":"Após realizar a BCG.","C":"Sem restrições.","D":"Após o recém-nascido iniciar isoniazida.","E":"Após o teste tuberculínico da mãe."},"answer":"C","source":"Pediatria/PED 2/PED 2.txt","sourceLabel":"Medcurso · PED 2","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 2","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
